def log_audit(user_name, action, details=None):
    if not SUPABASE_AVAILABLE:
        return
    try:
        supabase.table("audit_log").insert({
            "user_name": user_name,
            "action": action,
            "details": json.dumps(details) if details else None
        }).execute()
    except Exception:
        pass

# -------------------------------
# 6. EMAIL NOTIFICATION
# -------------------------------
def send_email_notification(recipient, subject, body_html, _return_error=False):
    """Send an email. Returns True/False, or (bool, error_str) if
    _return_error=True — used by the Owner Console health check so a
    misconfiguration shows the actual SMTP error instead of a bare
    failure.

    Sends multipart/alternative with a plain-text fallback alongside
    the HTML. Plain text matters here for two practical reasons: some
    site email gateways strip or quarantine HTML-only mail more
    aggressively, and a plain fallback still gets read on a phone with
    a broken mail-app renderer.
    """
    if not recipient:
        return (False, "No recipient") if _return_error else False
    smtp_server = st.secrets.get("SMTP_SERVER")
    smtp_port = st.secrets.get("SMTP_PORT", 587)
    smtp_user = st.secrets.get("SMTP_USER")
    smtp_password = st.secrets.get("SMTP_PASSWORD")
    smtp_from = st.secrets.get("SMTP_FROM", smtp_user)
    if not all([smtp_server, smtp_user, smtp_password]):
        return (False, "SMTP not configured") if _return_error else False
    try:
        import smtplib
        from email.mime.text import MIMEText
        from email.mime.multipart import MIMEMultipart
        plain_text = body_html
        plain_text = re.sub(r"<br\s*/?>", "\n", plain_text, flags=re.I)
        plain_text = re.sub(r"</p>", "\n\n", plain_text, flags=re.I)
        plain_text = re.sub(r"<[^>]+>", "", plain_text)
        plain_text = re.sub(r"\n{3,}", "\n\n", plain_text).strip()
        msg = MIMEMultipart("alternative")
        msg['From'] = smtp_from
        msg['To'] = recipient
        msg['Subject'] = subject
        msg.attach(MIMEText(plain_text, 'plain'))
        msg.attach(MIMEText(body_html, 'html'))
        with smtplib.SMTP(smtp_server, int(smtp_port), timeout=10) as server:
            server.starttls()
            server.login(smtp_user, smtp_password)
            server.send_message(msg)
        return (True, "") if _return_error else True
    except Exception as e:
        _err = f"{type(e).__name__}: {e}"
        log_error(_err, details={"recipient": recipient, "subject": subject},
                  endpoint="send_email")
        return (False, _err) if _return_error else False

# -------------------------------
# 7. SLACK / TEAMS WEBHOOK INTEGRATION
# -------------------------------
def send_slack_notification(message, _return_error=False):
    if not SLACK_WEBHOOK:
        return (False, "Slack webhook not configured") if _return_error else False
    try:
        payload = {"text": message}
        resp = requests.post(SLACK_WEBHOOK, json=payload, timeout=5)
        resp.raise_for_status()
        return (True, "") if _return_error else True
    except Exception as e:
        _err = f"{type(e).__name__}: {e}"
        log_error(_err, endpoint="slack")
        return (False, _err) if _return_error else False

def send_teams_notification(message, _return_error=False):
    """Posts to a Teams incoming webhook using the MessageCard format.

    IMPORTANT, time-sensitive context: Microsoft retired the old-style
    "Office 365 Connector" webhooks in a rollout completing May 22,
    2026 — a webhook URL obtained through that legacy setup will no
    longer work. The current, correct way to get a Teams webhook URL
    is via the Workflows app's "When a Teams webhook request is
    received" trigger template, not the old Connectors page. The
    MessageCard payload format used below is still explicitly
    supported through Workflows, so no payload change was needed —
    only awareness that HOW the URL is obtained changed, not the
    format sent to it.
    """
    if not TEAMS_WEBHOOK:
        return (False, "Teams webhook not configured") if _return_error else False
    try:
        payload = {
            "@type": "MessageCard",
            "@context": "http://schema.org/extensions",
            "summary": "MWDTS Notification",
            "themeColor": "001530",
            "title": "MWDTS Notification",
            "text": message,
        }
        resp = requests.post(TEAMS_WEBHOOK, json=payload, timeout=5)
        resp.raise_for_status()
        return (True, "") if _return_error else True
    except Exception as e:
        _err = f"{type(e).__name__}: {e}"
        log_error(_err, endpoint="teams")
        return (False, _err) if _return_error else False

def send_external_notifications(message):
    send_slack_notification(message)
    send_teams_notification(message)

# -------------------------------
# 7B. AI-ASSISTED FEATURES (Smart Descriptions, Severity Prediction)
# -------------------------------
def _call_anthropic(messages, max_tokens, timeout=15):
    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={
            "x-api-key": ANTHROPIC_API_KEY,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
        },
        json={"model": ANTHROPIC_MODEL, "max_tokens": max_tokens, "messages": messages},
        timeout=timeout,
    )
    resp.raise_for_status()
    data = resp.json()
    return "".join(block.get("text", "") for block in data.get("content", []) if block.get("type") == "text")


def _call_openai(messages, max_tokens, timeout=15):
    resp = requests.post(
        "https://api.openai.com/v1/chat/completions",
        headers={"Authorization": f"Bearer {OPENAI_API_KEY}"},
        json={"model": OPENAI_MODEL, "max_tokens": max_tokens, "messages": messages},
        timeout=timeout,
    )
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"]


def _call_gemini(messages, max_tokens, timeout=15):
    # Gemini's request shape genuinely differs from the shared
    # messages format used by the other providers — a "contents"
    # array of {"role", "parts": [{"text": ...}]} rather than
    # {"role", "content"}, and it names the model's own prior turns
    # "model", not "assistant" (verified directly against Google's
    # current API docs, not assumed from familiarity with the others).
    gemini_contents = [
        {"role": "user" if m["role"] == "user" else "model", "parts": [{"text": m["content"]}]}
        for m in messages
    ]
    try:
        resp = requests.post(
            f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent",
            params={"key": GEMINI_API_KEY},
            headers={"Content-Type": "application/json"},
            json={"contents": gemini_contents, "generationConfig": {"maxOutputTokens": max_tokens}},
            timeout=timeout,
        )
        resp.raise_for_status()
        data = resp.json()
        return data["candidates"][0]["content"]["parts"][0]["text"]
    except Exception as e:
        # The key rides in the URL for this provider (params={"key": ...}),
        # so raw exception text can contain it verbatim — e.g. an
        # HTTPError's string form includes the full request URL.
        # Redacted HERE, inside the helper, so it's always applied no
        # matter which caller catches this — a failed call must never
        # be the thing that leaks a live key into a log a supervisor
        # can read.
        raise RuntimeError(re.sub(r"key=[^&\s]+", "key=***REDACTED***", f"{type(e).__name__}: {e}")) from e


def _call_groq(messages, max_tokens, timeout=15):
    # Genuinely OpenAI-compatible, not just similar — same
    # request/response shape as the OpenAI helper above, verified
    # directly against Groq's own docs and GitHub repo, not assumed
    # from the marketing claim alone. Only the base URL, key, and
    # model actually differ.
    resp = requests.post(
        "https://api.groq.com/openai/v1/chat/completions",
        headers={"Authorization": f"Bearer {GROQ_API_KEY}"},
        json={"model": GROQ_MODEL, "max_tokens": max_tokens, "messages": messages},
        timeout=timeout,
    )
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"]


def call_groq_web_search(question, search_settings=None):
    """Answers a question WITH live web search, using Groq's Compound
    Mini model — verified directly against Groq's own docs before
    writing this (console.groq.com/docs/tool-use/built-in-tools/
    web-search). Same endpoint, same auth as regular Groq — the ONLY
    difference is the model string; Compound decides on its own when
    a question actually needs a search versus when it can just answer.

    Deliberately NOT part of the generate_smart_text() fall-through
    chain, and never called automatically — this is genuinely paid
    (Groq's own pricing: $5-8 per 1,000 search requests, on top of
    normal token costs), unlike every other path in this app's AI
    integration, which runs on free tiers. It must only ever fire
    from an explicit, visible opt-in the person chose for that one
    question — silently routing questions through this via a
    provider preference or automatic fallback would risk real,
    unexpected charges for something that looks identical to a free
    request from the person's side.

    Returns (answer, sources) where sources is a list of
    {"title", "url"} dicts extracted from Compound's own citation
    data — or raises on failure, same convention as the other
    provider-calling helpers, so callers handle errors uniformly.

    search_settings, if given, is passed straight through to the API
    as-is — Groq's own include_domains/exclude_domains/country
    controls, unused by default (a global, unrestricted search is
    what "search globally" actually means).
    """
    payload = {
        "model": "groq/compound-mini",
        "messages": [{"role": "user", "content": question}],
    }
    if search_settings:
        payload["search_settings"] = search_settings
    resp = requests.post(
        "https://api.groq.com/openai/v1/chat/completions",
        headers={"Authorization": f"Bearer {GROQ_API_KEY}"},
        json=payload,
        timeout=30,  # search adds real latency beyond a normal completion — longer timeout than the 15s used elsewhere
    )
    resp.raise_for_status()
    data = resp.json()
    answer = data["choices"][0]["message"]["content"]
    sources = []
    executed = data["choices"][0]["message"].get("executed_tools") or []
    for tool_call in executed:
        for result in (tool_call.get("search_results") or {}).get("results", []):
            if result.get("url"):
                sources.append({"title": result.get("title", result["url"]), "url": result["url"]})
    return answer, sources


def _call_openrouter(messages, max_tokens, timeout=15):
    # Also genuinely OpenAI-compatible (verified directly against
    # OpenRouter's own docs) — the one real difference from the
    # Groq/OpenAI helpers is the model string needs a provider prefix
    # (OPENROUTER_MODEL already carries this, e.g. "openai/gpt-4o-mini").
    resp = requests.post(
        "https://openrouter.ai/api/v1/chat/completions",
        headers={"Authorization": f"Bearer {OPENROUTER_API_KEY}"},
        json={"model": OPENROUTER_MODEL, "max_tokens": max_tokens, "messages": messages},
        timeout=timeout,
    )
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"]


# Display name, the live API key to check, and the calling helper —
# one row per provider. AI_PROVIDER_CHOICES is the subset with a key
# actually configured, in this same default order — built fresh each
# time it's read (not cached at import time) so it always reflects
# current secrets, and is what the Assistant's provider picker in
# Chat is populated from.
_PROVIDER_CHAIN = [
    ("Anthropic", "ANTHROPIC_API_KEY", _call_anthropic),
    ("OpenAI", "OPENAI_API_KEY", _call_openai),
    ("Gemini", "GEMINI_API_KEY", _call_gemini),
    ("Groq", "GROQ_API_KEY", _call_groq),
    ("OpenRouter", "OPENROUTER_API_KEY", _call_openrouter),
]


def get_configured_ai_providers():
    """Display names of providers that currently have a key set, in
    the same default fall-through order — used to populate the
    Assistant's provider picker with only real, usable choices."""
    _key_values = {"ANTHROPIC_API_KEY": ANTHROPIC_API_KEY, "OPENAI_API_KEY": OPENAI_API_KEY,
                  "GEMINI_API_KEY": GEMINI_API_KEY, "GROQ_API_KEY": GROQ_API_KEY,
                  "OPENROUTER_API_KEY": OPENROUTER_API_KEY}
    return [name for name, key_var, _ in _PROVIDER_CHAIN if _key_values[key_var]]


def generate_smart_text(prompt, max_tokens=300, _return_error=False, preferred_provider=None, timeout=15):
    """Calls whichever AI provider is configured — tries Anthropic,
    OpenAI, Gemini, Groq, then OpenRouter, in that order by default.
    Shared by all AI-assisted features (Smart Work Order Descriptions,
    Incident Severity Prediction, AI Assistant) rather than each
    having its own separate API-calling logic, so a provider or model
    change only needs to happen in one place.

    `prompt` is EITHER a plain string (single-turn — wrapped into a
    one-message list internally, existing single-turn callers are
    unaffected) OR a list of {"role": "user"/"assistant", "content":
    ...} dicts for genuine multi-turn conversation. All five providers
    accept a messages/contents array in a compatible shape (Gemini's
    is converted inside its own helper; the other four are used as-is).

    `preferred_provider`, if given, is one of the display names from
    get_configured_ai_providers() (e.g. "Groq") — that provider is
    tried FIRST regardless of the default order, matching a person's
    own explicit choice in the Assistant's provider picker. Falls
    through to the rest of the chain in default order if the
    preferred one fails, same as any other provider would.

    `timeout`, in seconds, defaults to 15 (existing behavior for every
    caller that doesn't override it — the Assistant, Smart Work Order
    Descriptions, Incident Severity). auto_t() passes a shorter value:
    UI translation is a nice-to-have running silently in the middle of
    someone loading a page, not something worth blocking on for the
    same duration as a real, requested Assistant answer — and with up
    to 5 providers in the fall-through chain, a slow (not even failed)
    first provider at the default timeout could otherwise cost up to
    5x that before even reaching a faster one.

    Falls through to the next configured provider if one fails,
    rather than stopping at the first one tried — a leftover, broken
    key for an earlier provider in this order (e.g. an old Gemini key
    still set after switching to Groq) must not silently block a
    later, working one from ever being reached. Only returns failure
    once every configured provider has genuinely been attempted;
    _return_error's error string is the LAST failure seen, since
    that's most likely to be the actually-relevant one to fix if
    several providers happen to be misconfigured at once.

    Returns the generated text (str), or None on total failure — a
    down API, a bad key, a network timeout, or nothing configured at
    all. This must never be the thing that blocks someone from
    creating a task or reporting an incident just because a
    third-party AI service had a bad moment; callers fall back to the
    person's own typed input, not this failing outright.

    _return_error=True changes the return to a 3-tuple: (text, error,
    provider_name). provider_name is the display name of whichever
    provider actually answered — this exists specifically so a
    caller can tell the difference between "the preferred provider
    answered" and "the preferred provider failed and this is a
    fallback" — two situations that would otherwise look identical
    from the text alone, which is exactly what made an earlier
    provider-switching bug report hard to diagnose: a failed
    preference silently produces a normal-looking answer from a
    DIFFERENT provider, with nothing in the UI to reveal that.
    """
    messages = prompt if isinstance(prompt, list) else [{"role": "user", "content": prompt}]
    _last_err = "No AI provider configured"

    _key_values = {"ANTHROPIC_API_KEY": ANTHROPIC_API_KEY, "OPENAI_API_KEY": OPENAI_API_KEY,
                  "GEMINI_API_KEY": GEMINI_API_KEY, "GROQ_API_KEY": GROQ_API_KEY,
                  "OPENROUTER_API_KEY": OPENROUTER_API_KEY}
    _chain = list(_PROVIDER_CHAIN)
    if preferred_provider:
        # Move the preferred provider to the front, leaving the
        # relative order of everything else unchanged — a genuine
        # reorder, not a duplicate entry or a second attempt.
        _chain.sort(key=lambda row: row[0] != preferred_provider)

    for _name, _key_var, _call_fn in _chain:
        if not _key_values[_key_var]:
            continue
        try:
            text = _call_fn(messages, max_tokens, timeout=timeout)
            return (text, "", _name) if _return_error else text
        except Exception as e:
            _last_err = str(e) if isinstance(e, RuntimeError) else f"{type(e).__name__}: {e}"
            log_error(_last_err, endpoint=f"generate_smart_text_{_name.lower()}")

    return (None, _last_err, None) if _return_error else None


def generate_smart_work_order_description(brief_notes):
    """Expands a supervisor's brief, shorthand notes into a clearer,
    fuller work order description. Returns None on failure — the
    caller must fall back to the supervisor's own raw notes, not
    block task creation on an AI call succeeding.
    """
    prompt = (
        "You are helping a mine maintenance supervisor write a clear work order "
        "description from their brief notes. Expand the following short, informal "
        "note into a clear, professional 2-4 sentence work order description. "
        "Do not invent specific details (part numbers, exact measurements, root "
        "causes) that weren't in the original note — only clarify and expand the "
        "wording itself. Return ONLY the description text, no preamble.\n\n"
        f"Supervisor's notes: {brief_notes}"
    )
    return generate_smart_text(prompt, max_tokens=200)


def predict_incident_severity(incident_type, description):
    """Suggests a severity level from the incident description — a
    SUGGESTION ONLY, always shown as one to be reviewed and confirmed
    by the person reporting, never auto-applied to the actual form
    field. Getting a severity wrong has real consequences (a
    misclassified "Low" delaying an appropriately urgent response),
    so the response is validated strictly against the exact 4
    canonical values this app uses elsewhere — returns None (not a
    guess, not the closest-sounding word) if the AI's response
    doesn't cleanly match one of them, rather than risk silently
    coercing something unexpected into a specific severity claim.
    """
    valid_severities = {"Low", "Medium", "High", "Critical"}
    prompt = (
        "You are helping assess the severity of a mine safety incident. Based on the "
        "incident type and description below, respond with EXACTLY ONE WORD: Low, "
        "Medium, High, or Critical. No other text, no explanation, no punctuation — "
        "just the single severity word.\n\n"
        f"Incident type: {incident_type}\n"
        f"Description: {description}"
    )
    result = generate_smart_text(prompt, max_tokens=10)
    if not result:
        return None
    cleaned = result.strip().strip(".").strip()
    return cleaned if cleaned in valid_severities else None


def get_app_context_summary(tasks, assets, incidents, parts_lookup):
    """A compact, current-data snapshot fed to the Maintenance
    Assistant chatbot as grounding context — the whole point being
    that it answers from what's ACTUALLY in the app right now, not
    from whatever an LLM might otherwise guess or hallucinate about a
    mine site it has no real access to.

    Deliberately a summary, not a full data dump — the underlying
    tasks/incidents lists can run into the hundreds, which would
    blow past a reasonable prompt size and cost. Reuses functions
    already established elsewhere (safety_leading_indicators,
    compute_mtbf_hours, cost_by_category) rather than recalculating
    the same numbers a different way here.

    Also includes the full How It Works guide (~1,600 tokens,
    reasonable to send in full rather than truncate) — this is what
    lets the assistant answer "how do I..." questions about a
    feature's actual workflow, not just its data. Same grounding
    principle either way: answer from what's actually documented in
    this app, never guessed.
    """
    open_tasks = [t2 for t2 in tasks if t2.get("status") != "Complete"]
    overdue_tasks = [t2 for t2 in open_tasks if t2.get("due_date")
                     and (_parse_dt(t2["due_date"]) or datetime.max) < datetime.now()]
    si = safety_leading_indicators(incidents, tasks)
    mtbf, mtbf_n = compute_mtbf_hours(tasks)
    cost_cats = cost_by_category(tasks, parts_lookup)
    top_cost_cat = cost_cats[0] if cost_cats else None

    lines = [
        f"Open tasks: {len(open_tasks)} (of which {len(overdue_tasks)} overdue)",
        f"Total assets tracked: {len(assets)}",
        f"Incidents in last 30 days: {si['last_30_days']} (near-misses/hazards: {si['proactive_reports']}, injuries: {si['injuries']})",
        f"MTBF (mean time between failures): {f'{mtbf:.0f} hours' if mtbf is not None else 'not enough data yet'}",
    ]
    if top_cost_cat:
        lines.append(f"Highest-cost work category: {top_cost_cat['category']} (total: {top_cost_cat['total_cost']:,.2f})")
    if overdue_tasks:
        lines.append("Overdue task titles: " + "; ".join(t2.get("title", "") for t2 in overdue_tasks[:10]))

    lines.append("\n--- How each app feature works (use this to answer 'how do I...' questions) ---")
    for category, features in HOW_IT_WORKS_GUIDE.items():
        lines.append(f"\n{category}:")
        for name, desc in features.items():
            lines.append(f"- {name}: {desc}")

    return "\n".join(lines)


# -------------------------------
# 15C. AI ASSISTANT REINFORCEMENT LEARNING (Thompson Sampling bandit)
# -------------------------------
# What "the AI Assistant learns via reinforcement learning" honestly
# means in an app with no access to retrain the underlying model's
# weights: a genuine multi-armed bandit — specifically Thompson
# Sampling, a real, standard RL algorithm — that learns from thumbs
# up/down feedback which ANSWER-STYLE instruction tends to earn
# better ratings, and increasingly favors it over time. It is not
# fine-tuning Claude/GPT/Gemini itself (nobody outside the model
# provider can do that from an API-calling app like this one); it's
# the app learning which of ITS OWN prompt choices works better,
# which is exactly the kind of decision a bandit is for.
#
# Every variant keeps the identical grounding/anti-fabrication rules
# — only the closing style instruction differs — so this can never
# learn its way into a variant that answers less accurately, only one
# that people rate as more USEFULLY FORMATTED.
AI_PROMPT_VARIANTS = {
    "concise": "Keep answers concise (2-4 sentences unless more detail is clearly needed).",
    "detailed": "Give thorough, complete answers — don't compress an answer that genuinely "
               "needs more than a few sentences just to be short.",
    "structured": "Use short bullet points or numbered steps whenever the answer has more than "
                 "one part or step, rather than a single dense paragraph.",
}


@st.cache_data(ttl=60, show_spinner=False)
def get_variant_feedback_counts():
    """{variant: {'up': n, 'down': n}} aggregated from every rated
    assistant message across all users — this is the bandit's reward
    history. Fetches up to 2000 most recent rated messages rather
    than the whole table; feedback only accumulates on messages
    someone explicitly rated, which is naturally a small fraction of
    total chat volume, so this stays cheap even on an established
    deployment. Cached briefly since it's read on every single
    Assistant question."""
    counts = {v: {"up": 0, "down": 0} for v in AI_PROMPT_VARIANTS}
    if not SUPABASE_AVAILABLE:
        return counts
    try:
        res = (supabase.table("ai_chat_messages").select("prompt_variant, feedback")
              .not_.is_("prompt_variant", "null").not_.is_("feedback", "null")
              .order("created_at", desc=True).limit(2000).execute())
        for row in (res.data or []):
            v = row.get("prompt_variant")
            f = row.get("feedback")
            if v in counts and f in ("up", "down"):
                counts[v][f] += 1
    except Exception as e:
        log_error(str(e), endpoint="get_variant_feedback_counts")
    return counts


def select_prompt_variant():
    """Thompson Sampling: for each variant, draws one sample from
    Beta(1 + ups, 1 + downs) — the Bayesian posterior over that
    variant's true 'thumbs up' rate, starting from an uninformed
    Beta(1,1) prior before any feedback exists — and picks whichever
    variant drew the highest sample this time.

    This is what makes it genuine reinforcement learning rather than
    a fixed A/B split: a variant with a strong track record gets
    picked most of the time, but a struggling or brand-new variant
    still gets picked occasionally (its posterior is wide/uncertain,
    so its samples are more spread out and sometimes come out on
    top) — continued exploration happens automatically, without a
    separately-tuned exploration rate to get wrong.
    """
    counts = get_variant_feedback_counts()
    samples = {
        v: random.betavariate(1 + c["up"], 1 + c["down"])
        for v, c in counts.items()
    }
    return max(samples, key=samples.get)


ASSISTANT_ACTIONS = {
    "create_task": {
        "label": "Create a task",
        "fields": {"title": "Task title", "location": "Location", "priority": "Priority (Low/Medium/High)",
                   "description": "Description"},
        "required": ["title", "location"],
    },
    "create_incident": {
        "label": "Report an incident",
        "fields": {"incident_type": "Incident type", "severity": "Severity (Low/Medium/High/Critical)",
                   "location": "Location", "description": "Description of what happened"},
        "required": ["incident_type", "description"],
    },
    "log_meter_reading": {
        "label": "Log a meter reading",
        "fields": {"asset_name": "Asset name (as it appears in Assets)", "reading": "Reading value",
                   "meter_unit": "Unit (hours/km/cycles)"},
        "required": ["asset_name", "reading"],
    },
    "add_comment": {
        "label": "Add a comment to a task",
        "fields": {"task_id": "Task number", "comment": "Comment text"},
        "required": ["task_id", "comment"],
    },
}
# Deliberately NOT included: purchase orders (real financial
# commitment) and permit issuance (safety-critical authorization).
# Both need full, deliberate human authorship every time — even with
# a confirm-before-apply step, having an AI draft the starting point
# for either is the wrong shape of assistance for something this
# consequential. Everything in ASSISTANT_ACTIONS above still requires
# an explicit human confirmation before anything is created; this is
# a stricter line than that, for actions where even the DRAFT
# shouldn't come from the AI.

ASSISTANT_ACTION_BLOCK_RE = re.compile(r"```mwdts-action\s*(.*?)```", re.DOTALL)


def parse_assistant_action(response_text):
    """Looks for a fenced ```mwdts-action ... ``` JSON block in the
    model's response (see the system prompt instructions in
    ask_maintenance_assistant for the exact format it's asked to
    use). Returns (display_text, action_dict_or_None) — display_text
    has the raw block stripped out, since that's implementation
    detail the person shouldn't see; action_dict is validated against
    ASSISTANT_ACTIONS (unknown action types, or ones missing their
    required fields, are treated as no action at all rather than
    surfaced as broken — the model's plain-language answer alongside
    it is what actually failed gracefully in that case).
    """
    match = ASSISTANT_ACTION_BLOCK_RE.search(response_text)
    if not match:
        return response_text, None
    display_text = ASSISTANT_ACTION_BLOCK_RE.sub("", response_text).strip()
    try:
        parsed = json.loads(match.group(1).strip())
        action_type = parsed.get("action")
        fields = parsed.get("fields", {})
        spec = ASSISTANT_ACTIONS.get(action_type)
        if not spec:
            return display_text, None
        if not all(fields.get(f) for f in spec["required"]):
            return display_text, None
        return display_text, {"action": action_type, "fields": fields}
    except Exception:
        return display_text, None


def apply_assistant_action(action, current_user, full_name):
    """Applies one CONFIRMED assistant-proposed action through the
    same real, validated functions every other part of the app uses
    — create_task()/create_incident()/log_meter_reading()/
    add_comment(). Nothing here bypasses normal validation; this only
    runs after a person has reviewed the pre-filled fields and
    explicitly clicked confirm (see the Chat page UI). Returns
    (success: bool, message: str)."""
    action_type = action.get("action")
    fields = action.get("fields", {})
    try:
        if action_type == "create_task":
            new_task = create_task(
                title=fields.get("title", ""), location=fields.get("location", ""),
                priority=fields.get("priority") or "Medium", loto=False, jsa=False,
                created_by=full_name, description=fields.get("description"),
            )
            return (True, f"Created task #{new_task['id']}.") if new_task else (False, "Failed to create task.")

        elif action_type == "create_incident":
            new_incident = create_incident(
                incident_type=fields.get("incident_type", ""), severity=fields.get("severity") or "Low",
                location=fields.get("location") or "Unspecified", description=fields.get("description", ""),
                reported_by=full_name,
            )
            return (True, f"Filed incident #{new_incident['id']}.") if new_incident else \
                   (False, "Failed to file incident.")

        elif action_type == "log_meter_reading":
            asset_name = (fields.get("asset_name") or "").strip().lower()
            matches = [a for a in fetch_all_assets() if a.get("name", "").strip().lower() == asset_name]
            if not matches:
                matches = [a for a in fetch_all_assets() if asset_name in a.get("name", "").strip().lower()]
            if len(matches) != 1:
                return False, (f"Couldn't uniquely match asset '{fields.get('asset_name')}' — "
                              f"found {len(matches)} candidate(s). Log this one manually on the "
                              f"Assets page instead.")
            try:
                reading_val = float(fields.get("reading"))
            except (TypeError, ValueError):
                return False, "Reading value isn't a valid number."
            ok = log_meter_reading(matches[0]["id"], reading_val,
                                   fields.get("meter_unit") or matches[0].get("meter_unit", "hours"), full_name)
            return (True, f"Logged reading for {matches[0]['name']}.") if ok else (False, "Failed to log reading.")

        elif action_type == "add_comment":
            try:
                task_id = int(fields.get("task_id"))
            except (TypeError, ValueError):
                return False, "Task number isn't valid."
            ok = add_comment(task_id, fields.get("comment", ""), full_name)
            return (True, f"Comment added to task #{task_id}.") if ok else (False, "Failed to add comment.")

        else:
            return False, f"Unknown action type: {action_type}"
    except Exception as e:
        log_error(str(e), endpoint="apply_assistant_action", details={"action": action})
        return False, f"Unexpected error: {e}"


def render_struggle_banner(current_page_name):
    """Shows a 'need help?' prompt if THIS session has hit several
    errors recently (see the tracking added in log_error above), plus
    always offers a manual 'I'm stuck' escape hatch — the two
    detection modes requested: automatic AND self-reported. Clicking
    either jumps to the Assistant with the actual situation already
    filled in as the opening question, rather than a blank chat box
    someone has to figure out how to phrase from scratch."""
    _auto_triggered = st.session_state.get("_struggle_detected", False)
    if _auto_triggered:
        _last_err = st.session_state.get("_struggle_last_error", "")
        st.warning(f"🤖 Looks like something's not going smoothly on **{current_page_name}** — "
                  f"want help from the Assistant?")
        _sb1, _sb2 = st.columns([1, 3])
        if _sb1.button("Ask the Assistant", key="struggle_banner_help"):
            st.session_state["_ai_prefill_question"] = (
                f"I'm having trouble on the {current_page_name} page. The last error I saw was: "
                f"{_last_err}. Can you help me figure out what's going wrong?")
            st.session_state["_struggle_detected"] = False
            st.session_state["_recent_error_timestamps"] = []
            navigate_to("Chat")
            st.rerun()
        if _sb2.button("Dismiss", key="struggle_banner_dismiss"):
            st.session_state["_struggle_detected"] = False
            st.session_state["_recent_error_timestamps"] = []
            st.rerun()
    elif current_page_name != "Chat":
        # Always-available, quiet manual escape hatch — self-reported
        # struggle doesn't need three errors to have happened first;
        # someone can be stuck without hitting a single st.error().
        if st.button("🆘 I'm stuck — ask the Assistant", key="manual_stuck_button"):
            st.session_state["_ai_prefill_question"] = (
                f"I'm having trouble figuring out how to do something on the {current_page_name} "
                f"page. Can you help?")
            navigate_to("Chat")
            st.rerun()


def render_action_proposal_card(msg_id, action, current_user, full_name):
    """Shared confirm/discard UI for an action the Assistant proposed
    — used both for a just-received answer and when replaying chat
    history, so the same message shows the same card either way.
    Fields are pre-filled from what the model proposed but are all
    editable — the person can fix a wrong detail before confirming,
    they are never stuck accepting or fully rejecting a close-but-not-
    quite-right draft.

    'Handled' state (confirmed or discarded) is tracked in
    session_state per message id — persists for the rest of this
    browser session, but a fresh session starts clean rather than
    resurfacing a days-old draft as if it were new.
    """
    _handled_key = f"_ai_action_handled_{msg_id}"
    if st.session_state.get(_handled_key):
        _result = st.session_state.get(f"_ai_action_result_{msg_id}")
        if _result:
            (st.success if _result[0] else st.info)(_result[1])
        return

    spec = ASSISTANT_ACTIONS.get(action["action"])
    if not spec:
        return
    st.markdown(f"**🤖 Proposed: {spec['label']}** — review before confirming:")
    edited_fields = {}
    for fname, flabel in spec["fields"].items():
        edited_fields[fname] = st.text_input(
            flabel, value=str(action["fields"].get(fname, "")), key=f"_ai_action_field_{msg_id}_{fname}")

    _ac1, _ac2 = st.columns(2)
    if _ac1.button("✅ Confirm & create", key=f"_ai_action_confirm_{msg_id}"):
        _ok, _msg = apply_assistant_action({"action": action["action"], "fields": edited_fields},
                                           current_user, full_name)
        st.session_state[_handled_key] = True
        st.session_state[f"_ai_action_result_{msg_id}"] = (_ok, _msg)
        st.rerun()
    if _ac2.button("❌ Discard", key=f"_ai_action_discard_{msg_id}"):
        st.session_state[_handled_key] = True
        st.session_state[f"_ai_action_result_{msg_id}"] = (True, "Discarded — nothing was created.")
        st.rerun()


def ask_maintenance_assistant(question, context_summary, conversation_history=None, preferred_provider=None):
    """Answers questions about the app (grounded in current data and
    the How It Works guide) AND general knowledge questions, with
    genuine multi-turn memory of earlier questions in the same
    session when conversation_history is provided.

    The grounding constraint still applies specifically to app
    questions — never invent a task count, asset name, or feature
    behavior that isn't in the summary. General knowledge questions
    are a different kind of question entirely and are answered from
    the model's own knowledge, same as any general-purpose assistant
    would — the constraint against fabrication is about not
    pretending to know this app's actual data when it doesn't, not
    about refusing unrelated questions.

    conversation_history, if given, is a list of {"role": "user"/
    "assistant", "content": ...} dicts from earlier turns — appended
    to before this question, so the AI can resolve follow-ups like
    "what about the other one?" against what was actually asked and
    answered earlier, not just this single question in isolation.

    preferred_provider, if given, is passed straight through to
    generate_smart_text() — a person's own explicit choice in the
    Assistant's provider picker, tried first but still falling back
    to the rest of the chain if it fails.

    Which ANSWER STYLE is used comes from select_prompt_variant()
    (see the reinforcement-learning section above) rather than being
    fixed — this picks a style, weighted by which has earned better
    thumbs-up feedback historically, for every single question.

    Returns (answer, provider_name, variant_name) — variant_name lets
    the caller record which style produced this answer, so its
    eventual feedback can be attributed back to the bandit.
    """
    variant = select_prompt_variant()
    _action_instructions = "\n".join(
        f"- {atype}: {spec['label']}. Fields: "
        + ", ".join(f"{fname} ({fdesc})" for fname, fdesc in spec["fields"].items())
        + f". Required: {', '.join(spec['required'])}."
        for atype, spec in ASSISTANT_ACTIONS.items()
    )
    system_context = (
        "You are the assistant built into a mine's task and asset tracking system "
        "(MWDTS). You handle three kinds of things:\n"
        "1. Questions about this app's current data or how its features work — for "
        "these, answer using ONLY the data summary and feature guide below. Do not "
        "invent specific numbers, asset names, or task details that aren't in it. If "
        "the summary doesn't contain enough information, say so plainly rather than "
        "guessing.\n"
        "2. General knowledge questions unrelated to the app — answer these normally, "
        "using your own knowledge, the same as any general-purpose assistant would.\n"
        "3. Requests to actually DO something in the app (create a task, report an "
        "incident, log a meter reading, add a comment) — for these, respond with your "
        "normal plain-language reply, AND append a fenced block in EXACTLY this format "
        "on its own, with a single JSON object inside:\n"
        "```mwdts-action\n"
        '{"action": "<action_type>", "fields": {"<field>": "<value>", ...}}\n'
        "```\n"
        "Available action_types and their fields:\n"
        f"{_action_instructions}\n"
        "Only include fields you actually have real values for from the conversation — "
        "leave a field out entirely rather than inventing a placeholder value for it. "
        "This block is NEVER applied automatically — the person always sees exactly what "
        "you filled in and must explicitly confirm before anything is actually created, "
        "so it's fine (expected, even) to propose an action from a clear, direct request "
        "without asking clarifying questions first — missing required fields just means "
        "the person fills them in on the confirmation screen instead. Only skip proposing "
        "an action entirely if the request is genuinely ambiguous about WHICH action is "
        "wanted, not just missing some details of a clear one. Never propose "
        "action_types other than the ones listed above — this app deliberately does not "
        "let you draft purchase orders or safety permits; if asked for either, explain "
        "that those need to be created directly in their respective sections since they "
        "require full human authorship.\n"
        f"{AI_PROMPT_VARIANTS[variant]}\n\n"
        f"Current data summary and feature guide:\n{context_summary}"
    )
    messages = list(conversation_history) if conversation_history else []
    # The system context rides on THIS turn's question rather than a
    # separate system-role message — keeps the data summary current
    # even mid-conversation (it's regenerated fresh each call from
    # live app data), rather than baked into a system message from
    # whenever the conversation started.
    messages.append({"role": "user", "content": f"{system_context}\n\nQuestion: {question}"})
    text, _err, provider = generate_smart_text(messages, max_tokens=300,
                                                preferred_provider=preferred_provider, _return_error=True)
    return text, provider, variant

# 8. IMAGE & ATTACHMENT VALIDATION
# -------------------------------
def validate_image(file_bytes, filename):
    ext = filename.split('.')[-1].lower()
    if ext not in ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp']:
        return False, "Only image files (jpg, png, gif, bmp, webp) are allowed."
    if len(file_bytes) > MAX_UPLOAD_BYTES:
        return False, f"File size exceeds {MAX_UPLOAD_SIZE_MB} MB."
    if PIL_AVAILABLE:
        try:
            img = Image.open(BytesIO(file_bytes))
            img.verify()
            return True, "Valid image."
        except Exception:
            return False, "Invalid or corrupt image file."
    return True, "Valid image."

def validate_attachment(file_bytes, filename):
    if not filename or '.' not in filename:
        return False, "File must have a valid extension."
    ext = filename.split('.')[-1].lower()
    if ext not in ALLOWED_ATTACHMENT_EXTENSIONS:
        return False, f"File type '.{ext}' is not allowed. Allowed types: {', '.join(ALLOWED_ATTACHMENT_EXTENSIONS)}."
    if len(file_bytes) > MAX_UPLOAD_BYTES:
        return False, f"File size exceeds {MAX_UPLOAD_SIZE_MB} MB."
    return True, "Valid attachment."

