@st.cache_data(ttl=15, show_spinner=False)
def fetch_task_activity(task_id):
    """log_task_activity() writes here from 7 different call sites
    across the file — wiring explicit .clear() invalidation at every
    one is a real task, not done in this pass. A short 15s TTL instead
    trades a brief, low-stakes staleness window (this is an activity
    feed, not safety- or money-critical data) for most of the caching
    benefit without that larger effort. Revisit if 15s ever proves
    noticeable in practice."""
    if not SUPABASE_AVAILABLE:
        return st.session_state.get("activity_memory", [])
    try:
        res = supabase.table("task_activity").select("*").eq("task_id", task_id).order("created_at", desc=False).execute()
        if res.data:
            return res.data
    except Exception as e:
        log_error(str(e), endpoint="fetch_task_activity")
        pass
    return []

# -------------------------------
# 12. NOTIFICATIONS
# -------------------------------
def send_push_to_user(username, title, body):
    """Sends a real device-level push notification to every device
    that username has subscribed from (a person can have more than
    one). Best-effort by design, matching every other notification/
    logging function in this file — a failed push should never block
    or crash whatever triggered it. A subscription that comes back as
    permanently dead (410 Gone — the browser unsubscribed or the
    device is gone for good) gets cleaned up automatically instead of
    failing silently forever on every future send.
    """
    if not PUSH_CONFIGURED or not SUPABASE_AVAILABLE:
        return
    try:
        res = supabase.table("push_subscriptions").select("*").eq("username", username).execute()
        subs = res.data or []
    except Exception as e:
        log_error(str(e), endpoint="send_push_to_user:fetch")
        return

    for sub in subs:
        try:
            webpush(
                subscription_info={
                    "endpoint": sub["endpoint"],
                    "keys": {"p256dh": sub["p256dh_key"], "auth": sub["auth_key"]},
                },
                data=json.dumps({"title": title, "body": body}),
                vapid_private_key=VAPID_PRIVATE_KEY,
                vapid_claims={"sub": f"mailto:{VAPID_CLAIMS_EMAIL}"},
            )
        except WebPushException as e:
            _status = getattr(getattr(e, "response", None), "status_code", None)
            if _status == 410:
                try:
                    supabase.table("push_subscriptions").delete().eq("id", sub["id"]).execute()
                except Exception:
                    pass  # cleanup is a nicety, not worth a second error over
            else:
                log_error(str(e), endpoint="send_push_to_user:send", details={"username": username})
        except Exception as e:
            log_error(str(e), endpoint="send_push_to_user:send", details={"username": username})


def save_push_subscription(username, endpoint, p256dh_key, auth_key):
    """Persists a new device subscription. Uses the endpoint's own
    UNIQUE constraint (see schema) to make re-subscribing the same
    device harmless rather than creating duplicate rows that would
    each separately (and redundantly) receive every push."""
    if not SUPABASE_AVAILABLE:
        return False
    try:
        res = supabase.table("push_subscriptions").upsert({
            "username": username, "endpoint": endpoint,
            "p256dh_key": p256dh_key, "auth_key": auth_key,
        }, on_conflict="endpoint").execute()
        return bool(res.data)
    except Exception as e:
        log_error(str(e), endpoint="save_push_subscription")
        return False


NOTIFICATION_CATEGORIES = {
    "task_assigned": "Task assignments",
    "task_overdue": "Task overdue alerts",
    "permit_expiring": "Permit expiring alerts",
    "access_decisions": "Access approved / role changed",
    "announcements": "Announcements",
    "mentions": "Comment @mentions",
}


def get_notification_preferences(username_or_fullname):
    """Returns {category: bool}. Missing/NULL preferences column, or
    a category key not present in the stored JSON, defaults to True
    (fail-open) — see Phase 49 in schema_additions.sql for why."""
    defaults = {cat: True for cat in NOTIFICATION_CATEGORIES}
    try:
        user_record = next(
            (u for u in fetch_all_users_from_db()
            if u.get("username") == username_or_fullname or u.get("full_name") == username_or_fullname),
            None)
        if not user_record or not user_record.get("notification_preferences"):
            return defaults
        stored = json.loads(user_record["notification_preferences"])
        return {**defaults, **stored}
    except Exception:
        return defaults  # a malformed/unreadable preference must never block a notification


def _category_push_allowed(username_or_fullname, category):
    if not category:
        return True  # ungated categories (security/owner-critical) always push
    return get_notification_preferences(username_or_fullname).get(category, True)


def update_notification_preferences(username, prefs_dict):
    fetch_all_users_from_db.clear()
    if not SUPABASE_AVAILABLE:
        return False
    try:
        res = supabase.table("facility_users").update({
            "notification_preferences": json.dumps(prefs_dict)
        }).eq("username", username).execute()
        return bool(res.data)
    except Exception as e:
        log_error(str(e), details={"username": username}, endpoint="update_notification_preferences")
        return False


def send_notification(user_name, title, body, category=None):
    if not SUPABASE_AVAILABLE:
        return
    try:
        supabase.table("notifications").insert({
            "user_name": user_name,
            "title": title,
            "body": body
        }).execute()
    except Exception as e:
        log_error(str(e), endpoint="send_notification")
    # The in-app notification above is never gated — preferences here
    # only control whether a DEVICE push also fires for it.
    if _category_push_allowed(user_name, category):
        send_push_to_user(user_name, title, body)  # best-effort, real device push


def send_grouped_notification(user_name, event_title, items, item_label_fn, category=None, max_listed=5):
    """Sends ONE notification summarizing several items of the same
    kind, instead of one notification per item — e.g. "5 tasks
    overdue" rather than 5 separate 'Task Overdue' pushes landing
    back-to-back. Reduces to a plain single-item send_notification()
    call when there's exactly one item, so a caller never has to
    branch on count itself.

    This groups whatever the CALLER already collected in one pass
    (see run_escalations) — it is not a time-windowed background
    batcher, since Streamlit has no scheduler to run one outside of
    an actual page load/button click (same limitation already noted
    on run_escalations itself)."""
    if not items:
        return
    if len(items) == 1:
        send_notification(user_name, event_title, item_label_fn(items[0]), category=category)
        return
    listed = "; ".join(item_label_fn(i) for i in items[:max_listed])
    if len(items) > max_listed:
        listed += f"; +{len(items) - max_listed} more"
    send_notification(user_name, f"{len(items)}× {event_title}", listed, category=category)


def fetch_notifications(user_name):
    """Deliberately NOT cached — a notification list that's stale by
    even 30-60s reads as broken ("it says I have 3 unread but I just
    marked them read"), and this is checked constantly across the app
    (sidebar bell, dashboard widget). The read cost here is cheap
    (indexed lookup, limit 20) relative to how badly staleness would
    be noticed, unlike the config-like tables cached elsewhere."""
    if not SUPABASE_AVAILABLE:
        return []
    try:
        res = supabase.table("notifications").select("*").eq("user_name", user_name).order("created_at", desc=True).limit(20).execute()
        if res.data:
            return res.data
    except Exception as e:
        log_error(str(e), endpoint="fetch_notifications")
        return []
    return []

def mark_notification_read(notification_id):
    if not SUPABASE_AVAILABLE:
        return
    try:
        supabase.table("notifications").update({"is_read": True}).eq("id", notification_id).execute()
    except Exception as e:
        log_error(str(e), endpoint="mark_notification_read")

# -------------------------------
# 13. PHOTO FUNCTIONS (with fallback)
# -------------------------------
def upload_photo(task_id, file_bytes, filename, uploaded_by):
    """Upload proof-of-work/safety photo evidence.

    FIXED: this previously returned True unconditionally — even on a
    failed validation, a failed storage upload, or a caught exception.
    Nothing that happened in this function's body could ever make it
    report failure, which is a serious gap for what's often compliance
    evidence (LOTO isolation photos, incident scenes). The in-session
    memory fallback below is intentional and kept — it lets a photo
    still SHOW UP for the current browser session even if the durable
    write fails — but the return value now reflects whether it was
    actually saved somewhere that survives a refresh or a different
    user loading the same task, not just whether this call ran.
    """
    st.session_state.setdefault("photos_memory", []).append({
        "task_id": task_id,
        "photo_url": f"memory://{filename}",
        "uploaded_by": uploaded_by,
        "uploaded_at": datetime.now().isoformat()
    })
    log_audit(uploaded_by, "photo_upload_memory", {"task_id": task_id, "filename": filename})
    if not SUPABASE_AVAILABLE:
        return True  # demo mode — the memory fallback IS the intended store
    try:
        valid, msg = validate_image(file_bytes, filename)
        if not valid:
            st.error(msg)
            return False
        ext = filename.split(".")[-1]
        safe_name = f"task_{task_id}/{datetime.now().strftime('%Y%m%d_%H%M%S')}_{hashlib.md5(file_bytes).hexdigest()[:8]}.{ext}"
        storage_res = supabase.storage.from_("task_photos").upload(safe_name, file_bytes)
        if not storage_res:
            log_error("Storage upload returned a falsy result", details={"task_id": task_id},
                     endpoint="photo_upload")
            return False
        public_url = supabase.storage.from_("task_photos").get_public_url(safe_name)
        try:
            data = {"task_id": task_id, "photo_url": public_url, "uploaded_by": uploaded_by}
            res = supabase.table("task_photos").insert(data).execute()
            if not res.data:
                log_error("task_photos insert affected 0 rows — likely RLS blocking writes. "
                         "The file reached Storage but has no metadata row, so it won't "
                         "appear when this task is loaded again.",
                         details=data, endpoint="photo_insert")
                return False
            log_audit(uploaded_by, "photo_upload", {"task_id": task_id, "url": public_url})
            return True
        except Exception as e:
            log_error(str(e), endpoint="photo_insert")
            return False
    except Exception as e:
        log_error(str(e), endpoint="photo_upload")
        return False

def fetch_photos(task_id):
    """Deliberately NOT cached — this merges live DB photos with an
    in-session memory fallback (see upload_photo's docstring above)
    specifically so a photo still appears immediately even if the
    durable write silently failed. Caching the whole function would
    freeze that fallback stale within the session, undermining the
    exact safety-net behavior it exists for — and these are often
    compliance evidence (LOTO isolation photos, incident scenes),
    where that guarantee matters more than the read-cost saving."""
    if not SUPABASE_AVAILABLE:
        photos = st.session_state.get("photos_memory", [])
        return [p for p in photos if p["task_id"] == task_id]
    db_photos = []
    try:
        res = supabase.table("task_photos").select("*").eq("task_id", task_id).order("uploaded_at", desc=True).execute()
        if res.data:
            db_photos = res.data
    except Exception as e:
        log_error(str(e), endpoint="fetch_photos")
        pass
    memory_photos = st.session_state.get("photos_memory", [])
    memory_photos = [p for p in memory_photos if p["task_id"] == task_id]
    all_photos = db_photos + memory_photos
    all_photos.sort(key=lambda x: x.get('uploaded_at', ''), reverse=True)
    return all_photos

# -------------------------------
# 14. FILE ATTACHMENTS
# -------------------------------
def upload_attachment(task_id, file_bytes, filename, uploaded_by):
    valid, msg = validate_attachment(file_bytes, filename)
    if not valid:
        st.error(msg)
        return False

    if not SUPABASE_AVAILABLE:
        st.session_state.setdefault("attachments_memory", []).append({
            "task_id": task_id,
            "file_name": filename,
            "file_url": f"memory://{filename}",
            "file_type": filename.split('.')[-1].lower(),
            "uploaded_by": uploaded_by,
            "uploaded_at": datetime.now().isoformat()
        })
        log_audit(uploaded_by, "attachment_upload_memory", {"task_id": task_id, "filename": filename})
        fetch_attachments.clear()
        return True
    try:
        ext = filename.split('.')[-1].lower()
        safe_name = f"attachments/task_{task_id}/{datetime.now().strftime('%Y%m%d_%H%M%S')}_{hashlib.md5(file_bytes).hexdigest()[:8]}.{ext}"
        res = supabase.storage.from_("task_attachments").upload(safe_name, file_bytes)
        if res:
            public_url = supabase.storage.from_("task_attachments").get_public_url(safe_name)
            data = {
                "task_id": task_id,
                "file_name": filename,
                "file_url": public_url,
                "file_type": ext,
                "uploaded_by": uploaded_by
            }
            res2 = supabase.table("task_attachments").insert(data).execute()
            if not res2.data:
                log_error("task_attachments insert affected 0 rows — likely RLS blocking "
                         "writes. The file reached Storage but has no metadata row.",
                         details=data, endpoint="attachment_insert")
                return False
            log_audit(uploaded_by, "attachment_upload", {"task_id": task_id, "filename": filename})
            fetch_attachments.clear()
            return True
        else:
            return False
    except Exception as e:
        st.error(f"Upload failed: {e}")
        log_error(str(e), details={"task_id": task_id, "filename": filename}, endpoint="attachment_upload")
        return False

@st.cache_data(ttl=60, show_spinner=False)
def fetch_attachments(task_id):
    if not SUPABASE_AVAILABLE:
        return st.session_state.get("attachments_memory", [])
    try:
        res = supabase.table("task_attachments").select("*").eq("task_id", task_id).order("uploaded_at", desc=True).execute()
        if res.data:
            return res.data
        else:
            return []
    except Exception as e:
        log_error(str(e), endpoint="fetch_attachments")
        return []

# -------------------------------
# 15. TASK COMMENTS
# -------------------------------
def _parse_comment_mentions(comment_text, posted_by, task_id):
    """Finds @username tokens in a comment and pushes a notification
    to each real, distinct user mentioned (never the person who
    wrote the comment, even if they @mention their own username).
    Matched against username specifically (not full_name) since
    usernames are the no-space handle people would actually type
    after an @ — full names with spaces aren't a workable @mention
    syntax."""
    handles = set(re.findall(r'@([A-Za-z0-9_.]+)', comment_text))
    if not handles:
        return
    try:
        all_users = fetch_all_users_from_db()
        for handle in handles:
            user_record = next(
                (u for u in all_users if u.get("username", "").lower() == handle.lower()), None)
            if not user_record or user_record.get("full_name") == posted_by:
                continue
            send_notification(
                user_record["username"], "You were mentioned",
                f"{posted_by} mentioned you in a comment on Task #{task_id}.",
                category="mentions")
    except Exception as e:
        log_error(str(e), endpoint="_parse_comment_mentions")


def add_comment(task_id, comment, posted_by, parent_comment_id=None):
    if not SUPABASE_AVAILABLE:
        st.session_state.setdefault("comments_memory", []).append({
            "task_id": task_id,
            "comment": comment,
            "posted_by": posted_by,
            "posted_at": datetime.now().isoformat(),
            "parent_comment_id": parent_comment_id,
        })
        log_audit(posted_by, "comment_add_memory", {"task_id": task_id, "comment": comment[:50]})
        fetch_comments.clear()
        _parse_comment_mentions(comment, posted_by, task_id)
        return True
    try:
        data = {"task_id": task_id, "comment": comment, "posted_by": posted_by,
                "parent_comment_id": parent_comment_id}
        res = supabase.table("task_comments").insert(data).execute()
        if not res.data:
            return False
        log_audit(posted_by, "comment_add", {"task_id": task_id, "comment": comment[:50]})
        log_task_activity(task_id, posted_by, "commented", {"comment": comment[:50]})
        fetch_comments.clear()
        _parse_comment_mentions(comment, posted_by, task_id)
        return True
    except Exception as e:
        log_error(str(e), details={"task_id": task_id}, endpoint="add_comment")
        return False

@st.cache_data(ttl=30, show_spinner=False)
def fetch_comments(task_id):
    if not SUPABASE_AVAILABLE:
        comments = st.session_state.get("comments_memory", [])
        return [c for c in comments if c["task_id"] == task_id]
    try:
        res = supabase.table("task_comments").select("*").eq("task_id", task_id).order("posted_at", desc=False).execute()
        if res.data:
            return res.data
    except Exception as e:
        log_error(str(e), endpoint="fetch_comments")
        pass
    return []


def render_comments_section(task, full_name, key_prefix):
    """Shared comments UI — threaded (one level of replies) with
    @mention support. Used by all three role-specific task detail
    views so 'add threading here' is one change, not three near-
    identical ones drifting out of sync."""
    comments = fetch_comments(task['id'])
    top_level = [c for c in comments if not c.get('parent_comment_id')]
    replies_by_parent = {}
    for c in comments:
        if c.get('parent_comment_id'):
            replies_by_parent.setdefault(c['parent_comment_id'], []).append(c)

    if not comments:
        st.caption(t("task.caption_no_comments"))
    for c in top_level:
        st.markdown(f"**{esc(c['posted_by'])}** ({_fmt_log_time(c['posted_at'])}): {esc(c['comment'])}")
        for r in replies_by_parent.get(c['id'], []):
            st.markdown(f"&nbsp;&nbsp;&nbsp;&nbsp;↳ **{esc(r['posted_by'])}** "
                       f"({_fmt_log_time(r['posted_at'])}): {esc(r['comment'])}", unsafe_allow_html=True)
        _reply_key = f"_reply_open_{key_prefix}_{c['id']}"
        if st.button("↩️ Reply", key=f"reply_btn_{key_prefix}_{c['id']}"):
            st.session_state[_reply_key] = not st.session_state.get(_reply_key, False)
        if st.session_state.get(_reply_key):
            _reply_val_key = f"_reply_val_{key_prefix}_{c['id']}"
            reply_text = st.text_input("Reply (use @username to mention someone)",
                                       key=f"reply_input_{key_prefix}_{c['id']}",
                                       value=st.session_state.get(_reply_val_key, ""))
            if st.button("Post reply", key=f"post_reply_{key_prefix}_{c['id']}"):
                if reply_text.strip():
                    if add_comment(task['id'], reply_text, full_name, parent_comment_id=c['id']):
                        st.session_state[_reply_key] = False
                        st.session_state[_reply_val_key] = ""
                        st.rerun()
                    else:
                        st.error(t("task.err_comment_failed"))

    _comment_val_key = f"_comment_val_{key_prefix}_{task['id']}"
    if _comment_val_key not in st.session_state:
        st.session_state[_comment_val_key] = ""
    new_comment = st.text_area(t("task.field_add_comment"), key=f"comment_{key_prefix}_{task['id']}",
                               value=st.session_state[_comment_val_key],
                               placeholder="Write comment... (use @username to mention someone)")
    if st.button(t("task.btn_post_comment"), key=f"post_comment_{key_prefix}_{task['id']}"):
        if new_comment.strip():
            if add_comment(task['id'], new_comment, full_name):
                st.session_state[_comment_val_key] = ""
                st.rerun()
            else:
                st.error(t("task.err_comment_failed"))


# -------------------------------
# 15B. PRESENCE INDICATORS
# -------------------------------
PRESENCE_STALE_SECONDS = 90  # a viewer who hasn't rerun their page in this long is treated as gone


def record_presence(username, full_name, view_context):
    """Upserts a heartbeat row for this user+context. Called once per
    page render wherever presence is shown — see PRESENCE_STALE_SECONDS
    docstring above on why this is a heartbeat, not true realtime."""
    if not SUPABASE_AVAILABLE or not username:
        return
    try:
        supabase.table("viewer_presence").upsert({
            "username": username, "full_name": full_name, "view_context": view_context,
            "last_seen_at": datetime.now().isoformat(),
        }, on_conflict="username,view_context").execute()
    except Exception as e:
        log_error(str(e), endpoint="record_presence", details={"context": view_context})


def get_active_viewers(view_context, exclude_username=None):
    """Returns full_names of everyone whose last heartbeat for this
    context is within PRESENCE_STALE_SECONDS, excluding the caller
    themself (seeing your own name in 'also viewing' is just noise)."""
    if not SUPABASE_AVAILABLE:
        return []
    try:
        cutoff = (datetime.now() - timedelta(seconds=PRESENCE_STALE_SECONDS)).isoformat()
        res = (supabase.table("viewer_presence").select("username, full_name")
              .eq("view_context", view_context).gte("last_seen_at", cutoff).execute())
        return [r["full_name"] or r["username"] for r in (res.data or [])
                if r.get("username") != exclude_username]
    except Exception as e:
        log_error(str(e), endpoint="get_active_viewers", details={"context": view_context})
        return []


def render_presence_indicator(view_context, username, full_name):
    """Records this viewer's own heartbeat, then shows who else (if
    anyone) is currently looking at the same thing. One line, easy to
    drop into any detail view — task cards, asset detail, etc."""
    record_presence(username, full_name, view_context)
    others = get_active_viewers(view_context, exclude_username=username)
    if others:
        st.caption(f"👀 Also viewing: {', '.join(esc(o) for o in others)}")


# -------------------------------
# 15D. OFFLINE TASK UPDATES (capture -> export -> review -> apply)
# -------------------------------
# Streamlit itself is server-rendered: the whole app lives in a
# Python session kept alive by a live connection to the browser. When
# that connection drops, there is no client left running to queue
# anything against — this is a fundamentally different situation than
# a normal offline-capable web app with its own JavaScript runtime.
#
# What CAN genuinely work offline is a separate, self-contained
# browser component (plain HTML/JS, no Streamlit/Python involved
# while offline) that caches a snapshot of someone's tasks, lets them
# record status changes/comments/photos into the browser's own
# localStorage while there's no connection, then — once back online —
# EXPORTS that queue as JSON for a person to paste/upload into the
# Sync Review page below. Every queued action still goes through the
# exact same validated update_task()/add_comment()/upload flow as
# normal use once approved there — nothing bypasses server-side
# checks (permit gates, version conflicts, etc.), and nothing is
# ever applied without a human reviewing it first.
def render_offline_capture_component(my_tasks, username, full_name, app_url=""):
    """Returns the HTML/JS for the offline capture page. my_tasks is
    the list of task dicts to cache client-side for offline viewing
    and action-queueing — pass whatever the current user should be
    able to work on offline (their assigned tasks). app_url, if
    given, is used for the real-connectivity check against the app's
    own /?health=1 endpoint (see updateBanner below) — falls back to
    trusting navigator.onLine alone if not provided."""
    tasks_json = json.dumps([
        {"id": t["id"], "title": t.get("title", ""), "location": t.get("location", ""),
        "status": t.get("status", ""), "priority": t.get("priority", "")}
        for t in my_tasks
    ])
    return f"""
<!DOCTYPE html>
<html>
<head>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body {{ font-family: -apple-system, sans-serif; background: #0f1117; color: #e2e8f0; margin: 0; padding: 12px; }}
  .banner {{ padding: 10px 14px; border-radius: 8px; margin-bottom: 8px; font-weight: 600; }}
  .online {{ background: #0f9d58; color: white; }}
  .offline {{ background: #dc2626; color: white; }}
  .synced-caption {{ color: #94a3b8; font-size: 0.85em; margin-bottom: 12px; }}
  .tabs {{ display: flex; gap: 8px; margin-bottom: 12px; }}
  .tab-btn {{ flex: 1; padding: 8px; border-radius: 6px; border: 1px solid #334155;
              background: #1a1f2e; color: #e2e8f0; cursor: pointer; font-weight: 600; }}
  .tab-btn.active {{ background: #3b82f6; border-color: #3b82f6; }}
  .task {{ background: #1a1f2e; border-radius: 8px; padding: 12px; margin-bottom: 10px; border-left: 4px solid #3b82f6; }}
  .task h4 {{ margin: 0 0 6px 0; }}
  .task select, .task input, .task textarea {{
    width: 100%; box-sizing: border-box; margin-top: 6px; padding: 8px;
    background: #0f1117; color: #e2e8f0; border: 1px solid #334155; border-radius: 6px;
  }}
  .task button {{
    margin-top: 8px; padding: 8px 14px; border-radius: 6px; border: none;
    background: #3b82f6; color: white; font-weight: 600; cursor: pointer;
  }}
  .queue-box {{ background: #1a1f2e; border-radius: 8px; padding: 12px; margin-top: 16px; }}
  .queue-item {{ padding: 8px; border-bottom: 1px solid #334155; font-size: 0.9em; }}
  #exportArea {{ width: 100%; height: 150px; margin-top: 10px; font-family: monospace; font-size: 0.8em; }}
  .export-btn {{ background: #0f9d58; padding: 10px 16px; border-radius: 6px; border: none;
                 color: white; font-weight: 600; cursor: pointer; margin-top: 10px; margin-right: 8px; }}
  .clear-btn {{ background: #64748b; }}
  .hidden {{ display: none; }}
  .compress-note {{ color: #94a3b8; font-size: 0.8em; margin-top: 4px; }}
</style>
</head>
<body>
  <div id="statusBanner" class="banner offline">Checking connection...</div>
  <div id="syncedCaption" class="synced-caption"></div>

  <div class="tabs">
    <button class="tab-btn active" id="tabTasksBtn" onclick="showTab('tasks')">📋 Tasks</button>
    <button class="tab-btn" id="tabIncidentBtn" onclick="showTab('incident')">🚨 Report Incident</button>
  </div>

  <div id="tasksTab">
    <div id="taskList"></div>
  </div>

  <div id="incidentTab" class="hidden">
    <div class="task">
      <h4>Report a Safety Incident</h4>
      <label>Incident type</label>
      <select id="inc_type">
        <option>Near Miss</option>
        <option>Injury</option>
        <option>Equipment Damage</option>
        <option>Environmental</option>
        <option>Other</option>
      </select>
      <label>Severity</label>
      <select id="inc_severity">
        <option>Low</option>
        <option>Medium</option>
        <option>High</option>
        <option>Critical</option>
      </select>
      <label>Location</label>
      <input type="text" id="inc_location" placeholder="Where did this happen?">
      <label>Description</label>
      <textarea id="inc_description" placeholder="What happened?"></textarea>
      <button onclick="queueIncident()">Queue incident report</button>
    </div>
  </div>

  <div class="queue-box">
    <strong>📋 Queued offline actions: <span id="queueCount">0</span></strong>
    <div id="queueList"></div>
    <button class="export-btn" onclick="exportQueue()">📤 Export queue (copy this into Sync Review)</button>
    <button class="export-btn clear-btn" onclick="clearQueue()">🗑️ Clear queue</button>
    <textarea id="exportArea" readonly placeholder="Exported JSON will appear here — copy it and paste into the Sync Review page in the main app."></textarea>
  </div>

<script>
const MY_TASKS = {tasks_json};
const USERNAME = {json.dumps(username)};
const FULL_NAME = {json.dumps(full_name)};
const APP_URL = {json.dumps(app_url)};
const QUEUE_KEY = "mwdts_offline_queue_" + USERNAME;
const SYNC_TS_KEY = "mwdts_last_synced_" + USERNAME;
const MAX_PHOTO_BYTES = 1500000; // ~1.5MB — localStorage has a real ceiling (typically 5-10MB total)
const MAX_PHOTO_DIMENSION = 1280; // px, longer side — compression target before the size check above

// Record this load as "last synced" — the moment this page had fresh
// task data from the server, which is what "offline" data becomes
// stale relative to.
localStorage.setItem(SYNC_TS_KEY, new Date().toISOString());

function showTab(name) {{
  document.getElementById("tasksTab").classList.toggle("hidden", name !== "tasks");
  document.getElementById("incidentTab").classList.toggle("hidden", name !== "incident");
  document.getElementById("tabTasksBtn").classList.toggle("active", name === "tasks");
  document.getElementById("tabIncidentBtn").classList.toggle("active", name === "incident");
}}

function loadQueue() {{
  try {{ return JSON.parse(localStorage.getItem(QUEUE_KEY) || "[]"); }}
  catch (e) {{ return []; }}
}}
function saveQueue(q) {{ localStorage.setItem(QUEUE_KEY, JSON.stringify(q)); renderQueue(); }}

function queueAction(taskId, taskTitle, actionType, payload) {{
  const q = loadQueue();
  q.push({{
    client_id: Date.now() + "_" + Math.random().toString(36).slice(2),
    task_id: taskId, task_title: taskTitle, action_type: actionType,
    payload: payload, queued_at: new Date().toISOString(),
    queued_by: USERNAME, queued_by_name: FULL_NAME,
  }});
  saveQueue(q);
}}

function renderQueue() {{
  const q = loadQueue();
  document.getElementById("queueCount").textContent = q.length;
  document.getElementById("queueList").innerHTML = q.map(a =>
    `<div class="queue-item">${{a.task_id ? "#" + a.task_id + " " + a.task_title : "(incident)"}} — ${{a.action_type}} (${{new Date(a.queued_at).toLocaleString()}})</div>`
  ).join("") || "<div class='queue-item'>Nothing queued yet.</div>";
}}

function exportQueue() {{
  const q = loadQueue();
  document.getElementById("exportArea").value = JSON.stringify(q, null, 2);
}}

function clearQueue() {{
  if (confirm("Clear the offline queue? Only do this AFTER you've successfully pasted/reviewed it in Sync Review.")) {{
    localStorage.removeItem(QUEUE_KEY);
    renderQueue();
    document.getElementById("exportArea").value = "";
  }}
}}

function updateStatus(taskId, taskTitle, selectEl) {{
  queueAction(taskId, taskTitle, "status_change", {{new_status: selectEl.value}});
  alert("Status change queued offline. Export and review it in the app once you're back online.");
}}

function addComment(taskId, taskTitle, inputEl) {{
  if (!inputEl.value.trim()) return;
  queueAction(taskId, taskTitle, "comment", {{comment: inputEl.value.trim()}});
  inputEl.value = "";
  alert("Comment queued offline.");
}}

function queueIncident() {{
  const description = document.getElementById("inc_description").value.trim();
  if (!description) {{ alert("Please describe what happened."); return; }}
  queueAction(null, "(incident report)", "incident", {{
    incident_type: document.getElementById("inc_type").value,
    severity: document.getElementById("inc_severity").value,
    location: document.getElementById("inc_location").value.trim(),
    description: description,
  }});
  document.getElementById("inc_location").value = "";
  document.getElementById("inc_description").value = "";
  alert("Incident report queued offline. Export and review it as soon as you're back online — don't wait if this is urgent and you have any other way to report it.");
}}

// Compresses an image client-side (resize to MAX_PHOTO_DIMENSION on
// the longer side, re-encode as JPEG at 0.7 quality) before it's
// measured against MAX_PHOTO_BYTES — a raw phone camera photo is
// often 3-8MB, well over what localStorage can hold; this lets most
// real photos actually fit instead of being rejected outright.
function compressImage(file, callback) {{
  const reader = new FileReader();
  reader.onload = function(e) {{
    const img = new Image();
    img.onload = function() {{
      let w = img.width, h = img.height;
      if (w > h && w > MAX_PHOTO_DIMENSION) {{ h = Math.round(h * MAX_PHOTO_DIMENSION / w); w = MAX_PHOTO_DIMENSION; }}
      else if (h > MAX_PHOTO_DIMENSION) {{ w = Math.round(w * MAX_PHOTO_DIMENSION / h); h = MAX_PHOTO_DIMENSION; }}
      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      canvas.getContext("2d").drawImage(img, 0, 0, w, h);
      callback(canvas.toDataURL("image/jpeg", 0.7));
    }};
    img.onerror = function() {{ callback(null); }};
    img.src = e.target.result;
  }};
  reader.onerror = function() {{ callback(null); }};
  reader.readAsDataURL(file);
}}

function addPhoto(taskId, taskTitle, fileInput) {{
  const file = fileInput.files[0];
  if (!file) return;
  compressImage(file, function(dataUrl) {{
    if (!dataUrl) {{ alert("Couldn't process that photo."); fileInput.value = ""; return; }}
    // Rough byte estimate from a base64 data URL: length * 0.75
    const approxBytes = dataUrl.length * 0.75;
    if (approxBytes > MAX_PHOTO_BYTES) {{
      alert("Even compressed, this photo is too large for offline storage. Try a different photo, or attach it normally once back online.");
      fileInput.value = "";
      return;
    }}
    queueAction(taskId, taskTitle, "photo", {{filename: file.name, data_base64: dataUrl}});
    alert("Photo queued offline (compressed to fit).");
    fileInput.value = "";
  }});
}}

function renderTasks() {{
  document.getElementById("taskList").innerHTML = MY_TASKS.map(t => `
    <div class="task">
      <h4>#${{t.id}}: ${{t.title}}</h4>
      <div>${{t.location || ""}} — ${{t.status}} — ${{t.priority || ""}}</div>
      <select id="status_${{t.id}}">
        <option value="In Progress" ${{t.status==="In Progress"?"selected":""}}>In Progress</option>
        <option value="Pending QA" ${{t.status==="Pending QA"?"selected":""}}>Pending QA</option>
        <option value="Blocked" ${{t.status==="Blocked"?"selected":""}}>Blocked</option>
        <option value="Complete" ${{t.status==="Complete"?"selected":""}}>Complete</option>
      </select>
      <button onclick="updateStatus(${{t.id}}, ${{JSON.stringify(t.title)}}, document.getElementById('status_${{t.id}}'))">Queue status change</button>
      <input type="text" id="comment_${{t.id}}" placeholder="Add a comment...">
      <button onclick="addComment(${{t.id}}, ${{JSON.stringify(t.title)}}, document.getElementById('comment_${{t.id}}'))">Queue comment</button>
      <input type="file" accept="image/*" capture="environment" id="photo_${{t.id}}">
      <div class="compress-note">Photos are auto-compressed to fit offline storage.</div>
      <button onclick="addPhoto(${{t.id}}, ${{JSON.stringify(t.title)}}, document.getElementById('photo_${{t.id}}'))">Queue photo</button>
    </div>
  `).join("");
}}

function renderSyncedCaption() {{
  const ts = localStorage.getItem(SYNC_TS_KEY);
  document.getElementById("syncedCaption").textContent = ts
    ? "Task list last synced: " + new Date(ts).toLocaleString()
    : "";
}}

// navigator.onLine only reflects whether a network INTERFACE is up
// (e.g. connected to Wi-Fi) — it can read true even with no real
// internet behind a dead router. A real check needs an actual
// request; this pings the app's own lightweight health endpoint
// (see app.py's ?health=1 handler) with cache-busting, since that's
// already built, free, and near-instant. Falls back to trusting
// navigator.onLine alone if APP_URL wasn't provided.
let reallyOnline = navigator.onLine;
async function checkRealConnectivity() {{
  if (!navigator.onLine) {{ reallyOnline = false; updateBanner(); return; }}
  if (!APP_URL) {{ reallyOnline = navigator.onLine; updateBanner(); return; }}
  try {{
    const resp = await fetch(APP_URL + "/?health=1&_=" + Date.now(), {{ cache: "no-store", mode: "cors" }});
    reallyOnline = resp.ok;
  }} catch (e) {{
    reallyOnline = false;
  }}
  updateBanner();
}}

function updateBanner() {{
  const b = document.getElementById("statusBanner");
  if (reallyOnline) {{
    b.className = "banner online";
    b.textContent = "🟢 Online — you can also just use the main app normally right now.";
  }} else {{
    b.className = "banner offline";
    b.textContent = "🔴 Offline — actions below are queued locally until you export them.";
  }}
}}

window.addEventListener("online", checkRealConnectivity);
window.addEventListener("offline", () => {{ reallyOnline = false; updateBanner(); }});
checkRealConnectivity();
setInterval(checkRealConnectivity, 20000); // re-check periodically — Wi-Fi that dies without a browser event happens
renderSyncedCaption();
renderTasks();
renderQueue();
</script>
</body>
</html>
"""


def _log_offline_sync_decision(action, decision, reviewed_by, detail=None, error=None):
    if not SUPABASE_AVAILABLE:
        return
    try:
        supabase.table("offline_sync_log").insert({
            "task_id": action.get("task_id"), "action_type": action.get("action_type"),
            "queued_at": action.get("queued_at"), "queued_by": action.get("queued_by"),
            "client_id": action.get("client_id"),
            "reviewed_by": reviewed_by, "decision": decision,
            "detail": (str(detail)[:500] if detail else None), "error": (str(error)[:500] if error else None),
        }).execute()
    except Exception as e:
        log_error(str(e), endpoint="_log_offline_sync_decision")


@st.cache_data(ttl=30, show_spinner=False)
def get_processed_offline_client_ids():
    """Every client_id already reviewed (approved OR rejected) before
    — checked before Sync Review lets someone act on an action again,
    so pasting the same export twice, or re-uploading an old file,
    can't silently double-apply a status change, duplicate a comment,
    or file a duplicate incident report."""
    if not SUPABASE_AVAILABLE:
        return set()
    try:
        res = (supabase.table("offline_sync_log").select("client_id")
              .not_.is_("client_id", "null").limit(5000).execute())
        return {r["client_id"] for r in (res.data or []) if r.get("client_id")}
    except Exception as e:
        log_error(str(e), endpoint="get_processed_offline_client_ids")
        return set()


def apply_offline_action(action, reviewed_by):
    """Applies ONE approved queued action through the exact same
    validated functions normal use goes through — update_task() for
    a status change (so the permit gate and optimistic-concurrency
    version check both still apply exactly as they would for someone
    typing it in live), add_comment() for a comment, upload_attachment()
    for a photo (decoded from the base64 the offline page captured).

    Returns (success: bool, message: str). A version conflict here
    (task changed by someone else since this was queued offline) is a
    completely expected, correctly-caught case — NOT a bug — surfaced
    as a clear message rather than silently overwriting whatever
    happened while the device was offline.
    """
    task_id = action.get("task_id")
    action_type = action.get("action_type")
    payload = action.get("payload", {})
    queued_by_name = action.get("queued_by_name") or action.get("queued_by") or reviewed_by

    try:
        if action_type == "status_change":
            new_status = payload.get("new_status")
            if not new_status:
                return False, "Missing new_status in queued action."
            ok = update_task(task_id, {"status": new_status}, queued_by_name)
            if ok:
                _log_offline_sync_decision(action, "approved", reviewed_by, detail=f"status -> {new_status}")
                return True, f"Task #{task_id} status set to {new_status}."
            else:
                # update_task already surfaces the specific reason (version
                # conflict, etc.) via st.error internally — this just
                # confirms it wasn't applied.
                _log_offline_sync_decision(action, "approved", reviewed_by, error="update_task returned False")
                return False, (f"Task #{task_id} could not be updated — likely changed by someone "
                              f"else since this was queued offline. Check the task's current state "
                              f"before re-applying.")

        elif action_type == "comment":
            comment_text = payload.get("comment", "").strip()
            if not comment_text:
                return False, "Empty comment in queued action."
            ok = add_comment(task_id, f"[Synced from offline] {comment_text}", queued_by_name)
            _log_offline_sync_decision(action, "approved", reviewed_by, detail=comment_text[:100])
            return (True, f"Comment added to task #{task_id}.") if ok else \
                   (False, f"Failed to add comment to task #{task_id}.")

        elif action_type == "photo":
            data_url = payload.get("data_base64", "")
            filename = payload.get("filename", "offline_photo.jpg")
            if "," not in data_url:
                return False, "Malformed photo data in queued action."
            try:
                file_bytes = base64.b64decode(data_url.split(",", 1)[1])
            except Exception:
                return False, "Could not decode photo data — it may be corrupted."
            ok = upload_attachment(task_id, file_bytes, filename, queued_by_name)
            _log_offline_sync_decision(action, "approved", reviewed_by, detail=filename)
            return (True, f"Photo attached to task #{task_id}.") if ok else \
                   (False, f"Failed to attach photo to task #{task_id}.")

        elif action_type == "incident":
            incident_type = payload.get("incident_type", "").strip()
            severity = payload.get("severity", "").strip()
            location = payload.get("location", "").strip()
            description = payload.get("description", "").strip()
            if not incident_type or not description:
                return False, "Missing incident type or description in queued action."
            new_incident = create_incident(
                incident_type=incident_type, severity=severity or "Low",
                location=location or "Unspecified", description=description,
                reported_by=queued_by_name,
            )
            _log_offline_sync_decision(action, "approved", reviewed_by, detail=incident_type)
            return (True, f"Incident #{new_incident['id']} reported.") if new_incident else \
                   (False, "Failed to file the incident report.")

        else:
            return False, f"Unknown action type: {action_type}"

    except Exception as e:
        log_error(str(e), endpoint="apply_offline_action", details={"action": action})
        _log_offline_sync_decision(action, "approved", reviewed_by, error=str(e))
        return False, f"Unexpected error: {e}"


def reject_offline_action(action, reviewed_by, reason=None):
    _log_offline_sync_decision(action, "rejected", reviewed_by, detail=reason)


def send_message(sender, receiver, room, message, encrypted=False):
    if not SUPABASE_AVAILABLE:
        msg_id = st.session_state.next_memory_id
        st.session_state.next_memory_id -= 1
        msg = {
            "id": msg_id,
            "sender": sender,
            "receiver": receiver,
            "room": room,
            "message": message,
            "is_encrypted": encrypted,
            "created_at": datetime.now().isoformat()
        }
        st.session_state.setdefault("chat_messages_memory", []).append(msg)
        return True
    try:
        payload = {
            "sender": sender,
            "receiver": receiver,
            "room": room,
            "message": message,
            "is_encrypted": encrypted
        }
        res = supabase.table("chat_messages").insert(payload).execute()
        if not res.data:
            return False
        return True
    except Exception as e:
        log_error(str(e), endpoint="send_message")
        return False

def fetch_messages(room=None, limit=100):
    """Deliberately NOT cached — chat only feels like chat if a
    message sent by someone else shows up on the next rerun, not up
    to a TTL window later. Same reasoning as fetch_notifications and
    fetch_ai_chat_history: real-time feel matters more here than the
    read-cost saving would."""
    if not SUPABASE_AVAILABLE:
        msgs = st.session_state.get("chat_messages_memory", [])
        if room:
            msgs = [m for m in msgs if m["room"] == room]
        return sorted(msgs, key=lambda x: x["created_at"], reverse=True)[:limit]
    try:
        query = supabase.table("chat_messages").select("*").order("created_at", desc=True).limit(limit)
        if room:
            query = query.eq("room", room)
        res = query.execute()
        if res.data:
            return res.data
    except Exception as e:
        log_error(str(e), endpoint="fetch_messages")
        pass
    return []

def delete_message(message_id, deleted_by):
    if message_id < 0:
        st.session_state.chat_messages_memory = [
            m for m in st.session_state.get("chat_messages_memory", [])
            if m["id"] != message_id
        ]
        log_audit(deleted_by, "message_delete_memory", {"message_id": message_id})
        return True
    else:
        if not SUPABASE_AVAILABLE:
            return False
        try:
            msg = supabase.table("chat_messages").select("*").eq("id", message_id).execute()
            res = supabase.table("chat_messages").delete().eq("id", message_id).execute()
            if not res.data:
                return False
            if msg.data:
                log_audit(deleted_by, "message_delete", {"message_id": message_id, "content": msg.data[0]["message"][:50]})
            return True
        except Exception as e:
            log_error(str(e), details={"message_id": message_id}, endpoint="delete_message")
            return False

# -------------------------------
# 17. ENCRYPTION HELPERS (obfuscation)
# -------------------------------
try:
    from cryptography.fernet import Fernet
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
    CRYPTO_AVAILABLE = True
except ImportError:
    CRYPTO_AVAILABLE = False

def derive_key(name1, name2):
    """
    ⚠️ THIS IS OBFUSCATION, NOT SECURE ENCRYPTION. ⚠️

    The key material is just the two usernames, which are public
    within the app, combined with a salt. Anyone who knows both
    usernames can regenerate this key and decrypt the messages.
    It protects against nothing more than a casual glance at the
    raw database rows.

    To make private chat genuinely confidential you need per-user
    asymmetric keypairs, with private keys held client-side and
    never sent to the server. That is a real project, not a patch.
    Until then the UI warns users not to trust this channel.

    CHAT_KEY_SALT (optional, from secrets) at least prevents someone
    reading this public source from deriving keys without also
    having your deployment secret. It does NOT fix the fundamental
    weakness above.
    """
    sorted_names = sorted([name1.lower(), name2.lower()])
    combined = sorted_names[0] + sorted_names[1]
    salt = str(st.secrets.get("CHAT_KEY_SALT", "fixed_salt_for_demo")).encode()
    if CRYPTO_AVAILABLE:
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
        )
        key = base64.urlsafe_b64encode(kdf.derive(combined.encode()))
        return key
    else:
        return base64.urlsafe_b64encode(hashlib.sha256(combined.encode()).digest())

def encrypt_message(message, key):
    if CRYPTO_AVAILABLE:
        f = Fernet(key)
        return f.encrypt(message.encode()).decode()
    else:
        return base64.b64encode(message.encode()).decode()

def decrypt_message(encrypted_msg, key):
    if CRYPTO_AVAILABLE:
        f = Fernet(key)
        return f.decrypt(encrypted_msg.encode()).decode()
    else:
        return base64.b64decode(encrypted_msg.encode()).decode()

