# -------------------------------
# 18B. EXCEL (.xlsx) EXPORTS
# -------------------------------
# Same column selection as the CSV exports above (kept in sync
# deliberately — an xlsx export showing different columns than its
# CSV twin would be a confusing, easy-to-miss inconsistency), just
# written to a styled workbook instead of a comma-joined string.
# Each returns raw bytes for st.download_button, or None if pandas/
# openpyxl aren't available so callers can fall back to the CSV
# button that already exists everywhere these are used.

def _style_xlsx_header(worksheet, ncols):
    """Bold navy header row + auto-sized columns — applied identically
    across every sheet in every export below so a multi-sheet workbook
    doesn't look like it was assembled from mismatched parts."""
    from openpyxl.styles import Font, PatternFill, Alignment
    header_fill = PatternFill(start_color="001530", end_color="001530", fill_type="solid")
    header_font = Font(color="FFFFFF", bold=True)
    for col_idx in range(1, ncols + 1):
        cell = worksheet.cell(row=1, column=col_idx)
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = Alignment(horizontal="left")
    for column_cells in worksheet.columns:
        length = max((len(str(c.value)) if c.value is not None else 0) for c in column_cells)
        worksheet.column_dimensions[column_cells[0].column_letter].width = min(max(length + 2, 10), 50)


def _df_to_xlsx_bytes(sheets):
    """sheets: dict of {sheet_name: DataFrame}. Returns bytes, or None
    if openpyxl isn't installed."""
    if not OPENPYXL_AVAILABLE or not PANDAS_AVAILABLE:
        return None
    buf = BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as writer:
        for sheet_name, df in sheets.items():
            df.to_excel(writer, sheet_name=sheet_name[:31], index=False)  # Excel caps sheet names at 31 chars
            _style_xlsx_header(writer.sheets[sheet_name[:31]], len(df.columns))
    return buf.getvalue()


