def actual_spend_for_asset(asset_id, tasks, parts_lookup):
    """Real spend for one asset, computed live from actual task and
    parts cost data — the same underlying calculation cost_by_asset()
    uses elsewhere in Analytics, just scoped to a single asset_id
    instead of grouped by name. This is what Budget Center compares
    an allocated amount against, so there's never a separately-tracked
    'spent' number that could drift from what tasks actually cost."""
    return sum(task_total_cost(t, parts_lookup) for t in tasks if t.get("asset_id") == asset_id)


@st.cache_data(ttl=1800)
def fetch_weather_forecast():
    """Daily forecast for the configured site, next 7 days, via
    Open-Meteo — no API key needed for non-commercial use, which is
    why this app uses it rather than a key-gated provider. Cached for
    30 minutes: weather forecasts don't change meaningfully minute to
    minute, and this avoids hitting the API on every single Task
    Dashboard page load from every user.

    Returns a list of {date, precip_mm, precip_probability_pct,
    wind_speed_max_kmh, temp_max_c, temp_min_c, weather_code} dicts,
    or an empty list on ANY failure — a down API, a network timeout,
    a malformed response, or the site coordinates not being
    configured at all. This must never be the thing that breaks Task
    Dashboard just because a third-party weather service had a bad
    moment; an empty list means 'no forecast to show,' handled the
    same as 'nothing to warn about' by every caller.

    wind_speed_max_kmh, temp_max_c/min_c, and weather_code are newer
    additions (for the bad-weather email alert — see
    is_bad_weather_day) alongside the original precip fields; every
    existing caller that only reads precip_mm/precip_probability_pct
    keeps working unchanged.
    """
    if not WEATHER_CONFIGURED:
        return []
    try:
        resp = requests.get(
            "https://api.open-meteo.com/v1/forecast",
            params={
                "latitude": MINE_LATITUDE, "longitude": MINE_LONGITUDE,
                "daily": ("precipitation_sum,precipitation_probability_max,"
                         "windspeed_10m_max,temperature_2m_max,temperature_2m_min,weathercode"),
                "forecast_days": 7, "timezone": "auto",
            },
            timeout=8,
        )
        resp.raise_for_status()
        data = resp.json()
        daily = data.get("daily", {})
        dates = daily.get("time", [])
        precip_mm = daily.get("precipitation_sum", [])
        precip_prob = daily.get("precipitation_probability_max", [])
        wind_max = daily.get("windspeed_10m_max", [])
        temp_max = daily.get("temperature_2m_max", [])
        temp_min = daily.get("temperature_2m_min", [])
        weather_code = daily.get("weathercode", [])
        return [
            {"date": d, "precip_mm": precip_mm[i] if i < len(precip_mm) else None,
            "precip_probability_pct": precip_prob[i] if i < len(precip_prob) else None,
            "wind_speed_max_kmh": wind_max[i] if i < len(wind_max) else None,
            "temp_max_c": temp_max[i] if i < len(temp_max) else None,
            "temp_min_c": temp_min[i] if i < len(temp_min) else None,
            "weather_code": weather_code[i] if i < len(weather_code) else None}
            for i, d in enumerate(dates)
        ]
    except Exception as e:
        log_error(str(e), endpoint="fetch_weather_forecast")
        return []


# WMO weather codes (used by Open-Meteo) that represent genuinely
# hazardous conditions for outdoor mine/workshop work — thunderstorms,
# heavy/freezing rain, heavy snow, blizzard. Not every non-zero code
# (light drizzle, overcast) counts as "bad" on its own; those are
# already covered by the precipitation-probability threshold.
SEVERE_WEATHER_CODES = {65, 67, 75, 82, 86, 95, 96, 99}
BAD_WEATHER_WIND_KMH = 50
BAD_WEATHER_PRECIP_PROB_PCT = 70


def is_bad_weather_day(day):
    """True if a single forecast day (one dict from
    fetch_weather_forecast) crosses any hazard threshold: high
    rain probability, damaging wind, or a severe WMO weather code
    (thunderstorm, heavy/freezing precipitation, blizzard). Any ONE
    of these is enough — they're different hazards, not points on
    the same scale."""
    if not day:
        return False
    if (day.get("precip_probability_pct") or 0) >= BAD_WEATHER_PRECIP_PROB_PCT:
        return True
    if (day.get("wind_speed_max_kmh") or 0) >= BAD_WEATHER_WIND_KMH:
        return True
    if day.get("weather_code") in SEVERE_WEATHER_CODES:
        return True
    return False


def electrical_digest_recipients():
    """Who 'owns' the Electrical Department in this app: there's no
    dedicated electrical-manager role (only worker/supervisor/
    superintendent exist), so this targets everyone with supervisor or
    superintendent role, plus the app owner — the same audience the
    on-screen predictive/calibration alerts already target elsewhere
    in Task Dashboard. Only users with a real (non-placeholder) email
    on file can actually receive it."""
    recipients = []
    for u in fetch_all_users_from_db():
        if u.get("role") in ("supervisor", "superintendent") or is_owner(u.get("username", "")):
            _email = u.get("email")
            if _email and not str(_email).endswith("@mwdts.internal"):
                recipients.append({"username": u.get("username"), "full_name": u.get("full_name"), "email": _email})
    return recipients


# -------------------------------
# 20K. WEATHER ALERT EMAILS
# -------------------------------
# Two distinct email types, both built on fetch_weather_forecast() /
# is_bad_weather_day():
#   - 'bad_weather': fires as soon as hazardous conditions are
#     forecast within the next 48h, cooled down to at most once every
#     6 hours so repeated trigger calls don't spam the same alert.
#   - 'routine_12h': a status email regardless of conditions (good or
#     bad), cooled down to once every 12 hours.
# Neither is a real background job — see run_weather_email_check's
# docstring for how to actually get 12-hourly delivery via an
# external trigger, the same honest limitation already noted on
# run_escalations and the Electrical digest above.
WEATHER_BAD_ALERT_COOLDOWN_HOURS = 6
WEATHER_ROUTINE_COOLDOWN_HOURS = 12
def site_leadership_recipients():
    """Supervisors, superintendents, and the owner with a real
    (non-placeholder) email on file — the same audience as the
    Electrical Department digest, reused here rather than duplicated
    logic that could quietly drift from it over time."""
    return electrical_digest_recipients()


def _weather_alert_last_sent(alert_type):
    """Returns the datetime this alert type was last sent, or None if
    never (or if the log table doesn't exist yet / DB unavailable —
    treated as 'never sent' so the feature fails open to sending
    rather than silently never firing)."""
    if not SUPABASE_AVAILABLE:
        return None
    try:
        res = (supabase.table("weather_alert_log").select("sent_at")
              .eq("alert_type", alert_type).order("sent_at", desc=True).limit(1).execute())
        if res.data:
            return _parse_dt(res.data[0]["sent_at"])
    except Exception as e:
        log_error(str(e), endpoint="_weather_alert_last_sent", details={"alert_type": alert_type})
    return None


