def _weather_email_body(forecast, bad_days, is_bad_weather_alert):
    """Shared HTML builder for both weather email types — the routine
    12h email and the bad-weather alert use the same layout, just a
    different headline and urgency color, so the two never visually
    diverge into inconsistent formats."""
    today = forecast[0] if forecast else {}
    rows = "".join(f"""
        <tr>
            <td style="padding:6px 10px;">{d['date']}</td>
            <td style="padding:6px 10px;">{d.get('temp_min_c', '?')}–{d.get('temp_max_c', '?')}°C</td>
            <td style="padding:6px 10px;">{d.get('precip_probability_pct', '?')}% rain</td>
            <td style="padding:6px 10px;">{d.get('wind_speed_max_kmh', '?')} km/h wind</td>
            <td style="padding:6px 10px; color:{'#dc2626' if is_bad_weather_day(d) else '#16a34a'};">
                {'⚠️ Hazardous' if is_bad_weather_day(d) else 'OK'}
            </td>
        </tr>""" for d in forecast[:5])

    if is_bad_weather_alert:
        headline = "⚠️ Hazardous Weather Forecast"
        headline_color = "#dc2626"
        intro = (f"<p>Hazardous conditions are forecast for the site within the next 2 days "
                f"({', '.join(d['date'] for d in bad_days)}). Review weather-sensitive tasks "
                f"before dispatching crews.</p>")
    else:
        headline = "🌤️ Site Weather Status"
        headline_color = "#0f3460"
        intro = (f"<p>Current forecast: {today.get('temp_min_c', '?')}–{today.get('temp_max_c', '?')}°C, "
                f"{today.get('precip_probability_pct', '?')}% chance of rain, "
                f"{today.get('wind_speed_max_kmh', '?')} km/h max wind.</p>")

    return f"""
    <h2 style="color:{headline_color};">{headline}</h2>
    {intro}
    <table style="border-collapse:collapse; width:100%;">
        <tr style="background:#001530; color:white;">
            <th style="padding:6px 10px; text-align:left;">Date</th>
            <th style="padding:6px 10px; text-align:left;">Temp</th>
            <th style="padding:6px 10px; text-align:left;">Rain</th>
            <th style="padding:6px 10px; text-align:left;">Wind</th>
            <th style="padding:6px 10px; text-align:left;">Status</th>
        </tr>
        {rows}
    </table>
    <p style="color:#94a3b8; font-size:0.85em;">
        Sent because you're a supervisor, superintendent, or owner in MWDTS.
        Weather-sensitive tasks are cross-checked automatically on Task Dashboard.
    </p>
    """


def run_weather_email_check(triggered_by=None, force=False):
    """The single entry point for both weather email types — called
    from the manual Owner Console button AND from the external
    automation trigger endpoint (see the app.py header comment near
    the ?health=1 handler for the matching ?weather_check=1 one).

    Genuine 12-hourly (or 6-hourly bad-weather) delivery needs
    something OUTSIDE this app calling this on a real schedule —
    Streamlit itself has no background scheduler, the same honest
    limitation as run_escalations and the Electrical digest. Point an
    external scheduled job (a GitHub Action cron, or a Supabase Edge
    Function) at the ?weather_check=1&token=... trigger on some
    reasonable interval (hourly is plenty); THIS function's own
    cooldown tracking (WEATHER_BAD_ALERT_COOLDOWN_HOURS /
    WEATHER_ROUTINE_COOLDOWN_HOURS) decides whether an email is
    actually due each time it's called, so the external job doesn't
    need to itself track a 12-hour cadence — it can just call this
    often and trust the cooldowns.

    force=True bypasses both cooldowns — used by the manual "send
    test email now" button so a person testing the setup doesn't have
    to wait out a cooldown to see it work.

    Returns a summary dict for the caller to display.
    """
    if not WEATHER_CONFIGURED:
        return {"sent": False, "reason": "Weather not configured (MINE_LATITUDE/MINE_LONGITUDE)."}
    forecast = fetch_weather_forecast()
    if not forecast:
        return {"sent": False, "reason": "Could not fetch a forecast right now."}

    recipients = site_leadership_recipients()
    bad_days = [d for d in forecast[:2] if is_bad_weather_day(d)]
    results = {"bad_weather_sent": False, "routine_sent": False, "recipients": len(recipients)}

    if bad_days:
        last_bad = _weather_alert_last_sent("bad_weather")
        due = force or not last_bad or (datetime.now() - last_bad) >= timedelta(hours=WEATHER_BAD_ALERT_COOLDOWN_HOURS)
        if due:
            subject = f"⚠️ Hazardous Weather Forecast — {datetime.now().strftime('%B %d, %Y')}"
            body = _weather_email_body(forecast, bad_days, is_bad_weather_alert=True)
            sent = sum(1 for r in recipients if send_email_notification(r["email"], subject, body))
            _log_weather_alert_sent("bad_weather", len(recipients), sent)
            log_audit(triggered_by or "system", "weather_bad_alert_sent",
                     {"recipient_count": len(recipients), "sent_count": sent})
            results["bad_weather_sent"] = True
            results["bad_weather_sent_count"] = sent

    last_routine = _weather_alert_last_sent("routine_12h")
    routine_due = force or not last_routine or (datetime.now() - last_routine) >= timedelta(hours=WEATHER_ROUTINE_COOLDOWN_HOURS)
    if routine_due:
        subject = f"🌤️ Site Weather Status — {datetime.now().strftime('%B %d, %Y %H:%M')}"
        body = _weather_email_body(forecast, bad_days, is_bad_weather_alert=False)
        sent = sum(1 for r in recipients if send_email_notification(r["email"], subject, body))
        _log_weather_alert_sent("routine_12h", len(recipients), sent)
        log_audit(triggered_by or "system", "weather_routine_email_sent",
                 {"recipient_count": len(recipients), "sent_count": sent})
        results["routine_sent"] = True
        results["routine_sent_count"] = sent

    results["sent"] = results["bad_weather_sent"] or results["routine_sent"]
    return results


def weather_sensitive_tasks_at_risk(tasks, forecast, probability_threshold=60):
    """Cross-references weather-sensitive, not-yet-complete tasks
    against the forecast, returning (task, forecast_day) pairs for
    any day within the forecast where rain probability exceeds the
    threshold — regardless of a task's own due_date, since a
    weather-sensitive task without a specific due date is still worth
    flagging against tomorrow's forecast, not just tasks explicitly
    scheduled for a matching date."""
    if not forecast:
        return []
    risky_days = [d for d in forecast
                 if (d.get("precip_probability_pct") or 0) >= probability_threshold]
    if not risky_days:
        return []
    at_risk = []
    for t in tasks:
        if not t.get("weather_sensitive") or t.get("status") in ("Complete", "Blocked"):
            continue
        for day in risky_days:
            at_risk.append((t, day))
    return at_risk


@st.cache_data(ttl=86400)
def fetch_historical_weather(start_date, end_date):
    """Daily precipitation for a past date range, via Open-Meteo's
    Historical Weather API — a DIFFERENT subdomain
    (archive-api.open-meteo.com) than the forecast endpoint
    (api.open-meteo.com), easy to get wrong by assuming they share a
    host. Same no-key access for non-commercial use.

    Cached for 24 hours rather than 30 minutes like the forecast —
    historical data for a past date never changes, so there's no
    reason to refetch it as often as a live forecast.

    ERA5 data has roughly a 5-day processing delay, so very recent
    dates may come back without data — this isn't a bug in this
    function, just how the underlying dataset updates. Returns an
    empty list on any failure, same defensive contract as
    fetch_weather_forecast — a down API must never break whatever
    page called this.
    """
    if not WEATHER_CONFIGURED:
        return []
    try:
        resp = requests.get(
            "https://archive-api.open-meteo.com/v1/archive",
            params={
                "latitude": MINE_LATITUDE, "longitude": MINE_LONGITUDE,
                "start_date": start_date.strftime("%Y-%m-%d"),
                "end_date": end_date.strftime("%Y-%m-%d"),
                "daily": "precipitation_sum", "timezone": "auto",
            },
            timeout=10,
        )
        resp.raise_for_status()
        data = resp.json()
        daily = data.get("daily", {})
        dates = daily.get("time", [])
        precip = daily.get("precipitation_sum", [])
        return [{"date": d, "precip_mm": precip[i] if i < len(precip) else None}
                for i, d in enumerate(dates)]
    except Exception as e:
        log_error(str(e), endpoint="fetch_historical_weather")
        return []


def rainy_vs_dry_production(production_records, historical_weather, rain_threshold_mm=1.0):
    """Compares average DAILY ore production on rainy days vs dry
    days. Ore-only, same reasoning as the KPI target comparison —
    mixing in waste rock would produce a number that doesn't mean
    what it claims to. A day counts as 'rainy' if precipitation_sum
    exceeds rain_threshold_mm (1mm default — enough to distinguish a
    genuine rain day from trace/measurement noise, not so high that
    a moderate but real rainy day gets miscounted as dry).

    Only dates with BOTH a known ore total AND known weather are
    used — a date missing either is excluded rather than guessed at.
    Returns a dict with rainy/dry average daily tonnes, sample sizes
    for each, and the percentage difference — or None fields where
    there isn't enough data to say anything real, rather than a
    misleading number built from too little.
    """
    weather_by_date = {d["date"]: d.get("precip_mm") for d in historical_weather if d.get("precip_mm") is not None}

    ore_by_date = {}
    for r in production_records:
        if "ore" not in (r.get("material_type") or "").lower():
            continue
        date_key = r.get("production_date")
        ore_by_date[date_key] = ore_by_date.get(date_key, 0) + (r.get("quantity") or 0)

    rainy_totals, dry_totals = [], []
    for date_key, ore_qty in ore_by_date.items():
        if date_key not in weather_by_date:
            continue
        if weather_by_date[date_key] > rain_threshold_mm:
            rainy_totals.append(ore_qty)
        else:
            dry_totals.append(ore_qty)

    rainy_avg = sum(rainy_totals) / len(rainy_totals) if rainy_totals else None
    dry_avg = sum(dry_totals) / len(dry_totals) if dry_totals else None
    pct_loss = None
    if rainy_avg is not None and dry_avg is not None and dry_avg > 0:
        pct_loss = (dry_avg - rainy_avg) / dry_avg * 100

    return {
        "rainy_avg_tonnes": rainy_avg, "rainy_days": len(rainy_totals),
        "dry_avg_tonnes": dry_avg, "dry_days": len(dry_totals),
        "pct_loss_on_rainy_days": pct_loss,
    }


def create_shipment(material_type, quantity, unit, transport_mode, destination, carrier,
                    expected_arrival, created_by):
    fetch_shipments.clear()
    shipment_ref = f"SHP-{datetime.now().strftime('%Y%m%d')}-{secrets.token_hex(4).upper()}"
    payload = {
        "shipment_ref": shipment_ref, "material_type": material_type, "quantity": quantity,
        "unit": unit, "transport_mode": transport_mode, "destination": destination,
        "carrier": carrier, "status": "Scheduled",
        "expected_arrival": expected_arrival.isoformat() if expected_arrival else None,
        "created_by": created_by,
    }
    if not SUPABASE_AVAILABLE:
        return None
    try:
        res = supabase.table("haulage_shipments").insert(payload).execute()
        if not res.data:
            log_error("haulage_shipments insert affected 0 rows — likely RLS blocking writes",
                     endpoint="create_shipment")
            return None
        log_audit(created_by, "shipment_created", {"shipment_ref": shipment_ref})
        return res.data[0]
    except Exception as e:
        log_error(str(e), details=payload, endpoint="create_shipment")
        return None


def mark_shipment_departed(shipment_id, updated_by):
    if not SUPABASE_AVAILABLE:
        return False
    try:
        res = supabase.table("haulage_shipments").update({
            "status": "In Transit", "departure_time": datetime.now().isoformat(),
        }).eq("id", shipment_id).execute()
        if not res.data:
            return False
        log_audit(updated_by, "shipment_departed", {"shipment_id": shipment_id})
        return True
    except Exception as e:
        log_error(str(e), endpoint="mark_shipment_departed")
        return False


def mark_shipment_arrived(shipment_id, delay_reason, updated_by):
    """Records the actual arrival time as right now. Lateness itself
    is NOT stored here — it's computed by comparing actual_arrival
    against expected_arrival wherever it's needed, the same
    don't-store-a-derived-fact principle already used for Budget
    Center's spend tracking. delay_reason is optional free text,
    worth capturing even for an on-time arrival in case something
    relevant happened en route that didn't end up costing time."""
    if not SUPABASE_AVAILABLE:
        return False
    try:
        res = supabase.table("haulage_shipments").update({
            "status": "Delivered", "actual_arrival": datetime.now().isoformat(),
            "delay_reason": delay_reason or None,
        }).eq("id", shipment_id).execute()
        if not res.data:
            return False
        log_audit(updated_by, "shipment_arrived", {"shipment_id": shipment_id})
        return True
    except Exception as e:
        log_error(str(e), endpoint="mark_shipment_arrived")
        return False


@st.cache_data(ttl=120, show_spinner=False)
def fetch_shipments(status=None, limit=200):
    if not SUPABASE_AVAILABLE:
        return []
    try:
        q = supabase.table("haulage_shipments").select("*")
        if status:
            q = q.eq("status", status)
        res = q.order("created_at", desc=True).limit(limit).execute()
        return res.data or []
    except Exception as e:
        log_error(str(e), endpoint="fetch_shipments")
        return []


def shipment_delay_hours(shipment):
    """Positive = late, negative = early, None = can't be computed
    yet (no actual_arrival recorded, or no expected_arrival was ever
    set for this shipment)."""
    actual = _parse_dt(shipment.get("actual_arrival"))
    expected = _parse_dt(shipment.get("expected_arrival"))
    if not actual or not expected:
        return None
    return (actual - expected).total_seconds() / 3600.0


def average_delay_hours(shipments):
    """Average delay across delivered shipments that actually have
    both timestamps to compare — shipments still in transit, or
    missing an expected_arrival, are excluded rather than silently
    treated as zero delay, which would understate the real average."""
    delays = [d for d in (shipment_delay_hours(s) for s in shipments) if d is not None]
    if not delays:
        return None
    return sum(delays) / len(delays)


def fleet_average_utilization(assets, window_start, window_end):
    """Averages compute_asset_utilization() across every asset that
    HAS enough status history to produce a real number — assets with
    zero logged transitions are excluded from the average entirely,
    not counted as 0% (which would understate fleet performance) or
    100% (which would overstate it). Returns (avg_pct, assets_counted,
    assets_total) so a caller can show 'based on N of M assets' rather
    than presenting a fleet-wide figure that's silently based on only
    a fraction of the actual fleet."""
    utils = []
    for a in assets:
        pct, _coverage = compute_asset_utilization(a["id"], window_start, window_end)
        if pct is not None:
            utils.append(pct)
    if not utils:
        return None, 0, len(assets)
    return sum(utils) / len(utils), len(utils), len(assets)


def mttr_trend(tasks, now=None):
    """This-month vs last-month MTTR, using the same
    compute_mttr_hours_v2 calculation already trusted elsewhere in
    Analytics — not a separate, parallel calculation that could give
    a different answer for the same underlying question. Returns
    (this_month_hours, this_month_n, last_month_hours, last_month_n).
    Any value can independently be None if that period doesn't have
    enough completed tasks to compute a real number — a missing prior
    month must never be silently treated as 0 (which would make any
    real MTTR look like a worsening trend by comparison)."""
    now = now or datetime.now()
    this_month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    last_month_end = this_month_start
    last_month_start = (this_month_start - timedelta(days=1)).replace(day=1)

    def _completed_in_range(task, start, end):
        completed = _parse_dt(task.get("completed_at"))
        return completed is not None and start <= completed < end

    this_month_tasks = [t for t in tasks if _completed_in_range(t, this_month_start, now)]
    last_month_tasks = [t for t in tasks if _completed_in_range(t, last_month_start, last_month_end)]

    this_hours, this_n = compute_mttr_hours_v2(this_month_tasks)
    last_hours, last_n = compute_mttr_hours_v2(last_month_tasks)
    return this_hours, this_n, last_hours, last_n


def average_ore_grade(records):
    """Average grade across production records that actually have
    one logged — most records won't (grade is optional, and doesn't
    apply to waste rock at all), so this must exclude anything
    missing rather than treat it as 0%, which would badly understate
    real ore quality. Returns (avg_pct, sample_size) so the UI can
    show how many shift logs the average is actually based on."""
    graded = [r.get("ore_grade_pct") for r in records if r.get("ore_grade_pct") is not None]
    if not graded:
        return None, 0
    return sum(graded) / len(graded), len(graded)


def run_escalations(tasks, permits, triggered_by):
    """Checks for overdue tasks and soon-to-expire permits, sending a
    notification for each. This is NOT a scheduled background job —
    Streamlit has no true scheduler, so this only runs when something
    in the app actually calls it (a button click, or once per session
    on load). A permit expiring at 3am with nobody using the app
    won't trigger anything until someone next opens it. Genuine
    always-on scheduling would need something outside this app
    entirely — e.g. a scheduled GitHub Action or Supabase Edge
    Function hitting a dedicated trigger — not something this
    function can promise on its own.

    Fixes a real bug from the original source material: it hardcoded
    a single username ("superintendent1") to notify, which would
    silently fail to reach anyone else holding that role. This
    notifies every actual superintendent instead.
    """
    if not SUPABASE_AVAILABLE:
        return {"overdue_notified": 0, "permits_notified": 0}

    superintendents = [u["full_name"] for u in fetch_all_users_from_db()
                       if u.get("role", "").strip().lower() == "superintendent"
                       and u.get("is_approved") and u.get("full_name")]

    # Collected per-recipient rather than sent as we go, so a
    # superintendent with 5 overdue tasks gets ONE push ("5 tasks
    # overdue") instead of 5 separate interruptions — see
    # send_grouped_notification below. Same reasoning for permits.
    overdue_by_recipient = {s_name: [] for s_name in superintendents}
    overdue_count = 0
    now = datetime.now()
    for task in tasks:
        if task.get("status") in ("Complete", "Blocked"):
            continue
        due = _parse_dt(task.get("due_date"))
        if due and due < now:
            for s_name in superintendents:
                overdue_by_recipient[s_name].append(task)
            overdue_count += 1
    for s_name, overdue_tasks in overdue_by_recipient.items():
        send_grouped_notification(
            s_name, "Task Overdue", overdue_tasks,
            item_label_fn=lambda t: f"#{t['id']} {t.get('title', '')}",
            category="task_overdue")

    permit_count = 0
    permits_by_recipient = {}
    soon = now + timedelta(hours=1)
    for p in permits:
        if p.get("status") != "Active":
            continue
        valid_until = _parse_dt(p.get("valid_until"))
        if valid_until and now < valid_until < soon:
            _issuer = p.get("issued_by")
            if _issuer:
                permits_by_recipient.setdefault(_issuer, []).append(p)
            permit_count += 1
    for _issuer, expiring_permits in permits_by_recipient.items():
        send_grouped_notification(
            _issuer, "Permit Expiring Soon", expiring_permits,
            item_label_fn=lambda p: f"#{p['id']} ({p.get('permit_type')})",
            category="permit_expiring")

    log_audit(triggered_by, "escalations_run", {"overdue": overdue_count, "permits_expiring": permit_count})
    return {"overdue_notified": overdue_count, "permits_notified": permit_count}


def detect_meter_anomaly(asset_id):
    """Flags the latest meter reading for an asset as anomalous.

    Upgraded from a plain mean/2-sigma check to a MEDIAN-ABSOLUTE-
    DEVIATION (MAD) based robust z-score — this is the real weakness
    a full ML model (e.g. Isolation Forest) would also be solving
    here, but MAD gets the same core benefit without it: a single
    wild outlier reading badly skews a plain mean and standard
    deviation, which can actually HIDE the very outlier that caused
    the skew (the classic failure mode of 2-sigma-on-mean). The
    median and MAD barely move when one point is extreme, so the
    check stays accurate even when the anomaly itself is in the
    dataset it's being compared against.

    A trained model (Isolation Forest or similar) was deliberately
    NOT used here: it needs a real training pipeline and enough
    historical density per asset to fit meaningfully, neither of
    which a fresh mine deployment has on day one, and it would add a
    scikit-learn dependency for a single-variable (meter reading)
    signal that a robust statistical test already handles well. A
    trained model becomes worth it once there's genuine multi-sensor
    telemetry (temperature, vibration, pressure) to find correlated
    patterns across — see the Live Sensor Feeds / IoT roadmap item,
    which is what would actually feed a model like that.

    Still needs at least 10 readings to say anything meaningful —
    same "not enough data yet" reasoning as before.
    """
    if not SUPABASE_AVAILABLE:
        return False
    try:
        res = supabase.table("meter_readings").select("reading").eq("asset_id", asset_id) \
            .order("recorded_at", desc=True).limit(50).execute()
        vals = [float(r["reading"]) for r in (res.data or []) if r.get("reading") is not None]
        if len(vals) < 10:
            return False
        sorted_vals = sorted(vals)
        n = len(sorted_vals)
        median = sorted_vals[n // 2] if n % 2 else (sorted_vals[n // 2 - 1] + sorted_vals[n // 2]) / 2
        abs_deviations = sorted([abs(x - median) for x in vals])
        mad = abs_deviations[n // 2] if n % 2 else (abs_deviations[n // 2 - 1] + abs_deviations[n // 2]) / 2
        if mad == 0:
            return False
        # 0.6745 scales MAD to be comparable to a standard deviation
        # for normally-distributed data — the standard conversion
        # factor, so "3.5" below reads like a familiar sigma threshold.
        robust_z = 0.6745 * (vals[0] - median) / mad
        return abs(robust_z) > 3.5
    except Exception as e:
        log_error(str(e), endpoint="detect_meter_anomaly")
        return False


def detect_meter_anomaly_ml(asset_id, lookback=100):
    """Isolation Forest anomaly check — a genuine trained model, run
    alongside (not instead of) the MAD-based detect_meter_anomaly()
    above. Requires scikit-learn AND at least 20 readings; returns
    (None, None) rather than False when either condition isn't met,
    so callers can tell 'checked, not anomalous' apart from 'couldn't
    check' instead of both collapsing to a false negative.

    Feature engineering note: this app only logs one signal per asset
    (the meter reading) — there's no true multi-sensor telemetry
    (temperature, vibration, pressure) yet. To still give Isolation
    Forest real multivariate structure to work with rather than a
    single flat number, each point is expanded into 4 engineered
    features: the raw reading, its delta from the previous reading,
    and a rolling mean/std over the last 5 readings. That's a
    meaningfully richer signal than the single-number MAD check
    above, even though it's derived from the same underlying stream —
    genuine multi-sensor input would still be a further improvement
    once the IoT / Live Sensor Feeds roadmap item exists to supply it.

    Returns (is_anomaly: bool, anomaly_score: float) — score is
    sklearn's own decision_function output for the latest point, more
    negative meaning more anomalous, useful for showing "how unusual"
    rather than just a yes/no.
    """
    if not SKLEARN_AVAILABLE or not SUPABASE_AVAILABLE:
        return None, None
    try:
        res = supabase.table("meter_readings").select("reading, recorded_at") \
            .eq("asset_id", asset_id).order("recorded_at", desc=False).limit(lookback).execute()
        rows = res.data or []
        vals = [float(r["reading"]) for r in rows if r.get("reading") is not None]
        if len(vals) < 20:
            return None, None

        window = 5
        features = []
        for i in range(window, len(vals)):
            recent = vals[i - window:i + 1]
            mean_recent = sum(recent) / len(recent)
            std_recent = (sum((v - mean_recent) ** 2 for v in recent) / len(recent)) ** 0.5
            delta = vals[i] - vals[i - 1]
            features.append([vals[i], delta, mean_recent, std_recent])
        if len(features) < 10:
            return None, None

        model = IsolationForest(contamination=0.1, random_state=42, n_estimators=100)
        model.fit(features)
        latest = [features[-1]]
        is_anomaly = bool(model.predict(latest)[0] == -1)
        score = float(model.decision_function(latest)[0])
        return is_anomaly, score
    except Exception as e:
        log_error(str(e), endpoint="detect_meter_anomaly_ml", details={"asset_id": asset_id})
        return None, None


def detect_meter_anomaly_autoencoder(asset_id, lookback=100):
    """Autoencoder-style anomaly check — an MLPRegressor with a
    bottleneck hidden layer (smaller than the input) trained to
    reconstruct its own input. A point the network can't reconstruct
    well (high reconstruction error) is the anomaly signal — this is
    the standard autoencoder approach to anomaly detection, just
    implemented with scikit-learn's MLPRegressor instead of a
    TensorFlow/PyTorch model, since a full deep-learning framework
    would be a much heavier dependency than this small, mostly-
    tabular dataset actually needs or benefits from.

    Same 4 engineered features as detect_meter_anomaly_ml (raw
    reading, delta, rolling mean, rolling std) — offered as an
    alternative model on the SAME feature set, so the two can be
    meaningfully compared rather than each also varying in what data
    they're given.
    """
    if not SKLEARN_AVAILABLE or not SUPABASE_AVAILABLE:
        return None, None
    try:
        res = supabase.table("meter_readings").select("reading, recorded_at") \
            .eq("asset_id", asset_id).order("recorded_at", desc=False).limit(lookback).execute()
        rows = res.data or []
        vals = [float(r["reading"]) for r in rows if r.get("reading") is not None]
        if len(vals) < 20:
            return None, None

        window = 5
        features = []
        for i in range(window, len(vals)):
            recent = vals[i - window:i + 1]
            mean_recent = sum(recent) / len(recent)
            std_recent = (sum((v - mean_recent) ** 2 for v in recent) / len(recent)) ** 0.5
            delta = vals[i] - vals[i - 1]
            features.append([vals[i], delta, mean_recent, std_recent])
        if len(features) < 10:
            return None, None

        scaler = StandardScaler()
        Xs = scaler.fit_transform(features)
        bottleneck = max(1, Xs.shape[1] // 2)
        model = MLPRegressor(hidden_layer_sizes=(bottleneck,), activation="tanh",
                             max_iter=2000, random_state=42)
        model.fit(Xs, Xs)
        recon = model.predict(Xs)
        errors = ((Xs - recon) ** 2).mean(axis=1)
        threshold = errors[:-1].mean() + 3 * errors[:-1].std() if len(errors) > 1 else errors.mean()
        is_anomaly = bool(errors[-1] > threshold)
        return is_anomaly, float(errors[-1])
    except Exception as e:
        log_error(str(e), endpoint="detect_meter_anomaly_autoencoder", details={"asset_id": asset_id})
        return None, None


def _build_asset_feature_matrix(asset_id, lookback_days=60):
    """Builds a daily-binned multi-dimensional feature matrix from
    EVERY signal actually logged for this asset — the meter reading
    plus every distinct sensor_type in sensor_readings with at least
    5 readings. This is what makes multi-sensor anomaly detection
    genuinely multivariate (real distinct physical signals), not just
    engineered features from one stream — that fallback still exists
    (see detect_meter_anomaly_ml/_autoencoder) for assets with no
    sensor_readings logged yet.

    Missing days within a series are forward-filled from the last
    known value — standard practice for irregularly-sampled sensor
    data — rather than dropped, so one sparser sensor doesn't shrink
    the usable date range for every other signal.

    Returns (dates, matrix, column_names), or (None, None, None) if
    there isn't at least one usable signal with enough history.
    """
    if not SUPABASE_AVAILABLE:
        return None, None, None
    cutoff = datetime.now() - timedelta(days=lookback_days)
    series = {}

    try:
        mres = (supabase.table("meter_readings").select("reading, recorded_at")
               .eq("asset_id", asset_id).gte("recorded_at", cutoff.isoformat())
               .order("recorded_at", desc=False).execute())
        meter_rows = mres.data or []
        if len(meter_rows) >= 5:
            day_vals = {}
            for r in meter_rows:
                d = _parse_dt(r.get("recorded_at"))
                if d and r.get("reading") is not None:
                    day_vals[d.date()] = float(r["reading"])
            if day_vals:
                series["meter"] = day_vals
    except Exception as e:
        log_error(str(e), endpoint="_build_asset_feature_matrix:meter")

    for sensor_type in get_asset_sensor_types(asset_id):
        rows = fetch_sensor_readings(asset_id, sensor_type=sensor_type, limit=500)
        day_vals = {}
        for r in rows:
            d = _parse_dt(r.get("recorded_at"))
            if d and d >= cutoff and r.get("value") is not None:
                day_vals[d.date()] = float(r["value"])
        if len(day_vals) >= 5:
            series[sensor_type] = day_vals

    if not series:
        return None, None, None

    all_dates = sorted(set().union(*[set(v.keys()) for v in series.values()]))
    columns = list(series.keys())
    matrix, usable_dates, last_known = [], [], {}
    for d in all_dates:
        row = []
        ok = True
        for col in columns:
            if d in series[col]:
                last_known[col] = series[col][d]
            if col not in last_known:
                ok = False
                break
            row.append(last_known[col])
        if ok:
            matrix.append(row)
            usable_dates.append(d)

    if len(matrix) < 10:
        return None, None, None
    return usable_dates, matrix, columns


def detect_asset_anomaly_ml(asset_id, method="isolation_forest", lookback_days=60):
    """Unified anomaly check that uses every signal actually logged
    for an asset. Automatically upgrades to genuine multi-sensor
    detection (real distinct signals: meter + temperature + vibration
    + whatever else has been logged) once there's enough sensor
    history, and transparently falls back to the single-meter
    engineered-feature approach for assets with no sensor_readings
    yet — so this always uses the richest data actually available
    rather than requiring sensor logging to be set up first.

    method: "isolation_forest" or "autoencoder" (see
    detect_meter_anomaly_autoencoder's docstring for what that means
    here — an MLPRegressor reconstruction-error model, not a
    TensorFlow/PyTorch deep autoencoder).

    Returns (is_anomaly, score, columns_used) — columns_used lets the
    caller show an honest "this is based on: meter, temperature" list
    rather than implying more sensors were involved than actually
    were.
    """
    if not SKLEARN_AVAILABLE:
        return None, None, None
    dates, matrix, columns = _build_asset_feature_matrix(asset_id, lookback_days)
    if matrix is None:
        if method == "autoencoder":
            is_anom, score = detect_meter_anomaly_autoencoder(asset_id)
        else:
            is_anom, score = detect_meter_anomaly_ml(asset_id)
        return is_anom, score, (["meter (engineered)"] if is_anom is not None else None)

    try:
        if method == "autoencoder":
            scaler = StandardScaler()
            Xs = scaler.fit_transform(matrix)
            bottleneck = max(1, Xs.shape[1] // 2)
            model = MLPRegressor(hidden_layer_sizes=(bottleneck,), activation="tanh",
                                 max_iter=2000, random_state=42)
            model.fit(Xs, Xs)
            recon = model.predict(Xs)
            errors = ((Xs - recon) ** 2).mean(axis=1)
            threshold = errors[:-1].mean() + 3 * errors[:-1].std() if len(errors) > 1 else errors.mean()
            is_anomaly = bool(errors[-1] > threshold)
            score = float(errors[-1])
        else:
            model = IsolationForest(contamination=0.1, random_state=42, n_estimators=100)
            model.fit(matrix)
            is_anomaly = bool(model.predict([matrix[-1]])[0] == -1)
            score = float(model.decision_function([matrix[-1]])[0])
        return is_anomaly, score, columns
    except Exception as e:
        log_error(str(e), endpoint="detect_asset_anomaly_ml", details={"asset_id": asset_id})
        return None, None, None


def detect_cost_anomalies(tasks, parts_lookup):
    """Flags completed tasks whose total cost is more than 2 standard
    deviations from the mean cost of OTHER tasks in the same work
    type — same simple, transparent statistical approach as
    detect_meter_anomaly() (not a trained model), extended to a new
    dimension rather than a separate detection philosophy, so both
    anomaly checks in this app reason about "unusual" the same way.

    Grouped by work_type specifically, not compared against the whole
    fleet at once — a Reactive emergency repair and a routine
    Preventive check have very different normal cost ranges, so
    comparing a task only against its own category's mean is what
    makes a flagged outlier actually meaningful rather than just
    "more expensive than an unrelated routine task."

    Needs at least 5 other tasks in the same category to compute a
    meaningful mean/std — returns no flags for categories below that,
    same "not enough data yet" reasoning as the meter check.

    Returns a list of dicts (task_id, title, work_type, cost, category_mean),
    worst (furthest from the mean) first.
    """
    by_category = {}
    for t2 in tasks:
        if t2.get("status") != "Complete":
            continue
        category = t2.get("work_type") or "Unspecified"
        cost = task_total_cost(t2, parts_lookup)
        by_category.setdefault(category, []).append({"task_id": t2["id"], "title": t2.get("title"), "cost": cost})

    anomalies = []
    for category, entries in by_category.items():
        if len(entries) < 6:  # need at least 5 OTHERS to compare each task against
            continue
        costs = [e["cost"] for e in entries]
        mean = sum(costs) / len(costs)
        variance = sum((c - mean) ** 2 for c in costs) / len(costs)
        std = variance ** 0.5
        if std == 0:
            continue
        for e in entries:
            if abs(e["cost"] - mean) > 2 * std:
                anomalies.append({
                    "task_id": e["task_id"], "title": e["title"], "work_type": category,
                    "cost": e["cost"], "category_mean": mean,
                })
    anomalies.sort(key=lambda a: abs(a["cost"] - a["category_mean"]), reverse=True)
    return anomalies


def log_production(production_date, shift, location, material_type, quantity, unit, notes, recorded_by,
                   ore_grade_pct=None):
    fetch_production_records.clear()
    payload = {
        "production_date": production_date.isoformat(), "shift": shift, "location": location,
        "material_type": material_type, "quantity": quantity, "unit": unit,
        "notes": notes, "recorded_by": recorded_by, "ore_grade_pct": ore_grade_pct,
    }
    if not SUPABASE_AVAILABLE:
        return None
    try:
        res = supabase.table("shift_production").insert(payload).execute()
        if not res.data:
            log_error("shift_production insert affected 0 rows — likely RLS blocking writes",
                     endpoint="log_production")
            return None
        log_audit(recorded_by, "production_logged",
                  {"date": payload["production_date"], "shift": shift, "quantity": quantity})
        return res.data[0]
    except Exception as e:
        log_error(str(e), details=payload, endpoint="log_production")
        return None


@st.cache_data(ttl=120, show_spinner=False)
def fetch_production_records(start_date=None, end_date=None, limit=200):
    if not SUPABASE_AVAILABLE:
        return []
    try:
        q = supabase.table("shift_production").select("*")
        if start_date:
            q = q.gte("production_date", start_date.isoformat())
        if end_date:
            q = q.lte("production_date", end_date.isoformat())
        res = q.order("production_date", desc=True).limit(limit).execute()
        return res.data or []
    except Exception as e:
        log_error(str(e), endpoint="fetch_production_records")
        return []


def delete_production_record(record_id, deleted_by):
    fetch_production_records.clear()
    if not SUPABASE_AVAILABLE:
        return False
    try:
        res = supabase.table("shift_production").delete().eq("id", record_id).execute()
        if not res.data:
            return False
        log_audit(deleted_by, "production_record_deleted", {"record_id": record_id})
        return True
    except Exception as e:
        log_error(str(e), endpoint="delete_production_record")
        return False


def production_totals_by_date(records):
    """Groups records by date, summing quantity WITHIN each
    (date, material_type, unit) combination separately — deliberately
    not just summing everything into one number per day, since
    'tonnes of ore' and 'tonnes of waste rock' are not interchangeable
    quantities, and silently adding them together would produce a
    number that means nothing real. Returns a dict keyed by date,
    each value itself a dict keyed by (material_type, unit)."""
    totals = {}
    for r in records:
        date_key = r.get("production_date")
        mat_key = (r.get("material_type"), r.get("unit"))
        if date_key not in totals:
            totals[date_key] = {}
        totals[date_key][mat_key] = totals[date_key].get(mat_key, 0) + (r.get("quantity") or 0)
    return totals


