def create_purchase_order(supplier_id, line_items, created_by):
    """line_items: list of {part_id, quantity, unit_price}. Both the
    PO header and every line item's insert result are checked — a
    line item silently failing to insert would mean a PO shows a
    total cost that doesn't match what was actually ordered."""
    get_purchase_orders.clear()
    get_po_line_items.clear()
    if not SUPABASE_AVAILABLE or not line_items:
        return None
    try:
        po_number = f"PO-{datetime.now().strftime('%Y%m%d')}-{secrets.token_hex(4).upper()}"
        total = sum(i["quantity"] * i["unit_price"] for i in line_items)
        po_res = supabase.table("purchase_orders").insert({
            "po_number": po_number, "supplier_id": supplier_id,
            "total_cost": total, "created_by": created_by, "status": "Sent",
        }).execute()
        if not po_res.data:
            log_error("purchase_orders insert affected 0 rows — likely RLS blocking writes",
                     endpoint="create_purchase_order")
            return None
        po = po_res.data[0]
        for item in line_items:
            li_res = supabase.table("po_line_items").insert({
                "po_id": po["id"], "part_id": item["part_id"],
                "quantity_ordered": item["quantity"], "unit_price": item["unit_price"],
            }).execute()
            if not li_res.data:
                log_error("po_line_items insert affected 0 rows — PO total will not match "
                         "its actual line items", details={"po_id": po["id"], "item": item},
                         endpoint="create_purchase_order")
        log_audit(created_by, "purchase_order_created", {"po_id": po["id"], "po_number": po_number})
        return po
    except Exception as e:
        log_error(str(e), endpoint="create_purchase_order")
        return None


def receive_purchase_order(po_id, received_items, received_by):
    """received_items: list of {part_id, quantity_received}. Stock is
    only adjusted for items that successfully update in
    po_line_items first — matching the same check-before-trusting
    pattern as link_part_to_task above, so a PO can't show as
    'Received' while some lines silently failed to update."""
    if not SUPABASE_AVAILABLE:
        return False
    try:
        all_ok = True
        for item in received_items:
            upd = supabase.table("po_line_items").update({
                "quantity_received": item["quantity_received"]
            }).eq("po_id", po_id).eq("part_id", item["part_id"]).execute()
            if not upd.data:
                log_error("po_line_items update affected 0 rows", details={"po_id": po_id, "item": item},
                         endpoint="receive_purchase_order")
                all_ok = False
                continue
            if not adjust_part_quantity(item["part_id"], item["quantity_received"], received_by,
                                        reason=f"received against PO #{po_id}"):
                all_ok = False
        po_res = supabase.table("purchase_orders").update({
            "status": "Received", "received_at": datetime.now().isoformat()
        }).eq("id", po_id).execute()
        if not po_res.data:
            return False
        log_audit(received_by, "purchase_order_received", {"po_id": po_id, "fully_ok": all_ok})
        return all_ok
    except Exception as e:
        log_error(str(e), endpoint="receive_purchase_order")
        return False

# -------------------------------
# 20B2. SAP ERP SYNC (S/4HANA / ECC OData, OAuth2 client credentials)
# -------------------------------
# Bidirectional: exports Purchase Orders to SAP, imports Material
# master and Vendor/Business Partner records from SAP. See Phase 48
# in schema_additions.sql for the supporting columns/table
# (sap_po_number, sap_material_number, sap_vendor_number,
# erp_sync_log).

def _get_sap_token():
    """OAuth2 client-credentials token, cached in session_state and
    refreshed 60s before expiry — a real network round trip, so
    re-fetching on every sync click would be wasteful."""
    if not SAP_CONFIGURED:
        return None
    cached = st.session_state.get("_sap_token")
    cached_exp = st.session_state.get("_sap_token_expires_at")
    if cached and cached_exp and datetime.now() < cached_exp:
        return cached
    try:
        resp = requests.post(
            SAP_OAUTH_TOKEN_URL,
            data={"grant_type": "client_credentials"},
            auth=(SAP_CLIENT_ID, SAP_CLIENT_SECRET),
            timeout=SAP_REQUEST_TIMEOUT,
        )
        resp.raise_for_status()
        payload = resp.json()
        token = payload.get("access_token")
        if not token:
            log_error("SAP OAuth response had no access_token", endpoint="sap_get_token")
            return None
        expires_in = int(payload.get("expires_in", 1800))
        st.session_state["_sap_token"] = token
        st.session_state["_sap_token_expires_at"] = datetime.now() + timedelta(
            seconds=max(expires_in - 60, 30))
        return token
    except Exception as e:
        log_error(str(e), endpoint="sap_get_token")
        return None


def _sap_request(method, path, **kwargs):
    """Returns (response_or_None, error_string_or_None) so callers
    can distinguish 'no connection' from 'SAP rejected the payload'
    without repeating try/except at every call site."""
    token = _get_sap_token()
    if not token:
        return None, ("Could not obtain SAP OAuth token — check SAP_CLIENT_ID/SECRET "
                      "and SAP_OAUTH_TOKEN_URL.")
    headers = kwargs.pop("headers", {})
    headers.setdefault("Authorization", f"Bearer {token}")
    headers.setdefault("Accept", "application/json")
    headers.setdefault("Content-Type", "application/json")
    url = f"{SAP_API_BASE_URL}/{path.lstrip('/')}"
    try:
        resp = requests.request(method, url, headers=headers, timeout=SAP_REQUEST_TIMEOUT, **kwargs)
        if resp.status_code >= 400:
            return resp, f"SAP returned HTTP {resp.status_code}: {resp.text[:500]}"
        return resp, None
    except Exception as e:
        return None, str(e)


def _log_erp_sync(sync_type, direction, status, detail=None, record_id=None,
                  sap_reference=None, triggered_by=None):
    if not SUPABASE_AVAILABLE:
        return
    try:
        supabase.table("erp_sync_log").insert({
            "sync_type": sync_type, "direction": direction, "record_id": record_id,
            "sap_reference": sap_reference, "status": status,
            "detail": (str(detail)[:1000] if detail else None),
            "triggered_by": triggered_by,
        }).execute()
    except Exception as e:
        log_error(str(e), endpoint="erp_sync_log_insert")


@st.cache_data(ttl=60, show_spinner=False)
def get_erp_sync_log(limit=50):
    if not SUPABASE_AVAILABLE:
        return []
    try:
        res = (supabase.table("erp_sync_log").select("*")
              .order("created_at", desc=True).limit(limit).execute())
        return res.data or []
    except Exception as e:
        log_error(str(e), endpoint="get_erp_sync_log")
        return []


def sap_export_purchase_order(po_id, triggered_by=None):
    """Exports one PO + line items to SAP as a PurchaseOrder OData
    entity with a nested deep-insert. Refuses to send if the
    supplier or any line item is missing its SAP number, rather than
    sending a blank/wrong reference. On success, stores SAP's PO
    number back onto the local row. Does not auto-retry — a failed
    export leaves sync_status='error' with the reason attached,
    visible in Owner Console → ERP Sync."""
    if not SAP_CONFIGURED:
        return False, "SAP is not configured (missing secrets)."
    if not SUPABASE_AVAILABLE:
        return False, "Database unavailable."
    try:
        po_res = supabase.table("purchase_orders").select(
            "*, suppliers(sap_vendor_number, company_name)").eq("id", po_id).execute()
        if not po_res.data:
            return False, "Purchase order not found."
        po = po_res.data[0]
        supplier = po.get("suppliers") or {}
        vendor_number = supplier.get("sap_vendor_number")
        if not vendor_number:
            msg = (f"Supplier '{esc(supplier.get('company_name', '?'))}' has no "
                  f"sap_vendor_number on file — run vendor import first, or set it "
                  f"manually on the supplier record.")
            _log_erp_sync("po_export", "export", "error", msg, record_id=po_id, triggered_by=triggered_by)
            return False, msg

        li_res = supabase.table("po_line_items").select(
            "*, inventory_parts(sap_material_number, part_name)").eq("po_id", po_id).execute()
        line_items = li_res.data or []
        missing_material = [li for li in line_items
                            if not (li.get("inventory_parts") or {}).get("sap_material_number")]
        if missing_material:
            names = ", ".join(esc((li.get("inventory_parts") or {}).get("part_name", "?"))
                              for li in missing_material)
            msg = f"Line item(s) missing sap_material_number: {names}. Run material import first."
            _log_erp_sync("po_export", "export", "error", msg, record_id=po_id, triggered_by=triggered_by)
            return False, msg

        payload = {
            "Supplier": vendor_number,
            "PurchaseOrderType": "NB",
            "to_PurchaseOrderItem": {"results": [
                {
                    "PurchaseOrderItem": str(idx + 1).zfill(5),
                    "Material": (li.get("inventory_parts") or {}).get("sap_material_number"),
                    "OrderQuantity": str(li.get("quantity_ordered")),
                    "NetPriceAmount": str(li.get("unit_price")),
                    "PurchaseOrderItemText": (li.get("inventory_parts") or {}).get("part_name", ""),
                }
                for idx, li in enumerate(line_items)
            ]},
        }

        resp, err = _sap_request("POST", SAP_PO_SERVICE_PATH, data=json.dumps(payload))
        if err:
            supabase.table("purchase_orders").update({
                "sync_status": "error", "sync_error": err[:500],
            }).eq("id", po_id).execute()
            _log_erp_sync("po_export", "export", "error", err, record_id=po_id, triggered_by=triggered_by)
            return False, err

        body = resp.json().get("d", resp.json())
        sap_po_number = body.get("PurchaseOrder")
        supabase.table("purchase_orders").update({
            "sap_po_number": sap_po_number, "sync_status": "synced", "sync_error": None,
            "last_synced_at": datetime.now().isoformat(),
        }).eq("id", po_id).execute()
        get_purchase_orders.clear()
        log_audit(triggered_by or "system", "po_exported_to_sap",
                 {"po_id": po_id, "sap_po_number": sap_po_number})
        _log_erp_sync("po_export", "export", "success", f"SAP PO {sap_po_number}",
                      record_id=po_id, sap_reference=sap_po_number, triggered_by=triggered_by)
        return True, sap_po_number
    except Exception as e:
        log_error(str(e), endpoint="sap_export_purchase_order")
        _log_erp_sync("po_export", "export", "error", str(e), record_id=po_id, triggered_by=triggered_by)
        return False, str(e)


def sap_import_materials(triggered_by=None, top=200):
    """Upserts SAP material master into inventory_parts, matched on
    sap_material_number — re-running this is always safe (updates,
    never duplicates). Only touches SAP-sourced fields; anything the
    app added locally (reorder_point, bin_location, etc.) is left
    untouched."""
    if not SAP_CONFIGURED:
        return False, "SAP is not configured (missing secrets)."
    if not SUPABASE_AVAILABLE:
        return False, "Database unavailable."
    resp, err = _sap_request("GET", SAP_MATERIAL_SERVICE_PATH, params={"$top": top, "$format": "json"})
    if err:
        _log_erp_sync("material_import", "import", "error", err, triggered_by=triggered_by)
        return False, err
    try:
        body = resp.json().get("d", resp.json())
        records = body.get("results", body if isinstance(body, list) else [])
        imported, failed = 0, 0
        for rec in records:
            material_number = rec.get("Product")
            if not material_number:
                continue
            try:
                supabase.table("inventory_parts").upsert({
                    "sap_material_number": material_number,
                    "part_name": rec.get("ProductDescription") or material_number,
                    "part_number": material_number,
                    "unit_cost": float(rec.get("StandardPrice") or 0),
                    "last_synced_at": datetime.now().isoformat(),
                }, on_conflict="sap_material_number").execute()
                imported += 1
            except Exception as row_err:
                failed += 1
                log_error(str(row_err), endpoint="sap_import_materials_row",
                         details={"material_number": material_number})
        summary = f"{imported} imported/updated, {failed} failed"
        _log_erp_sync("material_import", "import", "success" if failed == 0 else "error",
                      summary, triggered_by=triggered_by)
        log_audit(triggered_by or "system", "sap_material_import", {"imported": imported, "failed": failed})
        fetch_all_parts.clear()
        return True, summary
    except Exception as e:
        log_error(str(e), endpoint="sap_import_materials")
        _log_erp_sync("material_import", "import", "error", str(e), triggered_by=triggered_by)
        return False, str(e)


def sap_import_vendors(triggered_by=None, top=200):
    """Same upsert-by-key pattern as sap_import_materials, keyed on
    sap_vendor_number. Run before exporting POs for a new supplier —
    export refuses to send a PO for a supplier with no
    sap_vendor_number rather than guessing or sending blank."""
    if not SAP_CONFIGURED:
        return False, "SAP is not configured (missing secrets)."
    if not SUPABASE_AVAILABLE:
        return False, "Database unavailable."
    resp, err = _sap_request("GET", SAP_VENDOR_SERVICE_PATH, params={"$top": top, "$format": "json"})
    if err:
        _log_erp_sync("vendor_import", "import", "error", err, triggered_by=triggered_by)
        return False, err
    try:
        body = resp.json().get("d", resp.json())
        records = body.get("results", body if isinstance(body, list) else [])
        imported, failed = 0, 0
        for rec in records:
            vendor_number = rec.get("Supplier")
            if not vendor_number:
                continue
            try:
                supabase.table("suppliers").upsert({
                    "sap_vendor_number": vendor_number,
                    "company_name": rec.get("SupplierName") or vendor_number,
                    "last_synced_at": datetime.now().isoformat(),
                }, on_conflict="sap_vendor_number").execute()
                imported += 1
            except Exception as row_err:
                failed += 1
                log_error(str(row_err), endpoint="sap_import_vendors_row",
                         details={"vendor_number": vendor_number})
        summary = f"{imported} imported/updated, {failed} failed"
        _log_erp_sync("vendor_import", "import", "success" if failed == 0 else "error",
                      summary, triggered_by=triggered_by)
        log_audit(triggered_by or "system", "sap_vendor_import", {"imported": imported, "failed": failed})
        return True, summary
    except Exception as e:
        log_error(str(e), endpoint="sap_import_vendors")
        _log_erp_sync("vendor_import", "import", "error", str(e), triggered_by=triggered_by)
        return False, str(e)


def render_erp_sync_tab(current_username):
    """Owner Console → ERP Sync tab. Permission gating happens once,
    at the top of page_owner_console() (is_owner check) — this
    function does not re-check it."""
    st.markdown("### SAP ERP Sync")
    if not SAP_CONFIGURED:
        st.warning("SAP is not configured. Add `SAP_OAUTH_TOKEN_URL`, `SAP_CLIENT_ID`, "
                  "`SAP_CLIENT_SECRET`, and `SAP_API_BASE_URL` to `.streamlit/secrets.toml`.")
        return
    st.success("SAP OAuth2 credentials are configured.")
    col1, col2, col3 = st.columns(3)
    with col1:
        if st.button("🔄 Import Vendors", use_container_width=True):
            with st.spinner("Importing vendors from SAP..."):
                ok, msg = sap_import_vendors(triggered_by=current_username)
            (st.success if ok else st.error)(msg)
            get_erp_sync_log.clear()
    with col2:
        if st.button("🔄 Import Materials", use_container_width=True):
            with st.spinner("Importing materials from SAP..."):
                ok, msg = sap_import_materials(triggered_by=current_username)
            (st.success if ok else st.error)(msg)
            get_erp_sync_log.clear()
    with col3:
        st.caption("Export a PO to SAP from its detail page (Purchase Orders → select "
                  "PO → **Export to SAP**), once its supplier and parts have SAP "
                  "numbers from the imports above.")
    st.markdown("#### Recent sync activity")
    log_rows = get_erp_sync_log(limit=50)
    if not log_rows:
        st.caption("No sync activity yet.")
    else:
        for row in log_rows:
            icon = "✅" if row.get("status") == "success" else "❌"
            ts = row.get("created_at", "")[:19].replace("T", " ")
            st.write(f"{icon} `{ts}` — **{esc(row.get('sync_type'))}** "
                    f"({esc(row.get('direction'))}) — {esc(row.get('detail') or '')}")

