REPORT_DEPARTMENTS = ["Production", "Haulage", "Assets / Maintenance", "Electrical",
                      "Inventory", "Contractors", "Other"]


def generate_worker_report_draft(username, full_name, report_date):
    """Auto-pulls a draft report from real task data — completed tasks
    (completed ON report_date specifically) and currently incomplete
    tasks assigned to this worker (regardless of date, since
    "incomplete" is about current state, not a specific day), plus
    items used and locations derived from those same tasks. The
    worker reviews and adds notes on top rather than retyping
    anything the app already knows.

    Matches on BOTH username and full_name against a task's
    assigned_to, since tasks in this app store the assignee's display
    name, not their username — checking username alone would silently
    miss every task this worker actually has.
    """
    all_tasks = st.session_state.get("tasks", [])
    my_tasks = [t2 for t2 in all_tasks if t2.get("assigned_to") in (username, full_name)]

    completed = []
    incomplete = []
    for t2 in my_tasks:
        entry = {"task_id": t2["id"], "title": t2.get("title", ""), "location": t2.get("location", "")}
        if t2.get("status") == "Complete":
            completed_at = _parse_dt(t2.get("completed_at"))
            if completed_at and completed_at.date() == report_date:
                completed.append(entry)
        else:
            incomplete.append(entry)

    parts_lookup = {p["id"]: p for p in st.session_state.get("parts", [])}
    items_used = {}
    for entry in completed:
        for tp in fetch_task_parts(entry["task_id"]):
            part = parts_lookup.get(tp.get("part_id"))
            if part:
                name = part.get("part_name", f"Part #{tp.get('part_id')}")
                items_used[name] = items_used.get(name, 0) + float(tp.get("quantity_used", 0) or 0)
    items_used_list = [{"part_name": k, "quantity": v} for k, v in items_used.items()]

    locations = sorted(set(e["location"] for e in (completed + incomplete) if e.get("location")))

    return {
        "completed_tasks": completed,
        "incomplete_tasks": incomplete,
        "items_used": items_used_list,
        "locations": ", ".join(locations),
    }


