def build_comprehensive_report(department, report_date):
    """Merges every worker's individual report for a department/date
    into one combined view — the actual point of "comprehensive": one
    document showing everyone's completed/incomplete work, items
    used, and locations for that department that day, not just a
    list of separate reports someone has to read one at a time.
    """
    reports = fetch_worker_reports(department=department, report_date=report_date)
    total_completed = sum(len(r["completed_tasks"]) for r in reports)
    total_incomplete = sum(len(r["incomplete_tasks"]) for r in reports)
    combined_items = {}
    for r in reports:
        for item in r["items_used"]:
            combined_items[item["part_name"]] = combined_items.get(item["part_name"], 0) + item["quantity"]
    all_locations = sorted(set(
        loc.strip() for r in reports for loc in (r.get("locations") or "").split(",") if loc.strip()
    ))
    return {
        "worker_count": len(reports),
        "total_completed": total_completed,
        "total_incomplete": total_incomplete,
        "combined_items_used": [{"part_name": k, "quantity": v} for k, v in
                               sorted(combined_items.items(), key=lambda x: -x[1])],
        "all_locations": all_locations,
        "reports": reports,
    }

