# 20U. PER-USER AI ASSISTANT CHAT HISTORY
# -------------------------------
def fetch_ai_chat_history(username, limit=50):
    """Returns this user's own chat history, oldest first — never
    another user's. Scoped by username at the application layer
    (this app has no Supabase Auth / server-side identity to enforce
    it at the database layer, same model as every other table here).

    Deliberately NOT cached — same reasoning as fetch_messages and
    fetch_notifications: a chat history that doesn't show the message
    someone just sent, on the very next rerun, reads as broken. This
    is also scoped per-username with a LIMIT, so the read is already
    cheap; there isn't much caching upside to trade that immediacy
    away for."""
    if not SUPABASE_AVAILABLE:
        all_msgs = st.session_state.get("ai_chat_memory", [])
        return [m for m in all_msgs if m["username"] == username][-limit:]
    try:
        res = (supabase.table("ai_chat_messages").select("*")
              .eq("username", username).order("created_at", desc=True).limit(limit).execute())
        return list(reversed(res.data or []))
    except Exception as e:
        log_error(str(e), endpoint="fetch_ai_chat_history")
        return []


def save_ai_chat_message(username, role, content, prompt_variant=None):
    """Returns the saved message dict (including its id) on success,
    or None on failure. The id matters now — retry and thumbs up/down
    both need to reference a SPECIFIC message afterward, not just know
    that "a" message was saved somewhere.

    prompt_variant records which answer-style the reinforcement-
    learning bandit chose for this message (see select_prompt_variant)
    — only meaningful for role="assistant"; callers saving the user's
    own question just omit it."""
    if not SUPABASE_AVAILABLE:
        all_msgs = st.session_state.get("ai_chat_memory", [])
        new_id = max([m.get("id", 0) for m in all_msgs], default=0) + 1
        new_msg = {"id": new_id, "username": username, "role": role, "content": content,
                  "feedback": None, "prompt_variant": prompt_variant, "created_at": datetime.now().isoformat()}
        all_msgs.append(new_msg)
        st.session_state.ai_chat_memory = all_msgs
        return new_msg
    try:
        payload = {"username": username, "role": role, "content": content}
        if prompt_variant:
            payload["prompt_variant"] = prompt_variant
        res = supabase.table("ai_chat_messages").insert(payload).execute()
        return res.data[0] if res.data else None
    except Exception as e:
        log_error(str(e), endpoint="save_ai_chat_message")
        return None


def set_ai_message_feedback(message_id, username, feedback):
    """Records a thumbs up/down on a specific message. Scoped by
    username in the same query as the id — a person can only ever
    set feedback on their OWN messages, never someone else's, even if
    they somehow guessed another user's message id."""
    if feedback not in ("up", "down", None):
        return False
    if not SUPABASE_AVAILABLE:
        all_msgs = st.session_state.get("ai_chat_memory", [])
        for m in all_msgs:
            if m.get("id") == message_id and m["username"] == username:
                m["feedback"] = feedback
                return True
        return False
    try:
        res = (supabase.table("ai_chat_messages").update({"feedback": feedback})
              .eq("id", message_id).eq("username", username).execute())
        return bool(res.data)
    except Exception as e:
        log_error(str(e), endpoint="set_ai_message_feedback")
        return False


def delete_last_ai_exchange(username):
    """Deletes this user's single most recent user+assistant message
    pair — what "Retry" uses to remove the old answer before a fresh
    one is generated and saved in its place. Scoped by username, same
    as every other AI chat function, so this can only ever remove the
    calling user's own most recent exchange."""
    if not SUPABASE_AVAILABLE:
        all_msgs = st.session_state.get("ai_chat_memory", [])
        mine = [m for m in all_msgs if m["username"] == username]
        if len(mine) < 2:
            return False
        # The last two entries for this user are the pair to remove —
        # relies on save_ai_chat_message always appending user then
        # assistant together, which is the established pattern.
        to_remove_ids = {mine[-1]["id"], mine[-2]["id"]}
        st.session_state.ai_chat_memory = [m for m in all_msgs if m.get("id") not in to_remove_ids]
        return True
    try:
        res = (supabase.table("ai_chat_messages").select("id")
              .eq("username", username).order("created_at", desc=True).limit(2).execute())
        if not res.data or len(res.data) < 2:
            return False
        ids = [row["id"] for row in res.data]
        supabase.table("ai_chat_messages").delete().in_("id", ids).execute()
        return True
    except Exception as e:
        log_error(str(e), endpoint="delete_last_ai_exchange")
        return False


def clear_ai_chat_history(username):
    """Deletes only this user's own messages — the query is scoped
    by username, so this can never touch another user's history."""
    if not SUPABASE_AVAILABLE:
        all_msgs = st.session_state.get("ai_chat_memory", [])
        st.session_state.ai_chat_memory = [m for m in all_msgs if m["username"] != username]
        return True
    try:
        supabase.table("ai_chat_messages").delete().eq("username", username).execute()
        return True
    except Exception as e:
        log_error(str(e), endpoint="clear_ai_chat_history")
        return False

