def get_user_language():
    """Session-cached, falls back to English for anything unexpected —
    an unrecognized or missing language code should never break the
    app, just silently show English."""
    lang = st.session_state.get("user_language", "en")
    return lang if lang in SUPPORTED_LANGUAGES else "en"


def t(key):
    """Translation lookup with a safe fallback chain: current language
    -> English -> the key itself. The last step matters — it means a
    key that was never translated at all still shows SOMETHING
    readable-ish rather than crashing or showing blank text."""
    lang = get_user_language()
    return TRANSLATIONS.get(lang, {}).get(key) or TRANSLATIONS["en"].get(key) or key


# =====================================================================
# AUTO-TRANSLATION — the scalable alternative to hand-maintaining a
# key in 8 language dicts for every one of the ~735 UI strings in this
# app. auto_t("Some English text") returns that text translated into
# the current language, with no dictionary entry required anywhere.
#
# Three cache tiers, cheapest first:
#   1. TRANSLATIONS  — the hand-written dicts above. Checked FIRST on
#      purpose: a human-reviewed translation always beats a machine
#      one, so the existing curated strings (and any corrections a
#      native speaker makes later) are never overridden by AI output.
#   2. Session memory — same string, same run, zero cost.
#   3. Database       — translated once per deployment, ever. Shared
#      across all users, survives restarts.
# Only a genuine miss on all three reaches the AI.
#
# Fails SAFE: any failure (no AI configured, API down, DB error)
# returns the original English rather than blank text or an error. A
# translation problem must never be the thing that stops a supervisor
# reading a permit warning.
# =====================================================================
# Deliberately NOT a plain module-level dict (`_AUTO_T_MEMORY = {}`)
# — that was this exact line's original form, and it was a real bug:
# Streamlit re-executes the ENTIRE script file on every single
# interaction (button click, form submit, any widget change), so a
# module-level assignment resets to empty every time. The "session
# memory" tier below was silently non-functional across interactions
# as a result — it only ever helped within a single script execution
# (e.g. the same string appearing twice on one page), never across
# the string being looked up again on the next interaction, which
# defeated the entire point of having this tier before the database.
# st.session_state is what actually survives reruns; this now uses it.

# Built once from the curated dicts: English text -> key, so a string
# that already HAS a human translation is found by its text, not just
# by its key. This is what lets auto_t() prefer human work over AI
# without every call site needing to know which strings are curated.
_CURATED_BY_TEXT = {v: k for k, v in TRANSLATIONS["en"].items()}


def auto_t(text):
    """Translates an English UI string into the user's language.

    Unlike t(), this takes the ENGLISH TEXT ITSELF, not a key — which
    is the whole point: wrapping a string costs one function call, not
    a new entry in eight dictionaries.
    """
    lang = get_user_language()
    if lang == "en" or not text or not text.strip():
        return text

    # Tier 1 — a human-written translation always wins over AI.
    curated_key = _CURATED_BY_TEXT.get(text)
    if curated_key:
        human = TRANSLATIONS.get(lang, {}).get(curated_key)
        if human:
            return human

    _auto_t_memory = st.session_state.setdefault("_auto_t_memory", {})
    cache_key = (lang, text)
    if cache_key in _auto_t_memory:
        return _auto_t_memory[cache_key]

    source_hash = hashlib.sha256(text.encode("utf-8")).hexdigest()[:32]

    # Tier 2 — the shared database cache.
    if SUPABASE_AVAILABLE:
        try:
            res = (supabase.table("translation_cache").select("translated_text")
                  .eq("source_hash", source_hash).eq("lang_code", lang).limit(1).execute())
            if res.data:
                result = res.data[0]["translated_text"]
                _auto_t_memory[cache_key] = result
                return result
        except Exception as e:
            log_error(str(e), endpoint="auto_t_cache_read")

    # Tier 3 — actually translate. Only reached once per string per
    # language for the entire deployment's lifetime.
    if not AI_FEATURES_AVAILABLE:
        return text
    try:
        lang_name = SUPPORTED_LANGUAGES.get(lang, lang)
        prompt = (
            f"Translate the following UI text from an industrial mine maintenance app "
            f"into {lang_name}. Rules:\n"
            f"- Return ONLY the translation, no explanation, no quotes around it.\n"
            f"- Preserve any emoji, markdown (**bold**), and {{placeholders}} EXACTLY as-is.\n"
            f"- Keep safety acronyms (LOTO, JSA, HV, PPE, DGA) in English, since those are "
            f"what appear on physical equipment tags and permit books.\n"
            f"- Keep it concise — this is a button/label/message in a UI, not prose.\n\n"
            f"Text: {text}"
        )
        # Shorter timeout than the 15s default — translating a UI
        # label is a nice-to-have, not something worth making a page
        # load wait as long as a real, requested Assistant answer.
        # With up to 5 providers in the fall-through chain, this
        # bounds the worst case much more tightly than the default
        # would if an earlier provider were slow rather than failing
        # outright — a real, confirmed contributor to reports of the
        # app feeling slow specifically on first-ever page visits in
        # a non-English language, before a string's translation is
        # cached.
        translated = generate_smart_text(prompt, max_tokens=300, timeout=6)
        if not translated or not translated.strip():
            return text
        translated = translated.strip()

        # Placeholder integrity check — an AI that drops or renames a
        # {placeholder} would cause a KeyError crash at .format() time
        # downstream. If they don't match exactly, discard the
        # translation and keep English: a page in the wrong language
        # is a minor annoyance, a crashed page is not.
        if set(re.findall(r"\{(\w+)\}", text)) != set(re.findall(r"\{(\w+)\}", translated)):
            log_error(f"Placeholder mismatch, discarded: {text[:60]}", endpoint="auto_t_placeholder")
            return text

        _auto_t_memory[cache_key] = translated
        if SUPABASE_AVAILABLE:
            try:
                supabase.table("translation_cache").insert({
                    "source_hash": source_hash, "lang_code": lang,
                    "source_text": text, "translated_text": translated,
                }).execute()
            except Exception as e:
                # A failed cache WRITE is not a failed translation —
                # the text is already correct in memory for this
                # session. Logged, not surfaced.
                log_error(str(e), endpoint="auto_t_cache_write")
        return translated
    except Exception as e:
        log_error(str(e), endpoint="auto_t")
        return text


def set_user_language(lang_code, username):
    """Persists the choice to the database (so it survives future
    logins, not just this session) and updates the session immediately
    either way — the UI should feel instant even if the database write
    is slow or fails."""
    st.session_state["user_language"] = lang_code
    if SUPABASE_AVAILABLE:
        try:
            supabase.table("facility_users").update(
                {"preferred_language": lang_code}
            ).eq("username", username).execute()
        except Exception as e:
            log_error(str(e), endpoint="set_user_language")
            # Deliberately not surfaced as an error to the user — the
            # session-level change above already took effect, so their
            # immediate experience is correct even if persistence
            # across future logins silently didn't save this time.


# Registry of available "My Dashboard" widgets — a curated set of
# EXISTING analytics functions already built and proven elsewhere in
# this app, not a general-purpose widget framework. Each entry is
# (label, icon, render_function) — render_function takes the same
# (tasks, assets, incidents, parts_lookup) bundle every widget needs,
# even if a given widget only uses some of them, so the calling code
# doesn't need per-widget special-casing for which arguments to pass.
def _dash_widget_mtbf(tasks, assets, incidents, parts_lookup):
    mtbf, mtbf_n = compute_mtbf_hours(tasks)
    st.metric("MTBF (hours)", f"{mtbf:.1f}" if mtbf is not None else "No data", f"{mtbf_n} interval(s)")

def _dash_widget_cost_by_category(tasks, assets, incidents, parts_lookup):
    cats = cost_by_category(tasks, parts_lookup)
    if not cats:
        st.info("No cost data yet.")
    else:
        for c in cats[:5]:
            st.write(f"**{c['category']}**: {c['total_cost']:,.2f}")

def _dash_widget_predictive_alerts(tasks, assets, incidents, parts_lookup):
    alerts = get_predictive_failure_alerts(tasks, assets)
    if not alerts:
        st.info("No assets currently approaching their typical failure window.")
    else:
        for a in alerts[:3]:
            st.warning(f"**{a['asset_name']}** — {a['pct_of_window']:.0%} of typical interval between failures")

def _dash_widget_open_tasks(tasks, assets, incidents, parts_lookup):
    open_t = [t2 for t2 in tasks if t2.get("status") != "Complete"]
    overdue = [t2 for t2 in open_t if t2.get("due_date") and (_parse_dt(t2["due_date"]) or datetime.max) < datetime.now()]
    c1, c2 = st.columns(2)
    c1.metric("Open Tasks", len(open_t))
    c2.metric("Overdue", len(overdue))

def _dash_widget_safety_snapshot(tasks, assets, incidents, parts_lookup):
    si = safety_leading_indicators(incidents, tasks)
    c1, c2 = st.columns(2)
    c1.metric("Incidents (30d)", si["last_30_days"])
    c2.metric("Proactive Reports", si["proactive_reports"])

def _dash_widget_cost_anomalies(tasks, assets, incidents, parts_lookup):
    anomalies = detect_cost_anomalies(tasks, parts_lookup)
    if not anomalies:
        st.info("No cost anomalies detected.")
    else:
        for a in anomalies[:3]:
            st.warning(f"**#{a['task_id']} {a['title']}** — {a['cost']:,.2f} (typical: {a['category_mean']:,.2f})")

def _dash_widget_parts_forecast(tasks, assets, incidents, parts_lookup):
    forecast = get_parts_reorder_forecast(list(parts_lookup.values()), horizon_days=30)
    if not forecast:
        st.info("No parts forecast to need reordering in the next 30 days.")
    else:
        for f in forecast[:5]:
            _p = f["part"]
            if f["already_due"]:
                st.warning(f"**{esc(_p['part_name'])}** — at/below reorder point now")
            else:
                st.write(f"**{esc(_p['part_name'])}** — reorder point in "
                        f"~{f['days_until_reorder_point']:.0f} day(s)")

def _dash_widget_electrical_subsections(tasks, assets, incidents, parts_lookup):
    workload = get_electrical_subsection_workload(tasks)
    for sub, counts in workload.items():
        st.write(f"**{sub}**: {counts['open']} open ({counts['overdue']} overdue), "
                f"{counts['completed_last_30d']} completed (30d)")

def _dash_widget_active_outages(tasks, assets, incidents, parts_lookup):
    outages = fetch_outage_events(active_only=True)
    if not outages:
        st.info("No active outages.")
    else:
        for e in outages:
            st.error(f"**{e.get('location') or 'Location not set'}** — Commander: {e['outage_commander']}")

def _dash_widget_transformer_status(tasks, assets, incidents, parts_lookup):
    dga_tests = fetch_dga_tests()
    transformer_tags = sorted(set(t["transformer_tag"] for t in dga_tests))
    if not transformer_tags:
        st.info("No transformers tracked yet.")
        return
    worst_transformer = None
    for tag in transformer_tags:
        latest = max((t for t in dga_tests if t["transformer_tag"] == tag), key=lambda t: t["test_date"])
        worst, worst_gases = worst_dga_condition(latest)
        if worst_transformer is None or worst > worst_transformer[1]:
            worst_transformer = (tag, worst, worst_gases)
    _sev = {0: "info", 1: "success", 2: "warning", 3: "warning", 4: "error"}[worst_transformer[1]]
    getattr(st, _sev)(f"Worst: **{worst_transformer[0]}** — Condition {worst_transformer[1] or 'N/A'}")

def _dash_widget_pending_switching(tasks, assets, incidents, parts_lookup):
    pending = fetch_switching_orders(status="Draft")
    if not pending:
        st.info("No switching orders awaiting authorization.")
    else:
        for o in pending[:3]:
            st.warning(f"**{o['title']}** — awaiting {o.get('designated_approver') or 'approval'}")

def _dash_widget_calibration_alerts(tasks, assets, incidents, parts_lookup):
    overdue, due_soon = [], []
    for c in fetch_instrument_calibrations():
        _, _, status = instrument_calibration_status(c)
        if status == "overdue":
            overdue.append(c)
        elif status == "due_soon":
            due_soon.append(c)
    if not overdue and not due_soon:
        st.info("No calibrations overdue or due soon.")
    else:
        if overdue:
            st.error(f"{len(overdue)} overdue")
        if due_soon:
            st.warning(f"{len(due_soon)} due within 7 days")

