def create_announcement(message, created_by):
    fetch_active_announcements.clear()
    fetch_all_announcements.clear()
    if not message or not message.strip():
        return False, "Message can't be empty."
    if not SUPABASE_AVAILABLE:
        rows = st.session_state.setdefault("announcements_memory", [])
        rows.append({"id": max([r.get("id", 0) for r in rows], default=0) + 1,
                    "message": message.strip(), "is_active": True})
        return True, ""
    try:
        res = supabase.table("app_announcements").insert({
            "message": message.strip(), "is_active": True, "created_by": created_by,
        }).execute()
        if not res.data:
            return False, ("Saved but nothing was created — Row Level Security is likely "
                          "blocking writes to app_announcements. Run schema_additions.sql Phase 11.")
        log_audit(created_by, "announcement_create", {"message": message.strip()[:80]})
        # Fans out synchronously, same tradeoff as the Electrical digest
        # email loop elsewhere in this app — fine at tens of users, but
        # this blocks the person creating the announcement until every
        # push/SMS call finishes. Worth moving to a background job if
        # the user count grows large enough for this to feel slow.
        _announce_recipients = [u for u in fetch_all_users_from_db()
                                if u.get("is_approved") and not u.get("is_suspended")]
        for _u in _announce_recipients:
            notify_user_everywhere(
                _u, "📢 New Announcement", message.strip(),
                sms_body=f"MWDTS Announcement: {message.strip()[:140]}",
                category="announcements")
        return True, ""
    except Exception as e:
        log_error(str(e), endpoint="create_announcement")
        return False, str(e)


