# -------------------------------
# 22. SESSION TIMEOUT CHECK
# -------------------------------
def check_timeout():
    if st.session_state.authenticated:
        if datetime.now() - st.session_state.last_activity > timedelta(minutes=SESSION_TIMEOUT_MINUTES):
            _timeout_token = st.query_params.get("session")
            if _timeout_token:
                invalidate_session_token(_timeout_token)
                del st.query_params["session"]
            st.session_state.authenticated = False
            st.session_state.user_payload = None
            st.warning("Session expired due to inactivity. Please log in again.")
            st.rerun()
        else:
            st.session_state.last_activity = datetime.now()

# -------------------------------
# 23. OAUTH LOGIN (Google) — via Streamlit's native st.login()
# -------------------------------
# Requires an [auth] block in secrets.toml (NOT the same as the
# GOOGLE_CLIENT_ID/GOOGLE_CLIENT_SECRET keys used elsewhere in this
# file — Streamlit's st.login() reads specifically from st.secrets
# under [auth], so the same client id/secret need to be duplicated
# there):
#
#   [auth]
#   redirect_uri = "https://<your-app>.streamlit.app/oauth2callback"
#   cookie_secret = "<a long random string — generate once, keep it stable>"
#   client_id = "<same value as GOOGLE_CLIENT_ID>"
#   client_secret = "<same value as GOOGLE_CLIENT_SECRET>"
#   server_metadata_url = "https://accounts.google.com/.well-known/openid-configuration"
#
# On Google Cloud Console, the OAuth client's "Authorized redirect
# URIs" must include that exact redirect_uri — Google rejects the
# callback otherwise. Also needs Authlib>=1.3.2 in requirements.txt.


def _generate_google_account_password():
    """Google-authenticated accounts still need a password_hash row
    (the schema/register_user_to_db requires one) even though they'll
    only ever actually sign in via Google — this is never shown to
    the person and never used to log in through the normal form."""
    import string
    alphabet = string.ascii_letters + string.digits + "!@#$%^&*"
    while True:
        candidate = "".join(secrets.choice(alphabet) for _ in range(24))
        if is_strong_password(candidate)[0]:
            return candidate


# -------------------------------
# 23b. WHATSAPP LOGIN (OTP via Twilio Verify)
# -------------------------------
# Needs in secrets.toml (separate top-level keys — Twilio has no
# reserved [section] the way Streamlit's own [auth] does):
#
#   TWILIO_ACCOUNT_SID = "AC..."
#   TWILIO_AUTH_TOKEN = "..."
#   TWILIO_VERIFY_SERVICE_SID = "VA..."
#
# Also needs `twilio` in requirements.txt, and — unlike Google, which
# reused the existing `email` column — a phone_number column that
# doesn't exist yet in facility_users:
#
#   ALTER TABLE facility_users ADD COLUMN phone_number text;
#
# Run that in the Supabase SQL editor once before this feature can
# actually match anyone to an account (registration/login both
# degrade gracefully without it, but no one will ever be found).
#
# Twilio's Sandbox lets you test immediately (send "join <keyword>" to
# the Sandbox number from your own WhatsApp first) — a real, approved
# WhatsApp sender is only needed later, for OTPs to reach numbers that
# haven't joined the sandbox.
try:
    from twilio.rest import Client as _TwilioClient
    TWILIO_AVAILABLE = True
except ImportError:
    TWILIO_AVAILABLE = False

TWILIO_ACCOUNT_SID = _secret_get("TWILIO_ACCOUNT_SID", "")
TWILIO_AUTH_TOKEN = _secret_get("TWILIO_AUTH_TOKEN", "")
TWILIO_VERIFY_SERVICE_SID = _secret_get("TWILIO_VERIFY_SERVICE_SID", "")
WHATSAPP_LOGIN_CONFIGURED = bool(
    TWILIO_AVAILABLE and TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN and TWILIO_VERIFY_SERVICE_SID)

# A separate Twilio phone number for plain SMS alerts (task assignments,
# announcements, password reset links) — NOT the Verify service above,
# which only ever sends one-time codes for login, never free-form text.
# Needs its own secret:
#   TWILIO_SMS_FROM_NUMBER = "+1XXXXXXXXXX"   (a Twilio number with SMS capability)
TWILIO_SMS_FROM_NUMBER = _secret_get("TWILIO_SMS_FROM_NUMBER", "")
SMS_CONFIGURED = bool(TWILIO_AVAILABLE and TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN and TWILIO_SMS_FROM_NUMBER)


def send_sms(phone_e164, message):
    """Best-effort plain SMS via Twilio's Messaging API. Returns
    (ok, error_message). Never raises — every call site treats SMS as
    one channel among several (push/in-app/email usually also fire),
    so a failure here should never block the rest of a notification
    fan-out."""
    if not SMS_CONFIGURED or not phone_e164:
        return False, "SMS not configured or no phone number on file."
    try:
        client = _TwilioClient(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)
        client.messages.create(to=phone_e164, from_=TWILIO_SMS_FROM_NUMBER, body=message)
        return True, None
    except Exception as e:
        log_error(str(e), details={"phone": phone_e164}, endpoint="send_sms")
        return False, str(e)


def notify_user_everywhere(user_record, title, body, sms_body=None, category=None):
    """Fans a notification out across every channel this app supports
    for a single user: in-app notification list + real device push
    (send_notification already does both), plus SMS if the user has a
    phone_number on file and SMS is configured. sms_body defaults to
    the same text as the push/in-app body, but callers can pass a
    shorter or differently-worded version — SMS is charged per
    message/segment, so keeping it terse matters in a way it doesn't
    for a push notification.

    category, if given, is checked against the recipient's
    notification_preferences to decide whether the DEVICE PUSH fires
    (see send_notification) — it never affects the in-app record or
    SMS, which stay as before.

    Deliberately does NOT include email here — the existing password
    reset and digest flows already call send_email_notification
    directly where relevant, and not every notification (e.g. a task
    assignment) should also be an email."""
    username = user_record.get("username")
    if username:
        send_notification(username, title, body, category=category)
    phone = user_record.get("phone_number")
    if phone:
        send_sms(phone, sms_body or f"{title}: {body}")


def _normalize_whatsapp_number(raw):
    """Twilio Verify wants E.164 format (+<countrycode><number>, no
    spaces/dashes). This is a light touch, not full validation — it
    just strips obviously-wrong characters and requires a leading +,
    since guessing a country code for someone would silently send
    their OTP to the wrong number."""
    cleaned = re.sub(r"[^\d+]", "", raw or "")
    if not cleaned.startswith("+"):
        return None
    return cleaned if len(cleaned) >= 8 else None


def send_whatsapp_otp(phone_e164):
    """Starts a Twilio Verify check over the WhatsApp channel. Returns
    (ok, error_message)."""
    if not WHATSAPP_LOGIN_CONFIGURED:
        return False, "WhatsApp login isn't configured on this deployment."
    try:
        client = _TwilioClient(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)
        client.verify.v2.services(TWILIO_VERIFY_SERVICE_SID).verifications.create(
            to=phone_e164, channel="whatsapp")
        return True, None
    except Exception as e:
        log_error(str(e), details={"phone": phone_e164}, endpoint="send_whatsapp_otp")
        return False, str(e)


def check_whatsapp_otp(phone_e164, code):
    """Confirms the code Twilio sent. Returns (ok, error_message)."""
    if not WHATSAPP_LOGIN_CONFIGURED:
        return False, "WhatsApp login isn't configured on this deployment."
    try:
        client = _TwilioClient(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN)
        result = client.verify.v2.services(TWILIO_VERIFY_SERVICE_SID).verification_checks.create(
            to=phone_e164, code=code)
        if result.status == "approved":
            return True, None
        return False, "That code didn't match. Check it and try again."
    except Exception as e:
        # Twilio raises (rather than returning a status) for an
        # expired/already-used code — surfaced the same way as a
        # simple mismatch, since the person's fix is identical either
        # way: request a fresh code.
        log_error(str(e), details={"phone": phone_e164}, endpoint="check_whatsapp_otp")
        return False, "That code is invalid or expired. Request a new one."


def whatsapp_login():
    """Renders the WhatsApp login block: phone entry -> send OTP ->
    code entry -> verify -> account-linking (same matched/pending/
    suspended/no-match logic as Google, see handle_google_oauth_return
    for the reasoning — a verified phone number proves identity, not
    MWDTS approval, so the same admin-gated path applies here too)."""
    if not WHATSAPP_LOGIN_CONFIGURED:
        return
    with st.expander("Login with WhatsApp", key="whatsapp_login_expander"):
        _stage = st.session_state.get("_wa_login_stage", "enter_phone")

        if _stage == "enter_phone":
            _wa_phone_raw = st.text_input(
                "WhatsApp number (with country code)", placeholder="+233241234567",
                key="wa_phone_input")
            if st.button("Send code", key="wa_send_code_btn"):
                _wa_phone = _normalize_whatsapp_number(_wa_phone_raw)
                if not _wa_phone:
                    st.error("Enter your number in international format, starting with + "
                            "and your country code (e.g. +233241234567).")
                else:
                    _ok, _err = send_whatsapp_otp(_wa_phone)
                    if _ok:
                        st.session_state["_wa_login_phone"] = _wa_phone
                        st.session_state["_wa_login_stage"] = "enter_code"
                        st.rerun()
                    else:
                        st.error(f"Couldn't send the code: {_err}")

        elif _stage == "enter_code":
            _wa_phone = st.session_state.get("_wa_login_phone", "")
            st.caption(f"Code sent to {esc(_wa_phone)} on WhatsApp.")
            _wa_code = st.text_input("Enter the 6-digit code", key="wa_code_input", max_chars=6)
            _wa_col1, _wa_col2 = st.columns(2)
            if _wa_col1.button("Verify", key="wa_verify_btn"):
                _ok, _err = check_whatsapp_otp(_wa_phone, _wa_code.strip())
                if not _ok:
                    st.error(_err)
                else:
                    users = fetch_all_users_from_db()
                    matched_user = next((u for u in users if u.get("phone_number") == _wa_phone), None)
                    if matched_user is None:
                        st.session_state["_wa_login_stage"] = "no_match"
                        st.rerun()
                    elif matched_user.get("is_suspended"):
                        st.error("🚫 This account is suspended. Contact the administrator.")
                    elif not matched_user.get("is_approved"):
                        st.info("⏳ Your access request is pending administrator approval.")
                    else:
                        clear_login_failures(matched_user.get("username"))
                        st.session_state.user_payload = {
                            "name": matched_user.get("full_name", matched_user.get("username")),
                            "role": matched_user.get("role", "Worker"),
                            "username": matched_user.get("username"),
                            "email": matched_user.get("email", None),
                            "avatar_url": matched_user.get("avatar_url", None),
                            "must_change_password": False,
                        }
                        st.session_state["user_language"] = matched_user.get("preferred_language") or "en"
                        st.session_state["_show_welcome"] = not matched_user.get("has_seen_welcome", False)
                        st.session_state.authenticated = True
                        st.session_state.last_activity = datetime.now()
                        log_audit(matched_user.get("full_name"), "login_whatsapp")
                        _new_session_token = create_session_token(matched_user.get("username"))
                        if _new_session_token:
                            st.query_params["session"] = _new_session_token
                        update_user_profile(matched_user.get("username"), {"last_login": datetime.now().isoformat()})
                        for _k in ("_wa_login_stage", "_wa_login_phone"):
                            st.session_state.pop(_k, None)
                        st.rerun()
            if _wa_col2.button("Use a different number", key="wa_restart_btn"):
                for _k in ("_wa_login_stage", "_wa_login_phone"):
                    st.session_state.pop(_k, None)
                st.rerun()


def email_login():
    """Renders the 'Login with Email' block: enter an email -> a
    6-digit code is sent -> enter the code -> either logged straight
    in (an approved account matched) or sent to the Create Account
    Profile form below with that email pre-filled (no completable
    account matched) — one flow covering both login and signup, as
    requested, without ever revealing on screen which of those two
    outcomes is about to happen (see request_email_login_code() for
    why: that's what keeps this form from being usable to enumerate
    which email addresses have real accounts).

    Silently does nothing if SMTP isn't configured (send_email_
    notification fails safe already) — same fail-safe posture as the
    Forgot Password flow just above this, not a hard requirement for
    the rest of the login page to work.
    """
    with st.expander("Login with Email", key="email_login_expander"):
        _stage = st.session_state.get("_em_login_stage", "enter_email")

        if _stage == "enter_email":
            _em_addr = st.text_input("Email address", placeholder="you@company.com", key="em_addr_input")
            if st.button("Send code", key="em_send_code_btn"):
                if not _em_addr or "@" not in _em_addr:
                    st.error("Enter a valid email address.")
                else:
                    _em_key = f"emailcode:{_em_addr.strip().lower()}"
                    _locked, _secs = is_login_locked(_em_key)
                    if _locked:
                        st.error(f"Too many code requests for this address. "
                                f"Try again in about {max(1, _secs // 60)} minute(s).")
                    else:
                        record_login_failure(_em_key)
                        request_email_login_code(_em_addr)
                        st.session_state["_em_login_email"] = _em_addr.strip().lower()
                        st.session_state["_em_login_stage"] = "enter_code"
                        st.rerun()

        elif _stage == "enter_code":
            _em_addr = st.session_state.get("_em_login_email", "")
            # SECURITY: identical wording regardless of what actually
            # happened server-side — same principle as the Forgot
            # Password message above, extended here rather than
            # showing a different caption for "account found" vs not.
            st.caption(f"If {esc(_em_addr)} is registered or eligible, a code was sent to it.")
            _em_code = st.text_input("Enter the 6-digit code", key="em_code_input", max_chars=6)
            _em_col1, _em_col2 = st.columns(2)
            if _em_col1.button("Verify", key="em_verify_btn"):
                _ok, _purpose, _matched_user = verify_email_login_code(_em_addr, _em_code.strip())
                if not _ok:
                    st.error("That code is invalid or has expired. Request a new one.")
                elif _purpose == "login" and _matched_user:
                    complete_login(_matched_user)
                    for _k in ("_em_login_stage", "_em_login_email"):
                        st.session_state.pop(_k, None)
                    st.rerun()
                else:
                    # purpose == "signup" -- email verified, but no
                    # completable account exists yet. Hands off to the
                    # existing Create Account Profile form below with
                    # the now-proven email pre-filled, rather than
                    # inventing a second, separate account-creation path.
                    st.session_state["_verified_signup_email"] = _em_addr
                    for _k in ("_em_login_stage", "_em_login_email"):
                        st.session_state.pop(_k, None)
                    st.success("✅ Email verified. Scroll down to **Create Account Profile** "
                              "to finish requesting access — your email is already filled in.")
            if _em_col2.button("Use a different email", key="em_restart_btn"):
                for _k in ("_em_login_stage", "_em_login_email"):
                    st.session_state.pop(_k, None)
                st.rerun()

        elif _stage == "no_match":
            _wa_phone = st.session_state.get("_wa_login_phone", "")
            st.info(f"No MWDTS account found for **{esc(_wa_phone)}**.")
            with st.form("wa_signup_form"):
                st.caption("First time signing in with this number — this creates an "
                          "access request. An administrator still reviews and sets your "
                          "actual role.")
                _wa_username = st.text_input("Choose Username").strip().lower()
                _wa_name = st.text_input("Full Name *")
                _wa_role = st.selectbox("Requested Access Level", ["Worker", "Supervisor", "Superintendent"])
                _wa_submit = st.form_submit_button("📨 Request Access", use_container_width=True)
            if _wa_submit:
                if not _wa_username or not _wa_name:
                    st.error("Username and full name are required.")
                elif any(u["username"].lower() == _wa_username for u in fetch_all_users_from_db()):
                    st.error("That username is taken. Please choose another.")
                else:
                    _ok, _err = register_user_to_db(
                        _wa_username, _wa_name, _wa_role,
                        _generate_google_account_password(),  # same rationale as Google:
                        phone_number=_wa_phone)                # never used to log in via
                                                                # the normal form, only exists
                                                                # because the schema requires
                                                                # a password_hash row
                    if _ok:
                        st.success("✅ Access request submitted. You'll be able to sign in "
                                   "with WhatsApp once an administrator approves it.")
                        for _k in ("_wa_login_stage", "_wa_login_phone"):
                            st.session_state.pop(_k, None)
                    else:
                        st.error(_err or "Registration failed.")
            if st.button("Use a different number", key="wa_restart_from_nomatch_btn"):
                for _k in ("_wa_login_stage", "_wa_login_phone"):
                    st.session_state.pop(_k, None)
                st.rerun()


def google_oauth_login():
    """Renders the 'Login with Google' link. Following it triggers
    ?auto_google_login=1, which the Python-side check near the top of
    the auth gate picks up and turns into a real st.login() call —
    that's what actually redirects to Google and, on return,
    handle_google_oauth_return() reconciles that identity with this
    app's own account system.

    One real complication: when this app is opened through the
    wrapper site (the GitHub Pages install page used for push
    notifications), it's running inside an iframe there — and Google
    deliberately refuses to render its own sign-in page inside ANY
    iframe, as an anti-clickjacking policy on Google's side, not
    something this app's code controls. A plain click that stays
    inside that iframe would redirect the IFRAME to Google, which
    Google then blocks/errors on.

    This used to be handled with a small JS redirect inside an
    st.iframe() — st.button() plus a <script> setting window.top.
    location.href. That never actually worked: Streamlit's own iframe
    sandboxing does not include allow-top-navigation in its default
    policy (confirmed directly against streamlit/streamlit#6922 on
    GitHub, a still-open issue about exactly this), so the browser
    silently blocks ANY attempt from inside an st.iframe() to
    navigate the top-level window, by any technique — not a bug in
    the JS itself, a platform-level restriction on the sandboxed
    frame it was running in. That's exactly why the "Opening Google
    sign-in…" message appeared (the Python side rendered it
    unconditionally) while nothing further ever happened.

    Fixed by rendering a REAL <a> link directly in the page's own
    markup instead of going through an st.iframe() — that part still
    holds (st.iframe() JS can't navigate the top-level window at all,
    a Streamlit sandboxing restriction, not a bug in the JS itself).

    target="_top" was tried next, on the theory that it would both
    break out of the wrapper site's iframe AND be a harmless no-op on
    direct access. That second half was wrong in practice: confirmed
    directly (a real device test, not a guess) that ANY link carrying
    a non-default target attribute — even on a page with no framing to
    break out of — gets intercepted by Streamlit's own frontend and
    opened in a literal new browser tab, not navigated in place. That
    appears to be deliberate on Streamlit's part (protecting its own
    live session/websocket state from a same-tab navigation), not a
    bug, but it made target="_top" actively worse than no target at
    all for the common case (direct access, no wrapper).

    Currently NO target attribute is set — correct, same-tab
    navigation for direct access (the case that actually matters day
    to day). The tradeoff: this reintroduces the original wrapper-site
    problem — Google refuses to render inside ANY iframe regardless of
    target handling, so signing in through the embedded wrapper is
    broken again until that case gets its own separate fix (most
    likely: a distinct, wrapper-specific link/button that isn't
    subject to whatever Streamlit's frontend does with target
    attributes, or breaking out via the wrapper's OWN page instead of
    from inside this Streamlit-rendered link).

    The href itself is deliberately an ABSOLUTE URL (built from
    APP_URL), not a relative "?auto_google_login=1" — that relative
    form was tested directly (via a forced "open in new tab"
    navigation, bypassing any click-handling questions entirely) and
    confirmed to never actually deliver the query parameter through
    at all: the Python-side check for it never even fired. A relative
    href's resolution depends on the current document's own base URL,
    which is exactly the kind of thing that can go wrong when a page
    might be reached through more than one context. An absolute URL
    removes that ambiguity outright.
    """
    if APP_URL:
        _google_href = esc(f"{APP_URL.rstrip('/')}/?auto_google_login=1")
    else:
        # No APP_URL configured — fall back to the relative form.
        # Worth setting APP_URL in secrets.toml if this button doesn't
        # work; see this function's own docstring above.
        _google_href = esc("?auto_google_login=1")
    st.markdown(f"""
    <div class="google-login-link-wrap">
        <a href="{_google_href}" class="google-login-link">
            Login with Google
        </a>
    </div>
    """, unsafe_allow_html=True)


def handle_google_oauth_return():
    """Runs on every rerun, before the login screen — reconciles a
    Google-authenticated identity (st.user, populated by Streamlit
    itself after a successful st.login() round-trip) with this app's
    OWN account system (facility_users), which is a separate concept
    from OIDC identity. A Google login proves WHO someone is; it does
    not by itself say whether they're an approved MWDTS user or what
    role they hold — that authority stays entirely with this app's
    existing admin-approval flow, not with Google.

    The return value (True if it rendered something / handled this
    run) is informational only now — the caller does NOT st.stop() on
    it. Earlier it did, which meant anyone whose browser still carried
    a Google identity cookie from a past visit (that cookie outlives
    st.session_state — it isn't cleared just by closing the tab) would
    have the ENTIRE rest of the login screen silently fail to render
    on every future visit: no username/password form, no Forgot
    Password, no WhatsApp login. Not calling st.stop() means that
    banner/form renders, but the rest of the screen stays reachable
    right below it either way.
    """
    if not (AUTH_AVAILABLE and hasattr(st, "user")):
        return False
    # getattr(..., False), not st.user.is_logged_in directly: when
    # Streamlit can't successfully load an [auth] block from secrets
    # (missing, malformed, or just not deployed yet), st.user has NO
    # attributes at all — not even is_logged_in itself — so a direct
    # access raises AttributeError instead of the False you'd expect
    # for "not logged in". getattr's default absorbs exactly that case.
    if not getattr(st.user, "is_logged_in", False) or st.session_state.get("authenticated"):
        return False

    google_email = st.user.get("email")
    if not google_email:
        st.error("Google didn't return an email address for this account — cannot continue.")
        if st.button("Try a different account"):
            st.logout()
        return True

    users = fetch_all_users_from_db()
    matched_user = next((u for u in users if u.get("email") == google_email), None)

    if matched_user is None:
        # No existing MWDTS account for this Google email — auto-file
        # an access request exactly like the normal signup form does,
        # rather than either silently granting access or dead-ending
        # the person with no path forward at all.
        st.info(f"No MWDTS account found for **{esc(google_email)}**.")
        with st.form("google_signup_form"):
            st.caption("First time signing in with Google — this creates an access request, "
                      "same as the normal sign-up form. An administrator still reviews and "
                      "sets your actual role.")
            _g_username = st.text_input(
                "Choose Username",
                value=re.sub(r"[^a-z0-9_]", "", google_email.split("@")[0].lower()),
            ).strip().lower()
            _g_name = st.text_input("Full Name *", value=st.user.get("name", ""))
            _g_role = st.selectbox("Requested Access Level", ["Worker", "Supervisor", "Superintendent"])
            _g_submit = st.form_submit_button("📨 Request Access", use_container_width=True)
        if _g_submit:
            if not _g_username or not _g_name:
                st.error("Username and full name are required.")
            elif any(u["username"].lower() == _g_username for u in users):
                st.error("That username is taken. Please choose another.")
            else:
                _ok, _err = register_user_to_db(
                    _g_username, _g_name, _g_role,
                    _generate_google_account_password(), email=google_email)
                if _ok:
                    st.success("✅ Access request submitted. You'll be able to sign in "
                               "with Google once an administrator approves it.")
                else:
                    st.error(_err or "Registration failed.")
        if st.button("Use a different Google account"):
            st.logout()
        return True

    if matched_user.get("is_suspended"):
        st.error("🚫 **This account is suspended.** Contact the administrator "
                 "if you believe this is a mistake.")
        if st.button("Use a different Google account", key="google_switch_suspended"):
            st.logout()
        return True

    if not matched_user.get("is_approved"):
        st.info("⏳ **Your access request is pending.** The administrator has "
                "not yet reviewed it. You'll be able to sign in once approved.")
        if st.button("Use a different Google account", key="google_switch_pending"):
            st.logout()
        return True

    # Approved, non-suspended match — sign in. Mirrors the normal
    # username/password login success path exactly (same session_state
    # shape) so the rest of the app can't tell the difference between
    # the two login methods afterward.
    clear_login_failures(matched_user.get("username"))
    st.session_state.user_payload = {
        "name": matched_user.get("full_name", matched_user.get("username")),
        "role": matched_user.get("role", "Worker"),
        "username": matched_user.get("username"),
        "email": matched_user.get("email", None),
        "avatar_url": matched_user.get("avatar_url", None),
        "must_change_password": False,  # Google-authenticated accounts never touch the
                                         # app's own password, so there's nothing to force
                                         # a change on here even if the flag is set in the
                                         # DB from before this account switched to Google.
    }
    st.session_state["user_language"] = matched_user.get("preferred_language") or "en"
    st.session_state["_show_welcome"] = not matched_user.get("has_seen_welcome", False)
    st.session_state.authenticated = True
    st.session_state.last_activity = datetime.now()
    log_audit(matched_user.get("full_name"), "login_google")
    _new_session_token = create_session_token(matched_user.get("username"))
    if _new_session_token:
        st.query_params["session"] = _new_session_token
    update_user_profile(matched_user.get("username"), {"last_login": datetime.now().isoformat()})
    st.rerun()

# -------------------------------
# 24. AUTHENTICATION GATEWAY
# -------------------------------
# Restores login from a session token in the URL, if present — this
# is what lets a hard refresh (which genuinely resets session_state,
# a Streamlit platform limitation, not a bug in this app) skip
# straight back to where the person was instead of dropping them to
# the login screen. Guarded to run once per fresh session so it
# doesn't re-hit the database on every single rerun afterward.
# Completes the Google login button's iframe-breakout dance (see
# google_oauth_login() above): once the browser has reloaded — either
# at the top level (broken out of the wrapper site's iframe) or in
# place (direct access, no breakout needed) — with ?auto_google_login=1
# in the URL, this is what actually calls st.login() and triggers the
# real redirect to Google. Checked before session-token restoration so
# it fires as early as possible in a fresh page load.
if not st.session_state.authenticated and st.query_params.get("auto_google_login"):
    del st.query_params["auto_google_login"]
    try:
        st.login()
    except Exception as _google_login_err:
        log_error(str(_google_login_err), endpoint="auto_google_login")
        st.error("Couldn't reach Google sign-in. Please try again, or use username/password below.")
        st.stop()

if not st.session_state.authenticated and not st.session_state.get("_session_token_checked"):
    st.session_state["_session_token_checked"] = True
    _restore_token = st.query_params.get("session")
    if _restore_token:
        _restored_username = validate_session_token(_restore_token)
        if _restored_username:
            try:
                _restored_users = fetch_all_users_from_db()
                _restored_user = next((u for u in _restored_users if u.get("username") == _restored_username), None)
            except Exception as e:
                log_error(str(e), endpoint="session_token_restore")
                _restored_user = None
            if _restored_user and _restored_user.get("is_approved") and not _restored_user.get("is_suspended", False):
                # Mirrors the exact fields the normal login success path
                # sets, so a token-restored session is indistinguishable
                # from a freshly-logged-in one to the rest of the app.
                st.session_state.user_payload = {
                    "name": _restored_user.get("full_name", _restored_user.get("username")),
                    "role": _restored_user.get("role", "Worker"),
                    "username": _restored_user.get("username"),
                    "email": _restored_user.get("email", None),
                    "avatar_url": _restored_user.get("avatar_url", None),
                    "must_change_password": _restored_user.get("must_change_password", False),
                }
                st.session_state["user_language"] = _restored_user.get("preferred_language") or "en"
                st.session_state["_show_welcome"] = False  # already seen it in the original session
                st.session_state.authenticated = True
                st.session_state.last_activity = datetime.now()
            else:
                # A token that no longer maps to a valid, approved,
                # non-suspended account — clear it from the URL rather
                # than leave a dead token sitting there indefinitely.
                del st.query_params["session"]
        else:
            del st.query_params["session"]

if "_pre_login_welcome_dismissed" not in st.session_state:
    st.session_state["_pre_login_welcome_dismissed"] = False

if not st.session_state.authenticated and not st.session_state["_pre_login_welcome_dismissed"]:
    # Wrapped defensively — this is the very first thing every user
    # sees, so it must never be able to crash or loop. Any exception
    # anywhere in its render (a bad fetch, a malformed value, anything
    # unforeseen) now skips straight to the login form — the simpler,
    # already-proven-stable path — rather than risk repeating the
    # crash-and-Cloud-auto-restart cycle that caused the earlier
    # continuous-reload issue.
    try:
        render_logo_bar()
        st.markdown('''
        <div class="landing-hero">
            <i class="fas fa-hard-hat landing-icon"></i>
            <h1>Mine & Workshop Digital Tracker</h1>
            <p>Replacing paper task boards, incident report books, and permit logs with one
            system — tasks, permits, incidents, and shift handovers, all in one place,
            accessible from your phone.</p>
        </div>
        ''', unsafe_allow_html=True)

        render_subheading("What's inside", level=4)
        _landing_features = [
            ("fa-clipboard-list", "Task & Maintenance Tracking",
            "Dispatch work tickets, track repairs, and keep a full maintenance history per asset."),
            ("fa-shield-heart", "Safety & Incident Reporting",
            "Log hazards and near-misses from the field, with permit-to-work and JSA tracking built in."),
            ("fa-chart-line", "Production & Analytics",
            "Real reliability metrics, cost tracking, and an executive dashboard leadership can trust."),
            ("fa-language", "Built for the Whole Crew",
            "Available in English, French, Spanish, Portuguese, Chinese, and Hindi."),
        ]
        _lcol1, _lcol2 = st.columns(2)
        for _i, (_icon, _title, _desc) in enumerate(_landing_features):
            with (_lcol1 if _i % 2 == 0 else _lcol2):
                st.markdown(f'''
                <div class="landing-feature-card">
                    <i class="fas {_icon} landing-feature-icon"></i>
                    <h4>{esc(_title)}</h4>
                    <p>{esc(_desc)}</p>
                </div>
                ''', unsafe_allow_html=True)

        st.markdown("<br>", unsafe_allow_html=True)
        render_subheading("Get Started", level=4)
        st.caption("Choose your role to continue to login — same login form either way, this "
                  "just points you in the right direction.")
        _role_cards = [
            {"icon": "fa-helmet-safety", "title": "Worker", "desc": "Field tasks & incident reporting", "tone": "info"},
            {"icon": "fa-user-gear", "title": "Supervisor", "desc": "Crew, tasks & shift handovers", "tone": "ok"},
            {"icon": "fa-shield-halved", "title": "Superintendent", "desc": "Site oversight & analytics", "tone": "warn"},
        ]
        _rcol1, _rcol2, _rcol3 = st.columns(3)
        for _rcol, _rcard in zip([_rcol1, _rcol2, _rcol3], _role_cards):
            with _rcol:
                st.markdown(render_action_cards([_rcard]), unsafe_allow_html=True)
                if st.button(f"Continue as {_rcard['title']}", key=f"_role_landing_{_rcard['title']}",
                            use_container_width=True):
                    st.session_state["_pre_login_welcome_dismissed"] = True
                    st.rerun()

        # Deliberately NOT given the same card treatment as the three
        # above — this isn't a security boundary (the real check happens
        # at login, same as every other role), just not something to
        # visually advertise alongside the three main roles.
        st.markdown('<div style="text-align:center; margin-top:0.8rem;">', unsafe_allow_html=True)
        if st.button("Admin", key="_admin_landing_link", type="tertiary"):
            st.session_state["_pre_login_welcome_dismissed"] = True
            st.rerun()
        st.markdown('</div>', unsafe_allow_html=True)
    except Exception as e:
        log_error(str(e), endpoint="landing_page_render")
        st.session_state["_pre_login_welcome_dismissed"] = True
        st.rerun()

elif not st.session_state.authenticated:
    # ---------- AUTOMATION TRIGGER ENDPOINT ----------
    # Same reasoning as the ?health=1 endpoint near the top of this
    # file, placed here instead because it needs functions
    # (run_weather_email_check, send_email_notification, etc.) that
    # aren't defined yet at that early point in the script. Still
    # short-circuits before any login UI renders below.
    #
    # This is the real way to get actual 12-hourly (routine) / 6-hourly
    # (bad-weather) email delivery: Streamlit itself has no background
    # scheduler, so point an external scheduled job (a GitHub Action
    # cron, or a Supabase Edge Function) at
    # https://<your-app-url>/?weather_check=1&token=<AUTOMATION_TRIGGER_TOKEN>
    # on any reasonable interval (hourly is fine) — this endpoint's own
    # cooldown tracking decides whether an email is actually due each
    # time it's hit, so the external job doesn't need to track the
    # 12-hour cadence itself.
    #
    # Token-gated (unlike ?health=1) because this can send real email
    # to the whole leadership list — an unauthenticated, ungated
    # trigger for that would be a spam vector.
    if st.query_params.get("weather_check") is not None:
        _wc_token = st.query_params.get("token")
        _wc_expected = _secret_get("AUTOMATION_TRIGGER_TOKEN")
        if not _wc_expected:
            st.json({"error": "AUTOMATION_TRIGGER_TOKEN not configured in secrets."})
        elif _wc_token != _wc_expected:
            st.json({"error": "Invalid or missing token."})
        else:
            _wc_result = run_weather_email_check(triggered_by="automation_trigger")
            st.json(_wc_result)
        st.stop()

    render_logo_bar()
    render_poster_slideshow()
    render_ticker_bar()
    st.markdown('''
    <div class="main-header">
        <i class="fas fa-hard-hat"></i> Mine & Workshop Digital Tracker
        <small>Smart Maintenance Management System</small>
    </div>
    ''', unsafe_allow_html=True)
    st.markdown('<div class="main-header-spacer"></div>', unsafe_allow_html=True)
    st.markdown('<div class="sub-header"><i class="fas fa-shield-alt"></i> Secure Login Gateway</div>', unsafe_allow_html=True)

    # Checked before the rest of this screen: if this rerun is the
    # browser landing back from a Google login redirect, this
    # completes the sign-in (that path calls st.rerun() itself, which
    # naturally halts everything below — nothing further to do here).
    #
    # It does NOT st.stop() for its other outcomes (no matching
    # account yet, pending approval, suspended) — Streamlit's Google
    # identity cookie is separate from and outlives st.session_state,
    # so ANYONE who tested Google login on a given browser even once
    # and simply closed the tab (rather than clicking this app's own
    # Logout, which explicitly clears it) stays "Google-logged-in" on
    # that browser indefinitely. Every later visit would hit one of
    # these non-success branches — and an earlier version of this
    # code called st.stop() right here regardless of which branch,
    # which meant the username/password form, Forgot Password, and
    # WhatsApp login all silently stopped rendering on that browser,
    # with no error and no indication why. Letting the screen continue
    # below means those stay reachable even while the Google banner
    # (with its own "use a different account" escape hatch) shows above.
    if handle_google_oauth_return():
        st.markdown("---")

    # --- Owner not configured -------------------------------------------
    if SUPABASE_AVAILABLE and not owner_is_configured():
        st.error(
            "⚠️ **No owner configured.** Add `OWNER_USERNAME = \"your-username\"` to "
            "`.streamlit/secrets.toml` and restart. Until then the Owner Console is "
            "unreachable and nobody can approve access requests."
        )

    # --- Demo mode notice -------------------------------------------------
    if not SUPABASE_AVAILABLE:
        st.info(
            "**Demo mode — no database connected.** Nothing you enter will be saved. "
            "Sign in with `superintendent1` / `boss000`, `supervisor1` / `super789`, "
            "or `worker1` / `worker123`. These accounts exist ONLY in demo mode and "
            "disappear automatically once Supabase is connected."
        )

    # --- First-run administrator bootstrap --------------------------------
    # Without this, connecting a fresh database would leave nobody able to
    # log in: the demo accounts are gone, and self-registration requires an
    # existing Superintendent to approve it.
    elif not has_any_admin():
        st.warning("**First-run setup.** The database has no administrator yet. "
                   "Create one now — this form disappears permanently once an "
                   "administrator exists.")
        with st.form("bootstrap_admin", clear_on_submit=True):
            render_subheading("Create the first Superintendent account", level=4)
            _bs_user = st.text_input("Username", placeholder="e.g. amoses").strip().lower()
            _bs_name = st.text_input("Full Name", placeholder="Your full name")
            _bs_email = st.text_input("Email (optional)")
            _bs_p1 = st.text_input("Password", type="password")
            _bs_p2 = st.text_input("Confirm Password", type="password")
            _bs_go = st.form_submit_button("🚀 Create Administrator", use_container_width=True)
            if _bs_go:
                if not (_bs_user and _bs_name and _bs_p1):
                    st.error("Username, full name, and password are required.")
                elif _bs_p1 != _bs_p2:
                    st.error("Passwords do not match.")
                else:
                    _ok, _err = create_first_admin(_bs_user, _bs_name, _bs_p1, _bs_email or None)
                    if _ok:
                        st.success("Administrator created. You can now log in below.")
                        st.rerun()
                    else:
                        st.error(_err)
        st.markdown("---")

    # Check for reset token
    reset_token = st.query_params.get("reset_token")
    if reset_token:
        users = fetch_all_users_from_db()
        found = False
        for u in users:
            if u.get("password_reset_token") == reset_token:
                # Same timezone-safe parser as everywhere else in this
                # file — a raw datetime.fromisoformat() here crashed the
                # UNAUTHENTICATED login page (no surrounding try/except)
                # for anyone whose reset_token_expiry came back with a
                # UTC offset. A broken password-reset link is worse than
                # most instances of this bug since there's no other path
                # back into the app for that user.
                expiry = _parse_dt(u.get("reset_token_expiry")) or datetime.now()
                if expiry > datetime.now():
                    with st.form("reset_password_form", clear_on_submit=True):
                        st.markdown("### Reset Your Password")
                        new_pass = st.text_input("New Password", type="password")
                        if st.form_submit_button("Reset Password"):
                            strong, msg = is_strong_password(new_pass)
                            if strong:
                                hashed = hash_password(new_pass)
                                if update_user_profile(u["username"], {
                                    "password_hash": hashed,
                                    "password_reset_token": None,
                                    "reset_token_expiry": None
                                }):
                                    st.success("Password updated! Please log in.")
                                    st.query_params.clear()
                                    st.rerun()
                                else:
                                    st.error("Failed to update password.")
                            else:
                                st.error(msg)
                else:
                    st.error("Reset link expired.")
                found = True
                break
        if not found:
            st.error("Invalid reset token.")

    # Normal login form — hidden once a password has been verified and
    # we're waiting on a 2FA code instead, so the person isn't shown
    # both forms confusingly at once.
    if not st.session_state.get("_pending_2fa_username"):
        with st.form("login_form", clear_on_submit=True):
            user_in = st.text_input("Username", placeholder="Enter your username").strip().lower()
            pass_in = st.text_input("Password", type="password", placeholder="Enter your password")
            login_submitted = st.form_submit_button('Authenticate Profile', use_container_width=True, key="password_login_submit_btn")

        if login_submitted:
            locked, seconds_left = is_login_locked(user_in)
            if locked:
                mins = max(1, seconds_left // 60)
                st.error(f"🔒 Too many failed attempts. This account is locked for about {mins} more minute(s).")
            else:
                matched_user, status = authenticate_user(user_in, pass_in)
                if matched_user:
                    if matched_user.get("totp_enabled"):
                        # Password is correct, but login isn't complete
                        # yet — complete_login() only runs after the
                        # TOTP form below succeeds. Storing just the
                        # username (not the full record) keeps re-auth
                        # honest: the 2FA check below re-fetches fresh
                        # user data rather than trusting what's in
                        # session state from before the code was typed.
                        st.session_state["_pending_2fa_username"] = matched_user["username"]
                        st.rerun()
                    else:
                        complete_login(matched_user)
                        st.rerun()
                elif status == "pending_approval":
                    st.info("⏳ **Your access request is pending.** The administrator has "
                            "not yet reviewed it. You'll be able to sign in once approved.")
                elif status == "suspended":
                    st.error("🚫 **This account is suspended.** Contact the administrator "
                             "if you believe this is a mistake.")
                elif status == "denied":
                    st.error("🚫 **Your access request was declined.** Contact the "
                             "administrator for details.")
                else:
                    record_login_failure(user_in)
                    attempts = _login_state().get(str(user_in).lower(), {}).get("count", 0)
                    remaining = max(0, LOGIN_MAX_ATTEMPTS - attempts)
                    if remaining > 0:
                        st.error(f"Invalid credentials. {remaining} attempt(s) remaining before lockout.")
                    else:
                        st.error(f"🔒 Too many failed attempts. Account locked for {LOGIN_LOCKOUT_MINUTES} minutes.")
    else:
        # ---------- 2FA CHALLENGE ----------
        st.markdown("### 🔐 Two-Factor Authentication")
        _2fa_username = st.session_state["_pending_2fa_username"]
        st.caption(f"Enter the 6-digit code from your authenticator app for **{esc(_2fa_username)}**, "
                  "or one of your backup codes.")
        with st.form("totp_challenge_form", clear_on_submit=True):
            _totp_code_in = st.text_input("Code", max_chars=20, placeholder="123456")
            _totp_submitted = st.form_submit_button("Verify", use_container_width=True)
        if st.button("← Back to login"):
            del st.session_state["_pending_2fa_username"]
            st.rerun()
        if _totp_submitted:
            locked, seconds_left = is_login_locked(f"2fa:{_2fa_username}")
            if locked:
                mins = max(1, seconds_left // 60)
                st.error(f"🔒 Too many failed 2FA attempts. Try again in about {mins} minute(s).")
            else:
                _fresh_user = next((u for u in fetch_all_users_from_db()
                                    if u["username"] == _2fa_username), None)
                if not _fresh_user or not _fresh_user.get("totp_enabled"):
                    st.error("2FA state changed — please log in again.")
                    del st.session_state["_pending_2fa_username"]
                elif verify_totp_code(_fresh_user.get("totp_secret", ""), _totp_code_in) or \
                        consume_backup_code(_2fa_username, _totp_code_in):
                    del st.session_state["_pending_2fa_username"]
                    complete_login(_fresh_user)
                    st.rerun()
                else:
                    record_login_failure(f"2fa:{_2fa_username}")
                    st.error("Invalid code. Check your authenticator app's time is in sync, "
                            "or use a backup code.")

    # Forgot password link
    with st.expander("Forgot Password?"):
        with st.form("reset_form", clear_on_submit=True):
            reset_email = st.text_input("Enter your registered email", placeholder="email@example.com")
            if st.form_submit_button("Send Reset Link"):
                if not reset_email or "@" not in reset_email:
                    st.error("Enter a valid email address.")
                else:
                    _locked, _secs = is_login_locked(f"reset:{reset_email.lower()}")
                    if _locked:
                        st.error(f"Too many reset requests for this address. "
                                 f"Try again in about {max(1, _secs // 60)} minute(s).")
                    else:
                        record_login_failure(f"reset:{reset_email.lower()}")
                        users = fetch_all_users_from_db()
                        _matched = next((u for u in users if u.get("email") == reset_email), None)
                        if _matched:
                            generate_reset_token(_matched["username"], reset_email)
                        # SECURITY: identical response whether or not the email exists.
                        # Previously this branched to "Email not found" for unregistered
                        # addresses, which let anyone enumerate the worker roster by
                        # trying emails one at a time. If SMTP itself isn't configured,
                        # that's an operator problem visible in the Owner Console health
                        # check, not something to reveal to whoever is at this form.
                        st.success("If that email is registered, a reset link has been sent.")

    if AUTH_AVAILABLE and GOOGLE_CLIENT_ID:
        google_oauth_login()

    email_login()

    whatsapp_login()

    st.markdown("---")
    st.markdown('<div class="sub-header"><i class="fas fa-user-plus"></i> Create Account Profile</div>', unsafe_allow_html=True)

    with st.form("register_form", clear_on_submit=True):
        st.caption("Submitting this creates an **access request**. An administrator "
                   "reviews it and decides your role — selecting a role below is a "
                   "request, not a grant.")
        _rc1, _rc2 = st.columns(2)
        with _rc1:
            reg_user = st.text_input("Choose Username", placeholder="Pick a unique username").strip().lower()
            reg_name = st.text_input("Full Name *", placeholder="Your full name")
            reg_email = st.text_input("Work Email", placeholder="email@company.com",
                                      value=st.session_state.pop("_verified_signup_email", ""))
            reg_pass = st.text_input("Set Password *", type="password",
                                     placeholder="8+ chars, upper, lower, digit, symbol")
        with _rc2:
            reg_empid = st.text_input("Employee / Contractor ID",
                                      placeholder="Helps the admin verify you")
            reg_title = st.text_input("Job Title", placeholder="e.g. Fitter, Electrician")
            reg_dept = st.text_input("Department / Crew", placeholder="e.g. Fixed Plant")
            reg_role = st.selectbox("Requested Access Level",
                                    ["Worker", "Supervisor", "Superintendent"])
        register_submitted = st.form_submit_button('📨 Request Access', use_container_width=True)

    if register_submitted:
        if not SUPABASE_AVAILABLE:
            st.error("Cannot register in demo mode — no database is connected.")
        elif reg_user and reg_name and reg_pass:
            users = fetch_all_users_from_db()
            if any(u["username"].lower() == reg_user for u in users):
                st.error("That username is taken. Please choose another.")
            else:
                ok, err = register_user_to_db(
                    reg_user, reg_name, reg_role, reg_pass, reg_email or None,
                    job_title=reg_title or None, department=reg_dept or None,
                    employee_id=reg_empid or None)
                if ok:
                    st.success("✅ Access request submitted. You'll be able to sign in "
                               "once an administrator approves it.")
                else:
                    st.error(err or "Registration failed.")
        else:
            st.error("Username, full name, and password are required.")
    st.stop()
else:
    check_timeout()

    # --- Forced password change gate ------------------------------------
    # Blocks EVERYTHING else in the app until satisfied. This is the
    # enforcement side of admin_reset_password(): a temp password alone
    # is not enough, since the person who set it (the admin) would
    # otherwise still know the account's live password afterward.
    if st.session_state.user_payload.get("must_change_password"):
        render_logo_bar()
        render_poster_slideshow()
        render_ticker_bar()
        st.markdown('''
        <div class="main-header">
            <i class="fas fa-key"></i> Password Change Required
        </div>
        ''', unsafe_allow_html=True)
        st.markdown('<div class="main-header-spacer"></div>', unsafe_allow_html=True)
        st.warning("An administrator reset your password. Choose a new one to continue — "
                  "you won't be able to use the app until this is done.")
        with st.form("forced_password_change", clear_on_submit=True):
            _fp1 = st.text_input("New Password", type="password")
            _fp2 = st.text_input("Confirm New Password", type="password")
            _fp_go = st.form_submit_button("Set New Password", use_container_width=True)
            if _fp_go:
                if _fp1 != _fp2:
                    st.error("Passwords do not match.")
                else:
                    _strong, _msg = is_strong_password(_fp1)
                    if not _strong:
                        st.error(_msg)
                    elif update_user_profile(st.session_state.user_payload.get("username"), {
                        "password_hash": hash_password(_fp1),
                        "must_change_password": False,
                    }):
                        st.session_state.user_payload["must_change_password"] = False
                        log_audit(st.session_state.user_payload.get("name", "unknown"),
                                 "forced_password_change_completed", {})
                        st.success("Password updated.")
                        st.rerun()
                    else:
                        st.error("Failed to update password. Try again.")
        st.stop()

# -------------------------------
# 25. PWA MANIFEST & SERVICE WORKER
# -------------------------------
# Rewritten — the previous version linked to /static/manifest.json and
# /static/sw.js, but neither file existed anywhere in the project and
# even if they had, that isn't the correct URL path for how Streamlit
# actually serves static files. It never worked.
#
# The manifest and icons below are embedded directly as data: URIs —
# this makes "Add to Home Screen" installability work on a fresh
# deploy with ZERO configuration, regardless of Streamlit version or
# whether static file serving is set up. The one thing that genuinely
# needs real static file hosting is the service worker (browsers
# refuse to register a service worker from a data: URI — that's a
# security restriction, not a Streamlit limitation), so that part is
# wrapped to fail silently if it's not available. See
# PWA_SETUP.md for how to enable it.
_PWA_MANIFEST_B64 = ""
_PWA_ICON192_B64 = ""
_PWA_APPLE_ICON_B64 = ""

# CRITICAL FIX: this block used to be st.markdown(..., unsafe_allow_html=True)
# with an embedded <script> tag — which NEVER actually runs. Browsers
# never execute a <script> tag that was inserted via innerHTML (which
# is how Streamlit's markdown renderer inserts this HTML) — this is a
# fundamental, spec-defined browser behavior, not a Streamlit quirk.
# That means the service worker registration below was silently never
# happening at all, on any page load, for anyone, ever — which is
# exactly the failure mode this file's own push-notification
# diagnostics describes ("the single most common reason subscribing
# hangs forever: the browser can't find a service worker to
# register"). st.iframe() actually executes its script (this is the
# same mechanism the subscribe/unsubscribe flow further down already
# uses successfully) — switched to that here, with every reference
# explicitly qualified as window.top.* so it manipulates the REAL
# page's <head> and registers the service worker against the REAL
# page's origin, not the iframe's own throwaway document.
#
# IMPORTANT further correction: st.iframe()'s sandbox is confirmed
# (see the Google-login docstring above, citing streamlit/streamlit
# #6922) to block window.top NAVIGATION by any technique — that
# restriction doesn't apply to plain DOM mutation (manifest/meta tag
# injection above), but service worker registration triggered
# directly from inside the sandboxed iframe is close enough to that
# same restricted territory that it's not worth trusting blind. The
# robust fix: don't run the registration call FROM INSIDE the iframe
# at all — use the iframe only to inject a REAL <script> element into
# the top page's own DOM via createElement+appendChild (which
# genuinely executes — unlike the old innerHTML-based st.markdown
# approach this replaced, which never executed at all). Once that
# injected script is running, it's native top-level page code, not
# iframe code, so none of the iframe sandboxing applies to it.
_pwa_inner_js = (
    "(function() {"
    "  document.querySelectorAll('link[rel=\"manifest\"]').forEach(function(el) { el.remove(); });"
    "  var manifestLink = document.createElement('link');"
    "  manifestLink.rel = 'manifest';"
    "  manifestLink.href = 'data:application/manifest+json;base64," + _PWA_MANIFEST_B64 + "';"
    "  document.head.appendChild(manifestLink);"
    "  var iconLink = document.createElement('link');"
    "  iconLink.rel = 'icon';"
    "  iconLink.type = 'image/png';"
    "  iconLink.href = 'data:image/png;base64," + _PWA_ICON192_B64 + "';"
    "  document.head.appendChild(iconLink);"
    "  var appleIconLink = document.createElement('link');"
    "  appleIconLink.rel = 'apple-touch-icon';"
    "  appleIconLink.href = 'data:image/png;base64," + _PWA_APPLE_ICON_B64 + "';"
    "  document.head.appendChild(appleIconLink);"
    "  var metaTags = ["
    "    ['theme-color', '#16213e'],"
    "    ['apple-mobile-web-app-capable', 'yes'],"
    "    ['apple-mobile-web-app-status-bar-style', 'black-translucent'],"
    "    ['apple-mobile-web-app-title', 'MWDTS']"
    "  ];"
    "  metaTags.forEach(function(pair) {"
    "    var m = document.createElement('meta');"
    "    m.name = pair[0];"
    "    m.content = pair[1];"
    "    document.head.appendChild(m);"
    "  });"
    "})();"
    "if ('serviceWorker' in navigator) {"
    "  navigator.serviceWorker.register('./app/static/sw.js').catch(function() {});"
    "}"
)
_pwa_bootstrap_js = (
    "<script>"
    "(function() {"
    "  var s = window.top.document.createElement('script');"
    "  s.textContent = " + json.dumps(_pwa_inner_js) + ";"
    "  window.top.document.head.appendChild(s);"
    "})();"
    "</script>"
)
st.iframe(_pwa_bootstrap_js, height=1)

# -------------------------------
# 26. HANDLE RECURRING TASKS
# -------------------------------
handle_recurring_tasks()

# -------------------------------
# 27. MAIN APP
# -------------------------------
# Defensive: authenticated=True should always mean user_payload is a
# complete dict (login sets both together, see the login success
# block above) — but a stale browser tab left open from before a
# code deploy, or any other edge case that leaves these two out of
# sync, would otherwise crash here with an unhandled KeyError the
# moment the app tries to read a field that isn't there. Reset to a
# clean logged-out state instead, so the person sees a normal
# "please log in again" experience rather than a hard error page.
if not st.session_state.user_payload or "name" not in st.session_state.user_payload:
    _broken_session_token = st.query_params.get("session")
    if _broken_session_token:
        invalidate_session_token(_broken_session_token)
        del st.query_params["session"]
    st.session_state.authenticated = False
    st.session_state.user_payload = None
    st.warning("Your session couldn't be verified — please log in again.")
    st.rerun()

user = st.session_state.user_payload
full_name = user['name']
username = user['username']
role = user['role'].strip().lower()
user_email = user.get('email', None)
avatar_url = user.get('avatar_url', None)

# Completes the push-subscription round trip started in page_profile()'s
# "Enable Push Notifications" button: after the JS there subscribes (or
# unsubscribes) and reloads with the result in the URL, this is what
# actually writes it to Supabase — placed here, right after `username`
# becomes available, rather than inside page_profile() itself, because
# the reload is a real page load like the OAuth one above and does NOT
# preserve which section the person was on; handling it globally means
# it works no matter which section they land back on.
if st.query_params.get("push_endpoint"):
    _pe = st.query_params.get("push_endpoint")
    _pp = st.query_params.get("push_p256dh")
    _pa = st.query_params.get("push_auth")
    for _k in ("push_endpoint", "push_p256dh", "push_auth"):
        if _k in st.query_params:
            del st.query_params[_k]
    if save_push_subscription(username, _pe, _pp, _pa):
        st.toast("🔔 Push notifications enabled on this device.")
    else:
        st.toast("⚠️ Couldn't save that subscription — see error log in Owner Console.")
elif st.query_params.get("push_unsubscribed"):
    del st.query_params["push_unsubscribed"]
    try:
        supabase.table("push_subscriptions").delete().eq("username", username).execute()
    except Exception as e:
        log_error(str(e), endpoint="push_unsubscribe_callback")
    st.toast("🔕 Push notifications turned off on this device.")
elif st.query_params.get("push_error"):
    _push_err = st.query_params.get("push_error")
    del st.query_params["push_error"]
    st.toast(f"⚠️ Push notifications: {_push_err}")

# Broadcast the logged-in username to the TOP-LEVEL window via
# postMessage on every authenticated page load — not just when visiting
# the Notifications settings section (that was the earlier version;
# it meant the wrapper site never learned who was logged in unless
# someone happened to open that specific page). Harmless whether or
# not this is actually embedded in the wrapper site's iframe (if
# accessed directly, window.top is just window itself, so this only
# ever messages its own page).
# window.top specifically, not window.parent: st.iframe() renders this
# in its OWN nested iframe, so the actual structure is wrapper page ->
# iframe -> Streamlit app -> another iframe (this one) -> this code.
# window.parent from here only reaches the Streamlit app's own window,
# one level up — never the wrapper page two levels up. window.top
# always reaches the outermost window regardless of how many iframe
# layers sit in between, which is what actually gets this message
# where it needs to go. This is what lets the WRAPPER SITE know who's
# logged in, since it has no login of its own — the wrapper is what
# actually registers the push subscription, not this app directly.
# See PUSH_NOTIFICATIONS_SETUP.md for more.
_uname_js = username.replace("'", "\\'")
st.iframe(
    "<script>"
    f"try {{ window.top.postMessage({{type: 'mwdts-user', username: '{_uname_js}'}}, '*'); }} catch (e) {{}}"
    "</script>",
    height=1,  # st.iframe rejects height=0 outright (StreamlitInvalidHeightError,
               # unlike the old components.html which allowed it) — 1px is visually
               # identical to invisible and is the smallest value validate_height accepts.
)

